(window.WCD=window.WCD||[]).push(["chansons",[["Q205891",1,"chanson","'O sole mio","C","'O sole mio est une chanson d'amour napolitaine composée par les napolitains Eduardo di Capua et Alfredo Mazzucchi en 1898, avec des paroles de Giovanni Capurro. Elle est enregistrée pour la première fois par le ténor italien Giuseppe Anselmi en 1907, et devient une des chansons italiennes et napolitaines les plus célèbres du monde avec ses reprises par le ténor Enrico Caruso en 1916, Mario Lanza pour le film Le Grand Caruso de 1951, ou encore Elvis Presley avec sa version It's Now or Never de 1960.",117,"fr:'O_sole_mio","c:3/32/%27o_sole_mio_1898.JPG"],["Q158553",2,"chanson","(I Can't Get No) Satisfaction","PC","Satisfaction est une chanson du groupe de rock The Rolling Stones, enregistrée entre les 10 et 13 mai 1965.",null,"fr:(I_Can't_Get_No)_Satisfaction","https://upload.wikimedia.org/wikipedia/en/thumb/7/7f/Satisfaction-us.jpg/330px-Satisfaction-us.jpg"],["Q277342",3,"chanson","99 Luftballons","R","99 Luftballons est une chanson engagée contre la guerre froide du groupe pop rock ouest-allemand Nena, sortie en 1983, interprétée par la chanteuse éponyme. Elle est un succès international.",118,"fr:99_Luftballons","https://upload.wikimedia.org/wikipedia/en/thumb/4/40/99_Luftballons_single_cover.jpg/330px-99_Luftballons_single_cover.jpg"],["Q132120763",4,"chanson","Abracadabra","C","Abracadabra est une chanson de l'autrice-compositrice-interprète américaine Lady Gaga, sortie le 3 février 2025 en tant que troisième extrait de son septième album studio, Mayhem.",119,"fr:Abracadabra_(chanson_de_Lady_Gaga)","https://upload.wikimedia.org/wikipedia/en/thumb/0/04/Lady_Gaga_-_Abracadabra.png/330px-Lady_Gaga_-_Abracadabra.png"],["Q383842",5,"chanson","Africa","PC","Africa est une chanson du groupe de rock américain Toto, le dixième et dernier titre de leur quatrième album studio Toto IV. Elle est sortie en single en octobre 1982 aux États-Unis sous le label Columbia Records. Elle est écrite et composée par les membres du groupe David Paich et Jeff Porcaro, produite par le groupe et mixée par l'ingénieur du son Elliot Scheiner.",115,"fr:Africa_(chanson_de_Toto)","https://upload.wikimedia.org/wikipedia/en/thumb/1/1f/Toto_-_Africa.jpg/330px-Toto_-_Africa.jpg"],["Q2834251",6,"chanson","Alexandrie Alexandra","C","Alexandrie Alexandra est une chanson disco composée en 1977 par Jean-Pierre Bourtayre et Claude François, sur des paroles écrites par Étienne Roda-Gil, et interprétée par Claude François.",113,"fr:Alexandrie_Alexandra","c:2/23/Claude_Fran%C3%A7ois_%281976%29_by_Erling_Mandelmann_-_3.jpg"],["Q653991",7,"chanson","All I Want for Christmas Is You","PC","All I Want for Christmas Is You est une chanson de Mariah Carey présente sur son album Merry Christmas. Elle en est le premier single, sorti le 1er novembre 1994, sous le label Columbia Records. La chanson est écrite et produite par Carey et Walter Afanasieff. La chanson inclut des sons de cloches, des chœurs et l'utilisation de synthétiseurs. Les paroles déclarent que la protagoniste ne veut pas de cadeaux à Noël mais veut partager ses vacances avec son amoureux.","All I Want for Christmas Is You est une chanson de Mariah Carey présente sur son album Merry Christmas.","fr:All_I_Want_for_Christmas_Is_You","c:d/da/Mariah_Carey_Library_of_Congress_2023_%2853600169902%29_%28cropped_3%29.jpg"],["Q2838711",8,"chanson","Allumer le feu","C","Allumer le feu est une chanson de Johnny Hallyday écrite par Zazie et composée par Pascal Obispo et Pierre Jaconelli. Troisième extrait de l'album Ce que je sais, Allumer le feu sort en single en juin 1998. À l'automne de la même année, la chanson est l'un des moments forts des concerts de Johnny Hallyday au Stade de France et devient un incontournable à la scène du répertoire du chanteur.","Allumer le feu est une chanson de Johnny Hallyday écrite par Zazie et composée par Pascal Obispo et Pierre Jaconelli.","fr:Allumer_le_feu",""],["Q708698",9,"chanson","Alors on danse","C","Alors on danse est une chanson du chanteur belge Stromae. Elle est issue de l'album Cheese, qui est sorti le 21 juin 2010 soit un an après la sortie du single. Elle a été la première chanson de Stromae à être diffusée en tant que clip à la télévision. La chanson rencontre un grand succès à travers l'Europe. La chanson a fait l'objet de nombreux remixes.","Alors on danse est une chanson du chanteur belge Stromae.","fr:Alors_on_danse","https://upload.wikimedia.org/wikipedia/en/thumb/1/1d/Alors_on_danse.jpg/330px-Alors_on_danse.jpg"],["Q210211",10,"chanson","Amazing Grace","R","Amazing Grace est l'un des cantiques chrétiens les plus célèbres dans le monde anglophone. La première publication des paroles date de 1779. Associé à diverses mélodies au fil des années, il est aujourd'hui interprété sur la musique de New Britain.","Amazing Grace est l'un des cantiques chrétiens les plus célèbres dans le monde anglophone.","fr:Amazing_Grace","c:c/c1/Amazing_grace_in_OlneyHymns1779.jpg"],["Q122781",11,"chanson","Amsterdam","C","Amsterdam est une chanson de Jacques Brel. L'auteur-compositeur-interprète la crée en 1964 sur la scène de l'Olympia de Paris. Elle est éditée aux disques la même année, sur un super 45 tours proposant trois titres inédits créés pour l'occasion et extraits de l'album enregistré en public Olympia 1964.","Amsterdam est une chanson de Jacques Brel.","fr:Amsterdam_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/9/94/Jacques_Brel-Amsterdam_%281966_single_cover%29.jpg/330px-Jacques_Brel-Amsterdam_%281966_single_cover%29.jpg"],["Q18636033",12,"chanson","Andalouse","C","Andalouse est une chanson du chanteur français Kendji Girac parue sur son premier album Kendji. Elle est écrite par Rachid Mir, Christian Dessart et Nazim Khaled, étant produit par The Bionix. Elle est sortie le 18 août 2014 comme deuxième single de l'album.","Andalouse est une chanson du chanteur français Kendji Girac parue sur son premier album Kendji.","fr:Andalouse_(chanson)",""],["Q567940",13,"chanson","Another Brick in the Wall","PC","Another Brick in the Wall est un des titres les plus célèbres de Pink Floyd, composé par Roger Waters autour d'un même thème musical. Les trois parties figurent sur l'album The Wall paru le 30 novembre 1979. Respectivement sous-titrées Part 1, Part 2 et Part 3, ces chansons sont importantes dans le concept de l'album, puisqu'elles marquent la construction du mur derrière lequel s'enferme Pink, le personnage principal de l'album.",118,"fr:Another_Brick_in_the_Wall","https://upload.wikimedia.org/wikipedia/en/thumb/c/cb/PinkFloydAnotherBrickCover.jpg/330px-PinkFloydAnotherBrickCover.jpg",{"cats":["chansons","groupes"]}],["Q568065",14,"chanson","Another One Bites the Dust","PC","Another One Bites the Dust est une chanson du groupe de rock britannique Queen, sortie sur leur 8e album studio, The Game, en 1980, puis en single la même année.",116,"fr:Another_One_Bites_the_Dust","https://upload.wikimedia.org/wikipedia/en/thumb/4/4d/Another_one_bites_the_dust.jpg/330px-Another_one_bites_the_dust.jpg"],["Q2853393",15,"chanson","Antisocial","C","Antisocial est une chanson du groupe de hard rock français Trust. Elle est parue sur le deuxième album de Trust, Répression, en 1980.","Antisocial est une chanson du groupe de hard rock français Trust.","fr:Antisocial_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/c/c6/Antisocial_Trust_single_cover.jpg/330px-Antisocial_Trust_single_cover.jpg",{"cats":["chansons","groupes"]}],["Q2457967",16,"chanson","Around the World","C","Around the World est un morceau du groupe français de musique électronique Daft Punk. Apparu sur le premier album du duo, Homework, en 1997, il a fait l'objet d'un single la même année. Il a par la suite connu un grand succès en club à travers le monde, arrivant à la première place dans certains classements. Around the World est connu pour la répétition de son titre pendant le morceau, ainsi que pour son clip décalé réalisé par Michel Gondry.","Around the World est un morceau du groupe français de musique électronique Daft Punk.","fr:Around_the_World_(chanson_de_Daft_Punk)","c:0/02/Homework_daftpunk.jpg",{"cats":["chansons","electro"]}],["Q111397510",17,"chanson","As It Was","C","As It Was est une chanson du chanteur anglais Harry Styles sortie le 1er avril 2022 sous les labels Erskine et Columbia Records, en tant que premier single de son troisième album Harry's House.",119,"fr:As_It_Was","https://upload.wikimedia.org/wikipedia/en/thumb/f/ff/Harry_Styles_-_As_It_Was.png/330px-Harry_Styles_-_As_It_Was.png"],["Q211939",18,"chanson","Auld Lang Syne","E","Auld Lang Syne, chanson écossaise plus connue des francophones sous le nom de Ce n'est qu'un au revoir, signifie en scots « Depuis longtemps », « Les jours passés d'il y a longtemps », « Les jours d'antan », ou aussi « L'amitié de vieille date ». En français et en anglais, ce chant est souvent repris à la nouvelle année et autres grandes fêtes ou à la fin de réunions amicales ou cultuelles.",115,"fr:Auld_Lang_Syne","c:f/f7/Auld_Lang_Syne_manuscript_1.jpg"],["Q794635",19,"chanson","Aïcha","C","Aïcha est une chanson franco-algérienne écrite par Jean-Jacques Goldman pour le chanteur de raï algérien Khaled, et sortie en 1996.",115,"fr:Aïcha_(chanson)","c:4/4a/Cheb_Khaled_performed_in_Oran_on_July_5th_2011.jpg"],["Q48791055",20,"chanson","Baby Shark","PC","Baby Shark est une chanson enfantine au sujet d'une famille de requins, qui a connu un succès viral sur les réseaux sociaux.",115,"fr:Baby_Shark","c:b/bc/Baby_shark_dance%2C_Andersen.jpg",{"cats":["chansons","divers"]}],["Q275422",21,"chanson","Bad","PC","Bad est une chanson de Michael Jackson \"le roi de la pop\". Écrite et composée par Jackson, coproduite avec Quincy Jones, elle sort en single le 7 septembre 1987.","Bad est une chanson de Michael Jackson \"le roi de la pop\".","fr:Bad_(chanson_de_Michael_Jackson)","c:f/f6/BadlogoMJ.png"],["Q62618893",22,"chanson","Bad Guy","C","Bad Guy est une chanson de l'auteure-compositrice-interprète américaine Billie Eilish publiée le 29 mars 2019 par les labels Dark Room et Interscope Records et produite par Finneas O'Connell. Il s'agit du cinquième single extrait de When We All Fall Asleep, Where Do We Go?, le premier album studio de la chanteuse. Décrit comme une chanson pop-trap et nu-goth, Bad Guy présente une instrumentale minimaliste fournie par une basse synthé, une grosse caisse, des frappes au doigt et une basse 808.",117,"fr:Bad_Guy_(chanson_de_Billie_Eilish)","c:b/b1/Billie_Eilish_%40Pukkelpop_2019_%2848590443241%29.jpg"],["Q153064",23,"chanson","Bad Romance","C","Bad Romance est une chanson de l’artiste américaine Lady Gaga. Il s’agit du premier single issu de son deuxième album studio, The Fame Monster. Le morceau est produit par le producteur marocain RedOne. Il est inspiré de la paranoïa que Gaga a vécue lors de sa première tournée, au début de 2009. Après le piratage de la version démo du morceau, Gaga interprète pour la première fois la chanson, lors de la semaine parisienne de la mode, au défilé printemps/été du styliste Alexander McQueen, le 6 octobre 2009.","Bad Romance est une chanson de l’artiste américaine Lady Gaga.","fr:Bad_Romance","https://upload.wikimedia.org/wikipedia/en/thumb/c/cc/Lady_Gaga_-_Bad_Romance.png/330px-Lady_Gaga_-_Bad_Romance.png"],["Q63196661",24,"chanson","Balance ton quoi","C","Balance ton quoi est une chanson féministe de l'autrice-compositrice-interprète belge Angèle. Sortie le 5 octobre 2018 en tant que sixième single de son premier album Brol, elle dénonce le sexisme. Le titre fait référence au mouvement #BalanceTonPorc.","Balance ton quoi est une chanson féministe de l'autrice-compositrice-interprète belge Angèle.","fr:Balance_ton_quoi","c:a/a8/Festival_des_Vieilles_Charrues_2018_-_Ang%C3%A8le_-_014.jpg"],["Q101696002",25,"chanson","Bande organisée","C","Bande organisée est une chanson de rap français sortie le 15 août 2020 en tant que premier single de l'album collectif 13 Organisé. Elle est interprétée par plusieurs rappeurs originaires de Marseille: Jul, SCH, Kofs, Naps, Soso Maness, Elams, Solda et Houari.",118,"fr:Bande_organisée_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/8/81/Jul_-_Bande_organis%C3%A9e.png/330px-Jul_-_Bande_organis%C3%A9e.png"],["Q138666487",26,"chanson","Bangaranga","C","Bangaranga est une chanson de la chanteuse bulgare Dara, sortie le 2 mars 2026. Produite par le producteur roumain Monoir, elle a représenté la Bulgarie au Concours Eurovision de la chanson 2026, qu'elle remporte avec 516 points.","Bangaranga est une chanson de la chanteuse bulgare Dara, sortie le 2 mars 2026.","fr:Bangaranga","c:3/39/ESC_2026_final_2026-05-17_3219_BG_Dara_%28cropped%29.jpg"],["Q790315",27,"chanson","Barbie Girl","C","Barbie Girl est une chanson du groupe scandinave Aqua, sortie en 1997, qui est leur troisième single et leur premier titre à sortir au Royaume-Uni et en France. La chanson fait partie de l'album Aquarium et a été écrite par Claus Norreen et Søren Nystrøm Rasted après que le groupe a vu une exposition sur la culture kitsch.",116,"fr:Barbie_Girl","https://upload.wikimedia.org/wikipedia/en/thumb/4/4c/Aquabarbie.jpg/330px-Aquabarbie.jpg"],["Q42884399",28,"chanson","Basique","C","Basique est un single musical du rappeur français Orelsan sorti le 20 septembre 2017. C'est avec le clip vidéo de cette chanson que le rappeur annonce la date de sortie de son album La fête est finie.","Basique est un single musical du rappeur français Orelsan sorti le 20 septembre 2017.","fr:Basique_(chanson)",""],["Q210218",29,"chanson","Beat It","R","Beat It est une chanson de Michael Jackson, tirée de l'album Thriller. Écrite et composée par Jackson, coproduite avec Quincy Jones, elle est le 3e single extrait de cet album.","Beat It est une chanson de Michael Jackson, tirée de l'album Thriller.","fr:Beat_It","c:3/3a/%C2%ABBeat_It%C2%BB_vinyl_single_text.png"],["Q124422481",30,"chanson","Beautiful Things","C","Beautiful Things est une chanson du chanteur américain Benson Boone, sortie en janvier 2024. Ce tube planétaire a lancé son premier album Fireworks & Rollerblades.","","en:Beautiful_Things_(Benson_Boone_song)","https://upload.wikimedia.org/wikipedia/en/thumb/4/4b/Benson_Boone_-_Beautiful_Things.png/330px-Benson_Boone_-_Beautiful_Things.png"],["Q28737603",31,"chanson","Believer","C","Believer est une chanson du groupe de pop rock américain Imagine Dragons, sortie en tant que premier single de leur troisième album studio Evolve le 1er février 2017, publié par Interscope Records et KIDinaKORNER. Cette chanson a été écrite par Dan Reynolds, Wayne Sermon, Ben McKee, Daniel Platzman, Justin Tranter et leurs producteurs Mattman & Robin.",115,"fr:Believer_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/5/5c/Imagine-Dragons-Believer-art.jpg/330px-Imagine-Dragons-Believer-art.jpg",{"cats":["chansons","groupes"]}],["Q159633",32,"chanson","Bella ciao","E","Bella ciao est un chant de révolte italien révolutionnaire qui célèbre l'engagement dans le combat mené par les partisans, résistants pendant la Seconde Guerre mondiale opposés aux troupes allemandes alliées de la République sociale italienne fasciste, au cours de la guerre civile italienne.",111,"fr:Bella_ciao_(chant)","c:8/8e/Bandiera_giustizia_e_liberta.jpg"],["Q16034877",33,"chanson","Belle-Île-en-Mer, Marie-Galante","C","Belle-Île-en-Mer, Marie-Galante, aussi appelée simplement Belle-Île-en-Mer, est une chanson de Laurent Voulzy. Elle est sortie en single en 1986.","Belle-Île-en-Mer, Marie-Galante, aussi appelée simplement Belle-Île-en-Mer, est une chanson de Laurent Voulzy.","fr:Belle-Île-en-Mer,_Marie-Galante",""],["Q193319",34,"chanson","Billie Jean","R","Billie Jean est une chanson écrite et composée par Michael Jackson, parue dans l'album Thriller en 1982, puis sortie en single le 2 janvier 1983. Dès sa sortie, Billie Jean est un succès commercial considérable, se classant dans les premières places de nombreux hit-parades à travers le monde. Le titre reste ainsi sept semaines d'affilée en tête du Billboard Hot 100 et neuf semaines en tête du Hot R&B/Hip-Hop Songs aux États-Unis.",119,"fr:Billie_Jean","https://upload.wikimedia.org/wikipedia/commons/thumb/6/63/Billie_Jean_logo.svg/330px-Billie_Jean_logo.svg.png"],["Q126721841",35,"chanson","Birds of a Feather","C","Birds of a Feather est une chanson de l'auteure-compositrice-interprète américaine Billie Eilish tirée de son troisième album studio, Hit Me Hard and Soft. La chanson est sortie en tant que deuxième single de l'album le 2 juillet 2024, via Darkroom et Interscope Records. Billie Eilish a écrit la chanson avec son frère Finneas O'Connell, qui l'a enregistrée et produite dans son home studio à Los Angeles.",119,"fr:Birds_of_a_Feather_(chanson_de_Billie_Eilish)","c:c/c7/BillieEilishO2140725-39_-_54665577407_%28cropped%29.jpg"],["Q76566134",36,"chanson","Blinding Lights","PC","Blinding Lights est une chanson du chanteur canadien The Weeknd sortie le 29 novembre 2019 comme deuxième single de son quatrième album After Hours. Il s’agit à ce jour de la chanson la plus écoutée sur Spotify depuis le lancement de cette plateforme.",119,"fr:Blinding_Lights","https://upload.wikimedia.org/wikipedia/en/thumb/e/e6/The_Weeknd_-_Blinding_Lights.png/330px-The_Weeknd_-_Blinding_Lights.png"],["Q696600",37,"chanson","Blue","PC","Blue est une chanson interprétée par le groupe italien Eiffel 65 sur leur premier single, extrait de leur premier album Europop,",119,"fr:Blue_(Da_Ba_Dee)","https://upload.wikimedia.org/wikipedia/en/thumb/6/63/Eiffel_65_blue_cover.png/330px-Eiffel_65_blue_cover.png",{"cats":["chansons","electro"]}],["Q187745",38,"chanson","Bohemian Rhapsody","E","Bohemian Rhapsody est une chanson écrite par Freddie Mercury, enregistrée par le groupe de rock britannique Queen pour l'album A Night at the Opera, sorti en 1975. La chanson, qui adopte le style opératique, repose sur une structure assez inhabituelle pour un titre de musique rock: découpée en six parties, elle est dépourvue de refrain et comporte des arrangements tantôt a cappella, tantôt hard rock.",118,"fr:Bohemian_Rhapsody","c:b/bd/Bohemian_Rhapsody_by_Queen_US_vinyl_red_label.png",{"cats":["chansons","groupes"]}],["Q391180",39,"chanson","Bésame mucho","C","Bésame mucho est une chanson de variété écrite et composée en 1932 par la pianiste mexicaine Consuelo Velázquez d'après une aria d'Enrique Granados. Ce boléro en do mineur est devenu la chanson en espagnol la plus reprise du XXe siècle.",119,"fr:Bésame_mucho",""],["Q1990281",40,"chanson","California Love","C","California Love est une chanson du rappeur 2Pac avec Dr. Dre et Roger Troutman.","California Love est une chanson du rappeur 2Pac avec Dr.","fr:California_Love","c:d/db/California_Love_%281995%29%2C_by_Tupac_Shakur.png"],["Q326835",41,"chanson","Call Me Maybe","PC","Call Me Maybe est une chanson de la chanteuse canadienne Carly Rae Jepsen extraite de son maxi Curiosity, sorti en 2012. La chanson est sortie en tant que 1er single du maxi le 20 septembre 2011. Elle a été écrite par Carly Rae Jepsen, Josh Ramsay et Tavish Crowe. Après les jeunes chanteurs de musique pop, Justin Bieber et Selena Gomez, c'est au tour de Carly Rae Jepsen d'attirer la scène internationale, elle signe pour le label Schoolboy Records qui sort son single aux États-Unis.","Call Me Maybe est une chanson de la chanteuse canadienne Carly Rae Jepsen extraite de son maxi Curiosity, sorti en 2012.","fr:Call_Me_Maybe","c:5/52/CallMeMaybe.png"],["Q155029",42,"chanson","Can't Get You Out of My Head","C","Can't Get You Out of My Head est une chanson de Kylie Minogue sortie en 2001, incluse dans son huitième album Fever. Elle a été écrite et produite par Cathy Dennis et Rob Davis. Classée numéro un dans 40 pays, elle est souvent considérée comme la chanson phare de la chanteuse. Il s'agit de son single le plus vendu. Elle est considérée comme la chanson la plus écoutée de la décennie 2000 au Royaume-Uni.","Can't Get You Out of My Head est une chanson de Kylie Minogue sortie en 2001, incluse dans son huitième album Fever.","fr:Can't_Get_You_Out_of_My_Head","https://upload.wikimedia.org/wikipedia/en/thumb/6/60/Kylie_Minogue_-_Can%27t_Get_You_Out_of_My_Head.png/330px-Kylie_Minogue_-_Can%27t_Get_You_Out_of_My_Head.png"],["Q651472",43,"chanson","Careless Whisper","R","Careless Whisper est la première chanson en solo de l'auteur-compositeur-interprète et producteur anglais George Michael. Écrite en 1981 par celui-ci avec la complicité d'Andrew Ridgeley, l'autre membre du groupe de musique pop Wham!, elle est enregistrée aux studios SARM West de Londres en octobre 1983. Le single sort en juillet 1984 au Royaume-Uni, sous le label discographique Epic. Trois mois plus tard, l'œuvre musicale apparaît parmi les titres de l'album Make It Big de Wham!.",112,"fr:Careless_Whisper","https://upload.wikimedia.org/wikipedia/en/thumb/1/10/Careless_Whisper_UK_single.jpg/330px-Careless_Whisper_UK_single.jpg"],["Q2946985",44,"chanson","Ces soirées-là","C","Ces soirées-là est une chanson enregistrée par le chanteur Yannick. Ce morceau, sorti en mars 2000, est le deuxième single issu de son premier album C'est ça qu'on aime. Il est fondé sur la chanson Cette année-là de Claude François, elle-même adaptée d'après la chanson December, 1963 du groupe The Four Seasons sortie un an plus tôt. Le titre a connu en France un grand succès.","Ces soirées-là est une chanson enregistrée par le chanteur Yannick.","fr:Ces_soirées-là","c:0/0e/Tendance_live_show-saint_l%C3%B4-21_juin_2009-Yannick-011.JPG"],["Q16028874",45,"chanson","Chandelier","C","Chandelier est une chanson de l'auteure-compositrice-interprète australienne Sia, premier extrait de son sixième album studio 1000 Forms of Fear, sorti en 2014.",118,"fr:Chandelier_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/3/32/Sia_Chandelier.png/330px-Sia_Chandelier.png"],["Q109026",46,"chanson","Circle of Life","C","Circle of Life est une chanson composée par Elton John, sur des paroles de Tim Rice, pour le long métrage d'animation des studios Disney, Le Roi lion. Elle évoque le cycle de la vie.",117,"fr:Circle_of_Life","https://upload.wikimedia.org/wikipedia/en/thumb/8/88/Circle_of_Life_by_Elton_John_%28European_variant%29.png/330px-Circle_of_Life_by_Elton_John_%28European_variant%29.png"],["Q7888907",47,"chanson","Comme d'habitude","C","Comme d’habitude est une chanson écrite par Gilles Thibaut et Claude François, sur une musique composée par Jacques Revaux et Claude François, sortie en novembre 1967.",115,"fr:Comme_d'habitude","https://upload.wikimedia.org/wikipedia/en/thumb/9/95/Claude_Fran%C3%A7ois_%E2%80%93_Comme_D%27habitude.png/330px-Claude_Fran%C3%A7ois_%E2%80%93_Comme_D%27habitude.png"],["Q153202",48,"chanson","Con te partirò","PC","Con te partirò est une chanson italienne interprétée par Andrea Bocelli, écrite par Francesco Sartori pour la musique et Lucio Quarantotto pour les paroles. Andrea Bocelli l'a chantée pour la première fois en 1995 au festival de Sanremo. Elle a connu depuis un véritable succès international.",117,"fr:Con_te_partirò","https://upload.wikimedia.org/wikipedia/en/thumb/c/c9/Con_te_partir%C3%B2.png/330px-Con_te_partir%C3%B2.png"],["Q16034920",49,"chanson","Couleur Café","C","Couleur Café est une chanson de Serge Gainsbourg, parue en single en 1964. Vingt-quatre ans plus tard, une version live enregistrée au Zénith de Paris est parue en single.","Couleur Café est une chanson de Serge Gainsbourg, parue en single en 1964.","fr:Couleur_Café",""],["Q148511",50,"chanson","Crazy in Love","C","Crazy in Love est une chanson de la chanteuse américaine de RnB contemporain Beyoncé avec la participation du rappeur américain Jay-Z. Ces derniers et le producteur Rich Harrison ont écrit cette chanson pour le premier album solo de la chanteuse: Dangerously in Love. Elle sort le 14 mai 2003, chez Columbia, en premier single extrait de l'album. Crazy in Love est une chanson d'amour contenant un échantillon tiré de Are You My Woman, par les Chi-Lites, qui sert d'accroche.",117,"fr:Crazy_in_Love","c:3/36/Beyonce_and_Jay-z_2018_%282%29.jpg"],["Q67184416",51,"chanson","Cruel Summer","C","Cruel Summer est une chanson de l'auteure-compositrice-interprète américaine Taylor Swift issue de son septième album studio Lover sorti en 2019.",117,"fr:Cruel_Summer_(chanson_de_Taylor_Swift)","c:b/b3/Taylor_Swift_performing_%22Cruel_Summer%22_on_The_Eras_Tour_%28Tampa%2C_FL_-_Raymond_Jaymes_Stadium_-_April_2023%29.jpg"],["Q65071242",52,"chanson","Dance Monkey","C","Dance Monkey est le 2e single de la chanteuse australienne Tones and I. La chanson est écrite par Toni Watson et produite par Konstantin Kersting.","Dance Monkey est le 2e single de la chanteuse australienne Tones and I.","fr:Dance_Monkey","https://upload.wikimedia.org/wikipedia/en/thumb/1/1f/Dance_Monkey_by_Tones_and_I.jpg/330px-Dance_Monkey_by_Tones_and_I.jpg"],["Q870786",53,"chanson","Dancing Queen","PC","Dancing Queen est une chanson du groupe de pop suédois ABBA, sortie en single en 1976. C'est l'un des tubes les plus emblématiques du groupe et plus largement de l'ère disco. Ce titre connaît un regain de popularité en 1994 lors de la sortie de deux films australiens qui l'utilisent dans leur bande-son: Priscilla, folle du désert et Muriel.","Dancing Queen est une chanson du groupe de pop suédois ABBA, sortie en single en 1976.","fr:Dancing_Queen","c:3/3e/Agnetha_F%C3%A4ltskog_and_Anni-Frid_Lyngstad_in_G%C3%B6teborg_1979.jpg"],["Q15640702",54,"chanson","Dernière Danse","C","Dernière Danse est une chanson écrite et interprétée par Indila, et composée par Indila et Skalpovich. C'est le premier single en solo de la chanteuse, extrait de son premier album Mini World.","Dernière Danse est une chanson écrite et interprétée par Indila, et composée par Indila et Skalpovich.","fr:Dernière_Danse_(chanson_d'Indila)","https://upload.wikimedia.org/wikipedia/en/thumb/b/b1/Derniere_danse_cover.png/330px-Derniere_danse_cover.png"],["Q28572509",55,"chanson","Despacito","PC","Despacito est un single du musicien portoricain Luis Fonsi en duo avec Daddy Yankee, dont le featuring de Justin Bieber a dopé les records mondiaux de classement sur Internet.",119,"fr:Despacito","https://upload.wikimedia.org/wikipedia/en/thumb/c/c8/Luis_Fonsi_Feat._Daddy_Yankee_-_Despacito_%28Official_Single_Cover%29.png/330px-Luis_Fonsi_Feat._Daddy_Yankee_-_Despacito_%28Official_Single_Cover%29.png"],["Q74038",56,"chanson","Diamonds","C","Diamonds est une chanson interprétée par l'artiste barbadienne Rihanna sortie le 9 novembre 2012 sous le label Def Jam, et extraite de son 7e album studio Unapologetic. Le texte est signé Sia Furler, qui n'a mis que 14 minutes pour l'écrire, tandis que la musique a été réalisée par Benny Blanco et le duo StarGate.",119,"fr:Diamonds_(chanson_de_Rihanna)","c:c/c5/Rihanna.png"],["Q129169212",57,"chanson","Die with a Smile","PC","Die with a Smile est une chanson des auteurs-compositeurs-interprètes américains Lady Gaga et Bruno Mars, sortie le 16 août 2024, extraite du septième album de Gaga Mayhem paru le 7 mars 2025 via le label Interscope Records.",118,"fr:Die_with_a_Smile","https://upload.wikimedia.org/wikipedia/en/thumb/1/12/Lady_Gaga_and_Bruno_Mars_-_Die_with_a_Smile.png/330px-Lady_Gaga_and_Bruno_Mars_-_Die_with_a_Smile.png"],["Q55596661",58,"chanson","Djadja","C","Djadja est une chanson de la chanteuse franco-malienne Aya Nakamura, sortie le 6 avril 2018.",null,"fr:Djadja","c:b/b1/Aya_Nakamura_IMG_4756_%28cropped%29.jpg"],["Q1814600",59,"chanson","Dominique","C","Dominique est une chanson de langue française de l'artiste belge Sœur Sourire sortie en 1962. Elle est dédiée à Dominique de Guzmán, fondateur de l'ordre dominicain dont Sœur Sourire fait partie au début des années 1960.","Dominique est une chanson de langue française de l'artiste belge Sœur Sourire sortie en 1962.","fr:Dominique_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/1/14/Dominique_-_The_Singing_Nun.jpg/330px-Dominique_-_The_Singing_Nun.jpg"],["Q262417",60,"chanson","Don't Stop Me Now","C","Don't Stop Me Now est une chanson du groupe britannique Queen, sortie en single en 1979. Écrite par Freddie Mercury, elle est extraite de l'album Jazz sorti l'année précédente.","Don't Stop Me Now est une chanson du groupe britannique Queen, sortie en single en 1979.","fr:Don't_Stop_Me_Now","https://upload.wikimedia.org/wikipedia/en/thumb/9/97/Queen-dont-stop-me-now-1979-6-s.jpg/330px-Queen-dont-stop-me-now-1979-6-s.jpg",{"cats":["chansons","groupes"]}],["Q3037828",61,"chanson","Douce France","C","Douce France est une chanson française écrite et interprétée par Charles Trenet en 1943, composée avec Léo Chauliac, et enregistrée en 1947 en single chez Columbia, un des grands succès de son répertoire et de la chanson française.",119,"fr:Douce_France_(chanson)","c:0/04/Trenet_jeune.jpg"],["Q172152",62,"chanson","Douce nuit, sainte nuit","PC","Douce nuit, sainte nuit est l'un des chants de Noël les plus célèbres au monde représentant Noël dans l'espace germanophone. Il est chanté pour la première fois à la veille de Noël 1818 dans l'église Saint-Nicolas à la ville autrichienne d'Oberndorf bei Salzburg. Depuis mars 2011, Douce nuit, sainte nuit appartient au patrimoine culturel immatériel de l'humanité reconnu par l'UNESCO.",110,"fr:Douce_nuit,_sainte_nuit","c:5/5f/Chapel2.jpg"],["Q161407",63,"chanson","Dragostea din tei","R","Dragostea din tei, ou DDT, est une chanson du groupe moldave O-Zone, chantée en roumain. Le titre signifie, mot à mot, « L'amour venu du tilleul », qui n'a pas vraiment de sens. Il s'agirait d'un jeu de mots avec « Dragostea dintâi », qui signifie « Le premier amour ». Elle est connue notamment pour son refrain « nu mă, nu mă iei » qui signifie « tu ne me, tu ne m'emmènes pas ».","Dragostea din tei, ou DDT, est une chanson du groupe moldave O-Zone, chantée en roumain.","fr:Dragostea_din_tei","https://upload.wikimedia.org/wikipedia/en/thumb/d/d3/DragonsWhateverCover.jpg/330px-DragonsWhateverCover.jpg",{"cats":["chansons","electro"]}],["Q753118",64,"chanson","Du hast","C","Du hast est une chanson du groupe allemand Rammstein tirée de l'album Sehnsucht de 1997.",null,"fr:Du_hast","https://upload.wikimedia.org/wikipedia/en/thumb/1/1a/Du_hast.jpg/330px-Du_hast.jpg",{"cats":["chansons","groupes"]}],["Q2576448",65,"chanson","Désenchantée","C","Désenchantée est une chanson de Mylène Farmer, sortie le 18 mars 1991 en tant que premier extrait de son troisième album, L'Autre….",114,"fr:Désenchantée","c:f/f2/Logo_D%C3%A9senchant%C3%A9e.jpg"],["Q164599",66,"chanson","Earth Song","C","Earth Song est une chanson de Michael Jackson. Elle apparaît en cinquième piste sur le double album HIStory.","Earth Song est une chanson de Michael Jackson.","fr:Earth_Song","https://upload.wikimedia.org/wikipedia/fr/thumb/c/cf/Earth_Song.jpg/330px-Earth_Song.jpg"],["Q2678464",67,"chanson","Ella, elle l'a","C","Ella, elle l'a est une chanson de France Gall. Elle est sortie en single le 24 août 1987, extraite de l'album Babacar sorti en avril de la même année. Écrite et composée par Michel Berger, la chanson est un hommage à Ella Fitzgerald, elle est aussi une chanson de protestation contre le racisme et un hymne à l'autonomisation.","Ella, elle l'a est une chanson de France Gall.","fr:Ella,_elle_l'a","https://upload.wikimedia.org/wikipedia/en/thumb/0/0c/Ella_elle_l%27a.jpg/330px-Ella_elle_l%27a.jpg"],["Q2468845",68,"chanson","Elle me dit","C","Elle me dit est une chanson de Mika, sortie en single en 2011, puis sur son troisième album The Origin of Love en 2012. Ce titre dance-pop est écrit et composé par Mika et Doriand. La production est réalisée par Greg Wells et Klas Åhlund.","Elle me dit est une chanson de Mika, sortie en single en 2011, puis sur son troisième album The Origin of Love en 2012.","fr:Elle_me_dit","c:7/7b/Elle_Me_Dit_Mika.jpg"],["Q3053011",69,"chanson","Emmenez-moi","C","Emmenez-moi ou Take Me Along est une chanson française de l'auteur-compositeur-interprète Charles Aznavour, single de 1968 extrait de son album Entre deux rêves de 1967, un des plus importants succès emblématiques internationaux de sa carrière, et de la chanson française.",117,"fr:Emmenez-moi_(chanson)","c:4/43/2014.06.23._Charles_Aznavour_Fot_Mariusz_Kubik_09.jpg"],["Q3053472",70,"chanson","En apesanteur","C","En apesanteur est le 2e single issu du 2e album studio Calogero du chanteur français Calogero.",null,"fr:En_apesanteur","https://upload.wikimedia.org/wikipedia/en/thumb/6/69/En_apesanteur.jpg/330px-En_apesanteur.jpg"],["Q672508",71,"chanson","Enter Sandman","PC","Enter Sandman est une chanson du groupe de heavy metal américain Metallica. Elle est sortie en tant que premier single pour la promotion de leur cinquième album Metallica sorti en 1991. La musique a été écrite par Kirk Hammett, James Hetfield et Lars Ulrich. C'est le chanteur et guitariste rythmique Hetfield qui a écrit les paroles, qui traitent des cauchemars chez les enfants.","Enter Sandman est une chanson du groupe de heavy metal américain Metallica.","fr:Enter_Sandman","c:a/a8/Mettalica_Sonisphere_2014_in_the_United_Kingdom_26.jpg",{"cats":["chansons","groupes"]}],["Q125450571",72,"chanson","Espresso","C","Espresso est une chanson de l'auteure-compositrice-interprète américaine Sabrina Carpenter sortie en tant que single le 11 avril 2024 via le label Island Records. Il s'agit du premier et dernier extrait de l'album Short n' Sweet.",119,"fr:Espresso_(chanson_de_Sabrina_Carpenter)","c:0/00/Espresso_logo.png"],["Q163412",73,"chanson","Firework","C","Firework est une chanson de la chanteuse pop américaine Katy Perry tiré de son 3e album studio, Teenage Dream paru en 2010. La chanson écrite par Perry, Stargate, Sandy Vee, Ester Dean et produite par Stargate, Sandy Vee est sorti en tant que troisième single de l'album le 3 décembre 2010. Selon Perry, Firework est influencé par le roman de Jack Kerouac, Sur la route.",117,"fr:Firework_(chanson)","c:8/8f/Firework_Katy_Perry_2010.png"],["Q115945493",74,"chanson","Flowers","C","Flowers est une chanson de la chanteuse américaine Miley Cyrus sortie le 12 janvier 2023. Publiée au label Columbia Records, il s'agit du premier single du huitième album studio de la musicienne: Endless Summer Vacation. La chanson est un succès commercial immédiat, établissant par ailleurs un record sur Spotify en ayant été écouté plus de 101 millions de fois au cours de la première semaine d'existence du single.","Flowers est une chanson de la chanteuse américaine Miley Cyrus sortie le 12 janvier 2023.","fr:Flowers_(chanson_de_Miley_Cyrus)","c:d/d9/Miley_Cyrus_-_Flowers.png"],["Q13461348",75,"chanson","Formidable","C","Formidable est une chanson du chanteur belge Stromae, extraite de son second album studio, intitulé Racine carrée. Le titre est sorti en tant que second single de l'album le 27 mai 2013.","Formidable est une chanson du chanteur belge Stromae, extraite de son second album studio, intitulé Racine carrée.","fr:Formidable_(chanson)","c:9/99/Louise_arr%C3%AAt_de_tram.JPG"],["Q3079897",76,"chanson","Foule sentimentale","C","Foule sentimentale est une chanson écrite, composée et interprétée par Alain Souchon, extraite de l'album C'est déjà ça sorti en 1993.",119,"fr:Foule_sentimentale","https://upload.wikimedia.org/wikipedia/en/thumb/9/92/Foule_sentimentale.jpg/330px-Foule_sentimentale.jpg"],["Q1493554",77,"chanson","Gangsta's Paradise","R","Gangsta's Paradise est une chanson de rap de Coolio et L. V., présente sur la bande originale du film Esprits rebelles sorti le 9 août 1995, ainsi que sur les albums Gangsta's Paradise de Coolio et I Am L.V. de L.V., sortis en 1995 et 1996.","Gangsta's Paradise est une chanson de rap de Coolio et L.","fr:Gangsta's_Paradise_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/c/c6/Gangsta%27s_paradise.jpg/330px-Gangsta%27s_paradise.jpg"],["Q1049620",78,"chanson","Gasolina","C","Gasolina, est une chanson interprétée par Daddy Yankee extrait de son troisième album studio, Barrio fino sorti en 2004. Ce titre écrit par Raymond Ayala et Eddie Ávila est sorti en tant que second single de l'album aux États-Unis fin 2004 et en 2005 en Europe. Le titre est produit par Luny Tunes; la voix féminine qui chante « Dame más gasolina » est celle de Glory. En France, c'est la version du canadien Papa A.P.","Gasolina, est une chanson interprétée par Daddy Yankee extrait de son troisième album studio, Barrio fino sorti en 2004.","fr:Gasolina","https://upload.wikimedia.org/wikipedia/en/thumb/1/16/Daddy_Yankee_Gasolina_cover_art.png/330px-Daddy_Yankee_Gasolina_cover_art.png"],["Q11510350",79,"chanson","Get Lucky","C","Get Lucky est le premier single extrait de l'album Random Access Memories du groupe Daft Punk, coécrit et interprété en collaboration avec Pharrell Williams et Nile Rodgers.",119,"fr:Get_Lucky_(chanson_de_Daft_Punk)","https://upload.wikimedia.org/wikipedia/commons/thumb/5/5f/Daft_Punk_Get_Lucky.svg/330px-Daft_Punk_Get_Lucky.svg.png",{"cats":["chansons","electro"]}],["Q1123081",80,"chanson","Gimme! Gimme! Gimme!","C","Gimme! Gimme! Gimme!, est une chanson disco du groupe suédois ABBA. Sorti en single le 12 octobre 1979 pour promouvoir la tournée européenne et australienne du groupe de cette année. Extrait de leur compilation Greatest Hits Vol. 2, il est l'un des plus importants succès du groupe. C'est en 2025 le deuxième titre le plus écouté du groupe sur Spotify avec plus d'un milliard d'écoutes cumulées, derrière Dancing Queen.","Gimme!","fr:Gimme!_Gimme!_Gimme!_(A_Man_After_Midnight)","https://upload.wikimedia.org/wikipedia/en/thumb/a/a5/ABBA_-_Gimme%21_Gimme%21_Gimme%21_%28A_Man_After_Midnight%29.png/330px-ABBA_-_Gimme%21_Gimme%21_Gimme%21_%28A_Man_After_Midnight%29.png"],["Q969635",81,"chanson","Hallelujah","E","Hallelujah dans la Bible hébraïque et exprime l'allégresse des fidèles lors de prières ou dans des psaumes de David, est une chanson écrite par le Canadien Leonard Cohen, enregistrée pour la première fois sur son album de 1984 intitulé Various Positions.",116,"fr:Hallelujah_(chanson_de_Leonard_Cohen)","https://upload.wikimedia.org/wikipedia/en/thumb/4/45/Cohen_Hallelujah_single.jpg/330px-Cohen_Hallelujah_single.jpg"],["Q15275920",82,"chanson","Happy","C","Happy est une chanson écrite, produite et chantée par Pharrell Williams pour la bande originale du film Moi, moche et méchant 2. C'est également le 1er single extrait de son second album studio solo Girl.",117,"fr:Happy_(chanson_de_Pharrell_Williams)","https://upload.wikimedia.org/wikipedia/en/thumb/2/23/Pharrell_Williams_-_Happy.jpg/330px-Pharrell_Williams_-_Happy.jpg"],["Q1371074",83,"chanson","Harder, Better, Faster, Stronger","C","Harder, Better, Faster, Stronger est un morceau du groupe de musique électronique français Daft Punk. Sorti le 13 octobre 2001, c'est le quatrième single extrait de l'album Discovery, et également la 4e piste.","Harder, Better, Faster, Stronger est un morceau du groupe de musique électronique français Daft Punk.","fr:Harder,_Better,_Faster,_Stronger","https://upload.wikimedia.org/wikipedia/en/thumb/d/d2/Hbfs_single.jpg/330px-Hbfs_single.jpg",{"cats":["chansons","electro"]}],["Q131718",84,"chanson","Hava Nagila","PC","Hava Nagila, parfois orthographié Hava Naguila, en français, est une chanson folklorique en hébreu qui signifie « réjouissons-nous ». Elle est utilisée comme métonymie du judaïsme. Bien que la mélodie soit d'origine ancienne et populaire, les paroles ont probablement été écrites en 1918 pour célébrer la victoire britannique en Palestine pendant la Première Guerre mondiale et aussi la Déclaration Balfour de 1917.",113,"fr:Hava_Nagila","c:b/bb/PikiWiki_Israel_160_Dancing_%D7%9E%D7%94%D7%95%D7%95%D7%99_%D7%91%D7%A7%D7%99%D7%91%D7%95%D7%A5.jpg"],["Q281429",85,"chanson","Heal the World","C","Heal the World est une chanson de Michael Jackson issue de l'album Dangerous. Le single, sorti le 23 novembre 1992, est le sixième titre extrait de cet album.","Heal the World est une chanson de Michael Jackson issue de l'album Dangerous.","fr:Heal_the_World","https://upload.wikimedia.org/wikipedia/en/thumb/8/87/Michael_Jackson_-_Heal_the_World.png/330px-Michael_Jackson_-_Heal_the_World.png"],["Q21172725",86,"chanson","Hello","PC","Hello est une chanson de la chanteuse britannique Adele sortie le 23 octobre 2015. C'est le premier single issu de son troisième album 25, paru le 20 novembre 2015.","Hello est une chanson de la chanteuse britannique Adele sortie le 23 octobre 2015.","fr:Hello_(chanson_d'Adele)","https://upload.wikimedia.org/wikipedia/en/thumb/8/85/Adele_-_Hello_%28Official_Single_Cover%29.png/330px-Adele_-_Hello_%28Official_Single_Cover%29.png"],["Q3135026",87,"chanson","Hexagone","C","Hexagone est une chanson de Renaud, parue en 1975 dans l'album Amoureux de Paname.",null,"fr:Hexagone_(chanson)",""],["Q607742",88,"chanson","Hey Jude","R","Hey Jude est une chanson des Beatles parue en single le 26 août 1968 aux États-Unis et quatre jours plus tard au Royaume-Uni, avec Revolution de John Lennon en face B. C’est le premier disque des Beatles publié sous leur propre label, Apple Records. Composée par le seul Paul McCartney — mais créditée Lennon/McCartney, comme pour toutes les chansons du groupe composées par l’un ou l’autre —, Hey Jude était destinée à soutenir Julian Lennon, le fils de John, lors du divorce de ses parents.",112,"fr:Hey_Jude","c:5/5b/Memo_called_Paul_McCartney%27s_%27Hey_Jude%27_lyrics.jpg"],["Q1780500",89,"chanson","Hips Don't Lie","C","Hips Don't Lie est une chanson interprétée par Shakira et Wyclef Jean. Elle figure sur l'album Oral Fixation Vol. 2 de Shakira. Elle a été inspirée par une chanson de Dirty Dancing 2: Wyclef Jean l'avait notamment interprétée avec Claudette Ortiz, sous le titre de Dance Like This. Ces deux chansons empruntent un passage de l'intro du morceau salsa Amores como el nuestro de Jerry Rivera.","Hips Don't Lie est une chanson interprétée par Shakira et Wyclef Jean.","fr:Hips_Don't_Lie","c:3/33/Hipsdontlie_logo.png"],["Q780394",90,"chanson","Hotel California","L","Hotel California, dont le titre originel est Mexican Reggae, est une chanson américaine du groupe Eagles composée par Don Felder, Don Henley, Glenn Frey. Éditée sur l'album Hotel California en 1976, elle est sortie en single l'année suivante. Elle est classée no 1 au Billboard Hot 100, no 49 parmi les 500 plus grandes chansons de tous les temps selon Rolling Stone. Elle est certifiée disque de platine aux États-Unis où elle a été téléchargée plus de 3 millions de fois.",117,"fr:Hotel_California_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/2/20/Hotel_California_by_the_Eagles_US_vinyl_single.png/330px-Hotel_California_by_the_Eagles_US_vinyl_single.png"],["Q865095",91,"chanson","Hound Dog","C","Hound Dog est une chanson de blues rock américain, écrite et composée par Jerry Leiber & Mike Stoller, et enregistrée en version rhythm and blues en 1952 par Big Mama Thornton. Sa reprise en single en version rock 'n' roll - rockabilly par Elvis Presley en 1956, chez RCA, est un des premiers et plus importants succès de sa carrière et de l'histoire du rock, n°1 des ventes du Billboard Hot 100 américain, vendu à plus de 10 millions d'exemplaires dans le monde.",117,"fr:Hound_Dog","c:3/35/Elvis_Presley_Jailhouse_Rock.jpg"],["Q155512",92,"chanson","I Kissed a Girl","C","I Kissed a Girl est une chanson pop-rock interprétée par Katy Perry et coécrite par Perry, Dr. Luke, Max Martin et Cathy Dennis. Elle figure sur son deuxième album studio, One of the Boys, sorti en 2008. Ce titre a marqué un tournant dans la carrière de Perry, attirant l'attention grâce à ses paroles jugées provocantes et son refrain accrocheur. Son thème de la bisexualité féminine et sa production en ont fait un tube mondial et un titre emblématique de la scène pop de la fin des années 2000.","I Kissed a Girl est une chanson pop-rock interprétée par Katy Perry et coécrite par Perry, Dr.","fr:I_Kissed_a_Girl","c:c/c7/Katy_Perry_-_I_Kissed_a_Girl_logo.png"],["Q219209",93,"chanson","I Want to Break Free","C","I Want to Break Free est une chanson du groupe de rock britannique Queen, sortie en 1984. Il s'agit du deuxième single extrait de l'album The Works de Queen.","I Want to Break Free est une chanson du groupe de rock britannique Queen, sortie en 1984.","fr:I_Want_to_Break_Free","https://upload.wikimedia.org/wikipedia/en/thumb/8/8a/I_Want_to_Break_Free_by_Queen.jpg/330px-I_Want_to_Break_Free_by_Queen.jpg"],["Q666856",94,"chanson","I Will Always Love You","R","I Will Always Love You est une chanson américaine de musique country composée, écrite et interprétée par Dolly Parton et sortie en 1974, puis dans une autre version en 1982 pour la bande originale du film La Cage aux poules. Les deux versions ont atteint la première place du classement country établi par Billboard.",117,"fr:I_Will_Always_Love_You","c:5/59/Dolly_parton_i_will_always_love_you_rca_victor_us_vinyl_a-side.jpg"],["Q2389029",95,"chanson","Ice Ice Baby","C","Ice Ice Baby est une chanson de hip-hop écrite par le rappeur américain Vanilla Ice et DJ Earthquake, un beat-boxeur professionnel.",116,"fr:Ice_Ice_Baby","https://upload.wikimedia.org/wikipedia/en/thumb/3/3f/Vanilla_Ice_-_Ice_Ice_Baby.jpg/330px-Vanilla_Ice_-_Ice_Ice_Baby.jpg"],["Q1658265",96,"chanson","Il est cinq heures, Paris s'éveille","C","Il est cinq heures, Paris s'éveille est une chanson et le sixième EP de Jacques Dutronc, sorti en février 1968. La chanson apparaît aussi sur l'album Il est cinq heures auquel elle donne son titre.","Il est cinq heures, Paris s'éveille est une chanson et le sixième EP de Jacques Dutronc, sorti en février 1968.","fr:Il_est_cinq_heures,_Paris_s'éveille","https://upload.wikimedia.org/wikipedia/en/thumb/8/8b/Il_est_cinq_heures%2C_Paris_s%27%C3%A9veille_sleeve.jpg/330px-Il_est_cinq_heures%2C_Paris_s%27%C3%A9veille_sleeve.jpg"],["Q3148802",97,"chanson","Ils s'aiment","C","Ils s'aiment est une chanson composée par Daniel Lavoie et Daniel DeShaime et interprétée par Daniel Lavoie. D'abord parue en 1983 sur l'album Tension Attention, elle sort en single l'année suivante en France et au Québec.","Ils s'aiment est une chanson composée par Daniel Lavoie et Daniel DeShaime et interprétée par Daniel Lavoie.","fr:Ils_s'aiment_(chanson)",""],["Q1971",98,"chanson","Imagine","PC","Imagine est la chanson éponyme de l'album du musicien britannique John Lennon, sorti en 1971. Placée en ouverture de cet album et également sortie en single sur 45 tours, elle est produite par John Lennon, Yoko Ono et Phil Spector. Bien que la paternité de cette chanson soit attribuée uniquement à Lennon, la contribution de son épouse, Yoko Ono, a été largement reconnue; celle-ci n'est créditée comme coautrice qu'en juin 2017.","Imagine est la chanson éponyme de l'album du musicien britannique John Lennon, sorti en 1971.","fr:Imagine","https://upload.wikimedia.org/wikipedia/en/thumb/2/2a/Lennon_Imagine_Sleeve_1975.jpg/330px-Lennon_Imagine_Sleeve_1975.jpg"],["Q673947",99,"chanson","In da Club","C","In da Club est une chanson de hip-hop interprétée par le rappeur 50 Cent pour son premier album commercial Get Rich or Die Tryin'. La chanson a été produite par Dr. Dre avec une coproduction de Mike Elizondo. 50 Cent, Dr. Dre, et Elizondo ont écrit la chanson. La chanson est sortie en janvier 2003 comme le premier single de l'album et a été accueilli favorablement par la critique musicale.",118,"fr:In_da_Club","https://upload.wikimedia.org/wikipedia/en/thumb/1/12/50_Cent_-_In_Da_Club_-_CD_cover.jpg/330px-50_Cent_-_In_Da_Club_-_CD_cover.jpg"],["Q20003",100,"chanson","In the End","C","In the End est le quatrième et dernier single du premier album Hybrid Theory du groupe de rock alternatif américain Linkin Park. Ce single a été un très grand succès aux États-Unis, il a atteint la seconde position du Billboard Hot 100 au début de 2002, leur meilleure position à ce jour dans ce classement. Il a quitté le classement 38 semaines après sa sortie.",115,"fr:In_the_End_(chanson_de_Linkin_Park)","https://upload.wikimedia.org/wikipedia/en/thumb/3/3f/LinkinParkIntheEnd.jpg/330px-LinkinParkIntheEnd.jpg",{"cats":["chansons","groupes"]}],["Q3156565",101,"chanson","J'ai demandé à la Lune","C","J'ai demandé à la Lune est une chanson du groupe Indochine extraite de l'album Paradize sorti en 2002. Ce morceau phare, écrit en 1994 par Mickaël Furnon, chanteur de Mickey 3D, a permis à Indochine de retrouver le devant de la scène, après dix ans de faible exposition médiatique.","J'ai demandé à la Lune est une chanson du groupe Indochine extraite de l'album Paradize sorti en 2002.","fr:J'ai_demandé_à_la_Lune","https://upload.wikimedia.org/wikipedia/en/thumb/3/34/J%27ai_demand%C3%A9_%C3%A0_la_lune.jpg/330px-J%27ai_demand%C3%A9_%C3%A0_la_lune.jpg",{"cats":["chansons","groupes"]}],["Q1353423",102,"chanson","Jailhouse Rock","C","Jailhouse Rock est une chanson de rock 'n' roll-rockabilly, écrite et composée par Jerry Leiber et Mike Stoller pour Elvis Presley, enregistrée chez RCA pour le film musical Jailhouse Rock de Richard Thorpe en 1957, et pour l'album Elvis' Golden Records de 1958. Elle est reprise avec succès entre autres par The Blues Brothers pour la bande originale du film Les Blues Brothers de 1980.",116,"fr:Jailhouse_Rock","c:9/99/Elvis_Presley_promoting_Jailhouse_Rock.jpg"],["Q2480307",103,"chanson","Je l'aime à mourir","C","Je l'aime à mourir est une chanson de Francis Cabrel, incluse dans l'album Les Chemins de traverse sorti en 1979. L'album a été vendu à plus de 600 000 exemplaires en France et la chanson qui en est issue, Je l'aime à mourir, vendue à plus de 700 000 exemplaires, reste la plus grosse vente de singles de Francis Cabrel.","Je l'aime à mourir est une chanson de Francis Cabrel, incluse dans l'album Les Chemins de traverse sorti en 1979.","fr:Je_l'aime_à_mourir","c:4/43/Francis_Cabrel01.jpg"],["Q128028",104,"chanson","Je t'aime… moi non plus","C","Je t’aime… moi non plus est une chanson française écrite et composée par Serge Gainsbourg, et chantée par celui-ci, en duo, tout d’abord avec Brigitte Bardot en 1967, qui refuse dans un premier temps sa publication. Gainsbourg la réenregistre donc avec sa nouvelle compagne Jane Birkin en 1969, et le titre sera notamment n°1 au Royaume-Uni.",118,"fr:Je_t'aime…_moi_non_plus","c:6/68/Gainsbourg-Birkin-Italie-1976.png"],["Q406845",105,"chanson","Jingle Bells","C","Jingle Bells, connu en français sous le titre Vive le vent, est un chant de Noël traditionnel américain, écrit et composé par James Lord Pierpont.",113,"fr:Jingle_Bells","c:2/2f/One_Horse_Open_Sleigh_title_page.jpg"],["Q1762409",106,"chanson","Joe le taxi","C","Joe le taxi est une chanson française écrite par Étienne Roda-Gil, composée par Franck Langolff et interprétée par Vanessa Paradis en 1987.",114,"fr:Joe_le_taxi","https://upload.wikimedia.org/wikipedia/en/thumb/0/0b/Vanessa_Paradis_-_Joe_Le_Taxi_single_cover.jpg/330px-Vanessa_Paradis_-_Joe_Le_Taxi_single_cover.jpg"],["Q931481",107,"chanson","Johnny B. Goode","PC","Johnny B. Goode est une chanson de Chuck Berry, écrite en 1957. Elle atteint le huitième rang du hit-parade en 1958. La chanson est considérée comme l'un des morceaux les plus emblématiques du rock'n'roll.","Johnny B.","fr:Johnny_B._Goode","c:8/89/Johnny_B_Goode_by_Chuck_Berry_US_single_side-A.png"],["Q167545",108,"chanson","Joyeux Anniversaire","E","Joyeux Anniversaire, Bonne fête à toi ou tout simplement Bonne Fête, en anglais: Happy Birthday to You, est une chanson traditionnellement chantée pour célébrer l'anniversaire de naissance d'une personne vivante.",119,"fr:Joyeux_Anniversaire","c:4/4f/Birthday_cake.jpg"],["Q188766",109,"chanson","Judas","C","Judas est une chanson de l’artiste américaine Lady Gaga. Il s’agit du second single de son troisième album studio, Born This Way. Le morceau est dévoilé le 15 avril 2011, cinq jours avant la sortie initiale prévue par Interscope Records. Écrite et produite par Lady Gaga ainsi que RedOne, Judas adopte un style dance malgré son sujet posé, qui aborde la trahison et l’amour.","Judas est une chanson de l’artiste américaine Lady Gaga.","fr:Judas_(chanson)","c:a/a1/Judas_logo.png"],["Q720547",110,"chanson","Jump","C","Jump est une chanson du groupe de rock Van Halen sortie le 21 décembre 1983. Elle figure sur son 6e album intitulé 1984.","Jump est une chanson du groupe de rock Van Halen sortie le 21 décembre 1983.","fr:Jump_(chanson_de_Van_Halen)","c:6/6a/Van_Halen_-_Jump_2007-11-10.jpg"],["Q189007",111,"chanson","Just Dance","C","Just Dance est le premier single de l’artiste américaine Lady Gaga. La chanson est écrite par Gaga, Akon, qui contribue également aux chœurs, ainsi que par RedOne, qui de plus produit la piste, et est en collaboration avec Colby O'Donis. Elle sort en 2008, en tant que single ‘conducteur’ du premier album de Gaga, The Fame. La piste est écrite par Gaga en dix minutes dans un « drôle de studio ». Le morceau possède plusieurs influences R&B et lyriquement traite sur l’intoxication dans les clubs.","Just Dance est le premier single de l’artiste américaine Lady Gaga.","fr:Just_Dance_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/7/77/Just_Dance_cover.png/330px-Just_Dance_cover.png"],["Q382559",112,"chanson","Kalinka","C","Kalinka est une célèbre chanson d'amour traditionnelle russe, écrite et composée en 1860 par Ivan Larionov. Reprise en particulier par Ivan Rebroff et par les Chœurs de l'Armée rouge, il est impossible de traduire toutes les nuances de cette chanson d'amour poétique à cause des expressions typiques russes utilisées et des double-sens volontairement introduits.","Kalinka est une célèbre chanson d'amour traditionnelle russe, écrite et composée en 1860 par Ivan Larionov.","fr:Kalinka","c:0/0d/Ukrainian_girl_by_Nikolay_Rachkov_%282nd_half_19_c.%2C_Chernigov_museum%29.jpg"],["Q18288",113,"chanson","Katioucha","PC","Katioucha ou Katyusha est une chanson d'amour traditionnelle russe soviétique, composée par Matveï Blanter, avec des paroles de Mikhaïl Issakovski, interprétée pour la première fois en 1938 par Vera Krassovitskaïa, Gueorgui Vinogradov et Vsevolod Tioutiounnik, avec l'orchestre de Viktor Knouchevitski.",116,"fr:Katioucha_(chanson)",""],["Q829960",114,"chanson","Killer Queen","C","Killer Queen est une chanson du groupe Queen parue sur l'album Sheer Heart Attack, comme single double face A avec Flick of the Wrist en 1973.",114,"fr:Killer_Queen","https://upload.wikimedia.org/wikipedia/en/thumb/a/af/Killer3cdfront.JPG/330px-Killer3cdfront.JPG"],["Q3202736",115,"chanson","L'Aventurier","C","L’Aventurier est une chanson d'Indochine parue sur l'album du même nom en 1982, puis en single la même année. Ce deuxième single du groupe, qui évoque l'univers de Bob Morane et s'est hissé à la 4e place des ventes en France, a contribué à lancer la carrière du groupe dans les années 1980.","L’Aventurier est une chanson d'Indochine parue sur l'album du même nom en 1982, puis en single la même année.","fr:L'Aventurier_(chanson)","",{"cats":["chansons","groupes"]}],["Q20724521",116,"chanson","L'Envie","C","L'Envie est une chanson de Johnny Hallyday écrite par Jean-Jacques Goldman sortie en 1986 sur l'album Gang. En 1988, elle paraît en single dans une version live extraite de l'album Johnny à Bercy. L'Envie, à l'instar des chansons La Musique que j'aime, Oh ! Ma Jolie Sarah ou encore Gabrielle, est devenue un des nombreux classique du répertoire de son interprète. À quelques rares exceptions, elle a été durant trente ans présente dans tous les tours de chant de l'artiste.","L'Envie est une chanson de Johnny Hallyday écrite par Jean-Jacques Goldman sortie en 1986 sur l'album Gang.","fr:L'Envie_(chanson)",""],["Q641677",117,"chanson","La bamba","PC","La bamba est un air traditionnel mexicain, originaire de l'État de Veracruz, dans l'est du Mexique, au rythme proche de la cumbia. Le genre musical correspondant est le son jarocho.",119,"fr:La_bamba",""],["Q2635232",118,"chanson","La Bohème","C","La Bohème est une chanson d'amour française, composée par Charles Aznavour et écrite par Jacques Plante, sur le thème de la vie de bohème, pour l'opérette Monsieur Carnaval de Charles Aznavour de 1965. Ce single extrait de son 17e album La bohème de 1966, est un des nombreux tubes internationaux emblématiques de son important répertoire, de sa carrière, et un des classiques de la chanson française, et des chansons sur Paris.",117,"fr:La_Bohème_(chanson)","c:b/b7/2014.06.23._Charles_Aznavour_Fot_Mariusz_Kubik_02.jpg"],["Q1344584",119,"chanson","La Danse des canards","C","La Danse des canards est une chanson composée par l'accordéoniste suisse Werner Thomas en 1957 sous le titre Der Ententanz, plus tard réintitulée Der Vogeltanz.",112,"fr:La_Danse_des_canards","c:2/26/Chicken_dance_01_-_Ballard_Seafood_Fest_2007.jpg"],["Q3209834",120,"chanson","La Javanaise","C","La Javanaise est une chanson française de l'auteur-compositeur-interprète Serge Gainsbourg, qu'il enregistre en single en 1963. Le titre est repris en single par Juliette Gréco cette même année, extrait de son album La Javanaise no 8, un des grands succès de leurs carrières et de la chanson française.",118,"fr:La_Javanaise","c:4/49/Gainsboug-1965-Italie_%28cropped%29.png"],["Q11986",121,"chanson","La Vie en rose","PC","La Vie en rose est une chanson de l'auteure-interprète Édith Piaf, sur une musique de son pianiste-compositeur Louiguy. Elle l’enregistre le 9 octobre 1946 chez Columbia, avec l'orchestre de Guy Luypaerts, et dans le film Neuf Garçons, un cœur, de 1948. La Vie en rose est l'un des nombreux succès internationaux emblématiques de son répertoire, et de la chanson française.","La Vie en rose est une chanson de l'auteure-interprète Édith Piaf, sur une musique de son pianiste-compositeur Louiguy.","fr:La_Vie_en_rose","c:5/51/Edith_Piaf_Harcourt_1950_3.jpg"],["Q2572727",122,"chanson","Laisse tomber les filles","C","Laisse tomber les filles est une chanson française écrite et composée par Serge Gainsbourg et chantée par France Gall en 1964.",117,"fr:Laisse_tomber_les_filles","c:0/05/Gainsboug-Gall-1965-Italie.png"],["Q701766",123,"chanson","Lambada","C","Lambada, également connue sous le titre Chorando se foi, est une chanson du groupe franco-brésilien Kaoma. Elle est interprétée par la chanteuse brésilienne Loalwa Braz et a été sortie en tant que premier single de l'album Worldbeat, premier album de Kaoma. Le titre fait référence à la danse de la lambada. Le clip accompagnant la chanson met en scène le duo d'enfants brésiliens Chico et Roberta.","Lambada, également connue sous le titre Chorando se foi, est une chanson du groupe franco-brésilien Kaoma.","fr:Lambada_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/c/c5/Lambada_%28cover%29.jpg/330px-Lambada_%28cover%29.jpg"],["Q1318118",124,"chanson","Last Christmas","PC","Last Christmas est une chanson d'amour Disco-new wave-synthpop de Noël du groupe-duo anglais Wham!, composée et écrite par George Michael, et publiée en single double face A avec Everything She Wants, chez Epic Records en 1984, et sur leurs 3e et derniers albums The Final et Music from the Edge of Heaven de 1986. Ce titre est l'un des tubes internationaux emblématiques de la pop européenne des années 1980. Il est devenu par la suite un classique musical des fêtes de Noël.",118,"fr:Last_Christmas_(chanson)","c:f/f2/George_Michael.jpeg"],["Q3221047",125,"chanson","Le Chanteur","C","Le Chanteur est une chanson écrite, composée et interprétée en 1978 par Daniel Balavoine.",null,"fr:Le_Chanteur_(chanson)",""],["Q733238",126,"chanson","Le Déserteur","C","Le Déserteur est une chanson écrite par Boris Vian en février 1954, composée avec Harold B. Berg et enregistrée dans sa forme définitive l'année suivante. Son antimilitarisme a provoqué beaucoup de polémiques.","Le Déserteur est une chanson écrite par Boris Vian en février 1954, composée avec Harold B.","fr:Le_Déserteur_(chanson)","c:2/22/Boris_Vian_-_WIKI_retouched.jpg"],["Q1344182",127,"chanson","Le Plat Pays","C","Le Plat Pays est une chanson de l'auteur-compositeur-interprète belge Jacques Brel, une de ses œuvres les plus connues, dont le sujet est le pays d'origine de ses ancêtres, la Belgique.",119,"fr:Le_Plat_Pays","c:c/c1/Jacques_Brel_%281962%29.jpg"],["Q51788150",128,"chanson","Le Pouvoir des fleurs","C","Le Pouvoir des fleurs est une chanson de Laurent Voulzy, écrite par Alain Souchon et composée par Laurent Voulzy.",null,"fr:Le_Pouvoir_des_fleurs",""],["Q3227443",129,"chanson","Le Sud","C","Le Sud est une chanson écrite, composée, interprétée et coproduite par Nino Ferrer, publiée en février 1975 par le label CBS. Dernier et plus grand succès du chanteur, elle est le symbole de la carrière de cet artiste, par lui très mal vécue, partagée entre succès populaires et albums ambitieux ignorés du grand public.",114,"fr:Le_Sud_(chanson)","c:d/dc/Joseph_Rusling_Meeker_-_Bayou_Teche%2C_Louisiana_-_15-2008_-_Saint_Louis_Art_Museum.jpg"],["Q1340251",130,"chanson","Le Temps des cerises","C","Le Temps des cerises est une chanson dont les paroles sont écrites en 1866 par Jean Baptiste Clément et la musique composée par Antoine Renard en 1868.",114,"fr:Le_Temps_des_cerises","c:2/26/Le_temps_des_cerises_%28m%C3%A9lodie_en_Do%29.png"],["Q1172919",131,"chanson","Le vent nous portera","C","Le vent nous portera est une chanson du groupe Noir Désir en single et publiée sur l'album Des visages des figures le 11 septembre 2001.",117,"fr:Le_vent_nous_portera","https://upload.wikimedia.org/wikipedia/en/thumb/8/8e/Le_vent_nous_portera.jpg/330px-Le_vent_nous_portera.jpg",{"cats":["chansons","groupes"]}],["Q25066588",132,"chanson","Les Copains d'abord","C","Les Copains d'abord est une chanson de Georges Brassens parue en 1964 en ouverture de son dixième album, auquel elle donne son titre.",116,"fr:Les_Copains_d'abord","c:1/19/Brassens_TNP_1966.jpg"],["Q3233486",133,"chanson","Les Lacs du Connemara","C","Les Lacs du Connemara est une chanson de Michel Sardou créée en 1981 sur l’album qui sera plus tard désigné sous ce même titre. Le texte est signé Pierre Delanoë et Michel Sardou. Elle est composée et produite par Jacques Revaux.",115,"fr:Les_Lacs_du_Connemara_(chanson)",""],["Q37794344",134,"chanson","Les Mots bleus","C","Les Mots bleus est une chanson de Christophe sur des paroles de Jean-Michel Jarre, parue initialement sur l'album Les Mots bleus en 1974 et sortie comme deuxième 45 tours de l'album la même année. Elle a fait l'objet de nombreuses reprises.",117,"fr:Les_Mots_bleus_(chanson)",""],["Q184259",135,"chanson","Let It Be","PC","Let It Be est une chanson des Beatles, écrite et chantée par Paul McCartney, publiée en single le 6 mars 1970 avec You Know My Name en face B. Cette chanson fut numéro un des ventes au Billboard Hot 100, et numéro deux au UK Singles Chart. Sur le marché britannique, il s'agit du dernier single publié par le groupe. Elle est la chanson éponyme de l'album et du film.",118,"fr:Let_It_Be_(chanson)","c:1/16/LetItBe.JPG"],["Q2315784",136,"chanson","Levels","C","Levels est une chanson du DJ et producteur house suédois Avicii. Sortie le 28 juillet 2011, la chanson est écrite par Avicii et Ash Pournouri. La musique contient un sample gospel de 1962 inspirée de Something's Got a Hold on Me d'Etta James. Levels a inspiré le rappeur américain Flo Rida pour son single Good Feeling. Le single atteint la 1re place des ventes dans le pays d'origine d'Avicii, devenant ainsi le premier no 1 du Dj.","Levels est une chanson du DJ et producteur house suédois Avicii.","fr:Levels","https://upload.wikimedia.org/wikipedia/en/thumb/2/2c/Levelssong.jpg/330px-Levelssong.jpg",{"cats":["chansons","electro"]}],["Q90599924",137,"chanson","Levitating","C","Levitating est une chanson de la chanteuse anglaise Dua Lipa parue sur son deuxième album Future Nostalgia sorti le 27 mars 2020. Elle est sortie le 13 août 2020 en tant que cinquième single de l'album. La chanson a été écrite par Dua Lipa, Clarence Coffee Jr., Sarah Hudson et Stephen Kozmeniuk, la production étant faite par Kozmeniuk et Stuart Price. La chanson est une musique electro-disco et nu-disco avec plusieurs tropes disco.",118,"fr:Levitating","https://upload.wikimedia.org/wikipedia/en/thumb/c/c6/Dua_Lipa_Levitating_Solo_Single_Cover.jpeg/330px-Dua_Lipa_Levitating_Solo_Single_Cover.jpeg"],["Q15282326",138,"chanson","Libérée, délivrée","C","Libérée, délivrée, ou Let It Go en version originale, est une chanson provenant du film d'animation La Reine des neiges, sorti en 2013. Les paroles ont été écrites par Kristen Anderson-Lopez en version originale, et la musique a été composée par Robert Lopez.",112,"fr:Libérée,_délivrée","https://upload.wikimedia.org/wikipedia/fr/thumb/2/28/La_Reine_des_neiges_%28film%2C_2013%29_Logo.png/330px-La_Reine_des_neiges_%28film%2C_2013%29_Logo.png"],["Q1420677",139,"chanson","Like a Prayer","PC","Like a Prayer est une chanson de l'artiste américaine Madonna, issue de son quatrième album studio éponyme. Elle sort en single le 21 mars 1989 sous le label Sire Records en tant que premier single de l'album. La chanson apparaît aussi sur les compilations The Immaculate Collection et Celebration. Écrite et produite en collaboration avec Patrick Leonard, Like a Prayer souligne une approche plus personnelle et plus artistique pour Madonna, plus que le reste de l'album.","Like a Prayer est une chanson de l'artiste américaine Madonna, issue de son quatrième album studio éponyme.","fr:Like_a_Prayer_(chanson_de_Madonna)","c:b/bd/Like_a_Prayer_single_logo.png"],["Q214430",140,"chanson","Like a Rolling Stone","C","Like a Rolling Stone est une chanson de l'auteur, compositeur, et interprète américain Bob Dylan, sortie en 45 tours le 20 juillet 1965 par Columbia Records et figurant en ouverture de l'album Highway 61 Revisited.",119,"fr:Like_a_Rolling_Stone","c:2/2c/Like_a_rolling_stone_by_bob_dylan_us_vinyl_side_a.png"],["Q2604345",141,"chanson","Livin' la vida loca","C","Livin' la vida loca est une chanson du chanteur portoricain Ricky Martin sortie le 23 mars 1999 sous le label Columbia Records. Il s'agit du 1er single extrait de son 5e album studio Ricky Martin.",118,"fr:Livin'_la_vida_loca","https://upload.wikimedia.org/wikipedia/en/thumb/e/ed/Livin%27_la_vida_loca_cover.png/330px-Livin%27_la_vida_loca_cover.png"],["Q1894466",142,"chanson","Livin' on a Prayer","C","Livin' on a Prayer est un morceau de l'album Slippery When Wet de Bon Jovi. Pierre angulaire du long succès du groupe Bon Jovi, et véritable signature du groupe, Livin' on a Prayer est désormais considéré comme un classique de la musique de variété anglo-saxonne. Le titre est repris dans les jeux Rock Band 2 et Guitar Hero World Tour.","Livin' on a Prayer est un morceau de l'album Slippery When Wet de Bon Jovi.","fr:Livin'_on_a_Prayer","https://upload.wikimedia.org/wikipedia/en/thumb/c/c6/LivinOnAPrayer%28hq%29.jpg/330px-LivinOnAPrayer%28hq%29.jpg",{"cats":["chansons","groupes"]}],["Q122332978",143,"chanson","Lose Control","C","Lose Control est une chanson de l'Américain Teddy Swims sortie en 2023. Elle est devenue un énorme succès international et a battu des records de longévité dans les classements.","","en:Lose_Control_(Teddy_Swims_song)","https://upload.wikimedia.org/wikipedia/en/thumb/0/03/Teddy_Swims_-_Lose_Control.jpg/330px-Teddy_Swims_-_Lose_Control.jpg"],["Q957616",144,"chanson","Lose Yourself","PC","Lose Yourself est une chanson d'Eminem, présente sur la bande originale du film 8 Mile, et pour laquelle il gagne un Oscar de la meilleure chanson originale ainsi que deux Grammy Awards. C'est durant une pause sur le tournage du film qu'il écrit les trois couplets du morceau quasiment d'une traite. On voit d'ailleurs ses notes écrites dans une scène du film lorsque son personnage écrit dans un bus. Pour l'anecdote, ces notes ont été vendues 10 000 $ sur eBay.",116,"fr:Lose_Yourself","c:c/cd/Eminem-01-mika.jpg"],["Q1149738",145,"chanson","Macarena","R","Macarena est une chanson du groupe espagnol Los del Río sortie en 1993.",null,"fr:Macarena_(chanson_de_Los_del_Río)","c:7/77/Remix_of_Los_Del_Rio%27s_Macarena_by_The_Bayside_Boys_European_CD.jpeg"],["Q134721313",146,"chanson","Manchild","C","Manchild est une chanson de Sabrina Carpenter sortie le 5 juin 2025, premier single de son album Man's Best Friend, coproduite avec Jack Antonoff.","","en:Manchild_(Sabrina_Carpenter_song)","https://upload.wikimedia.org/wikipedia/en/thumb/2/2c/Sabrina_Carpenter_-_Manchild.png/330px-Sabrina_Carpenter_-_Manchild.png"],["Q113840008",147,"chanson","Mes emmerdes","C","Mes emmerdes est une chanson française écrite, composée et interprétée par Charles Aznavour en 1976.",null,"fr:Mes_emmerdes",""],["Q3317000",148,"chanson","Mistral gagnant","C","Mistral gagnant est une chanson de Renaud, éponyme de l’album Mistral gagnant paru en 1985.",null,"fr:Mistral_gagnant_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/6/6e/Mistral-Gagnant-Renaud.jpg/330px-Mistral-Gagnant-Renaud.jpg"],["Q26402",149,"chanson","Moi… Lolita","C","Moi... Lolita est une chanson d’Alizée, sortie en single le 3 juillet 2000, en tant que premier extrait de son premier album Gourmandises.","Moi...","fr:Moi…_Lolita","c:a/ad/Moi..._Lolita_%28pochette_du_single%29.png"],["Q3319803",150,"chanson","Mon amant de Saint-Jean","C","Mon amant de Saint-Jean est une chanson française, chanson réaliste de music-hall et valse musette enregistrée en disque 78 tours en 1942 par Lucienne Delyle, un des grands succès de son répertoire et de la chanson française.",113,"fr:Mon_amant_de_Saint-Jean","c:6/6a/Delyle1939.jpg"],["Q3319888",151,"chanson","Mon fils ma bataille","C","Mon fils ma bataille est une chanson écrite, composée et interprétée par Daniel Balavoine pour l'album Un autre monde en 1980, dont il est premier extrait à paraître en single, avec Détournement en face B.",117,"fr:Mon_fils_ma_bataille",""],["Q3326140",152,"chanson","Mourir sur scène","C","Mourir sur scène est une des chansons emblématiques du répertoire de Dalida, sortie en 1983. Elle est souvent considérée comme la chanson la plus représentative de la fin de carrière de la chanteuse.","Mourir sur scène est une des chansons emblématiques du répertoire de Dalida, sortie en 1983.","fr:Mourir_sur_scène","c:9/9b/Disque_Mourir_sur_sc%C3%A8ne.jpg"],["Q1999714",153,"chanson","Mr. Brightside","E","Mr. Brightside est une chanson du groupe de rock américain The Killers, sortie en 2003 et par la suite incluse dans leur premier album, Hot Fuss. Écrite et composée par Brandon Flowers et Dave Keuning, elle a connu un succès important et figure en 3e place du classement des « 200 meilleures chansons du XXIe siècle » établi par le magazine Rolling Stone.","Mr.","fr:Mr._Brightside","https://upload.wikimedia.org/wikipedia/en/thumb/d/d1/Mr.-Brightside.jpg/330px-Mr.-Brightside.jpg"],["Q155577",154,"chanson","My Heart Will Go On","PC","My Heart Will Go On est la chanson thème du film Titanic sortie en 1997. Cette chanson, interprétée par Céline Dion, est composée par James Horner et les paroles sont écrites par Will Jennings. Elle est éditée pour la première fois le 14 novembre 1997 sur l'album de Céline Dion Let's Talk About Love, puis 18 novembre sur la bande originale du film et en single le 24 novembre. Le titre devient vite un gros succès.","My Heart Will Go On est la chanson thème du film Titanic sortie en 1997.","fr:My_Heart_Will_Go_On","https://upload.wikimedia.org/wikipedia/en/thumb/3/3e/Celine_Dion_-_My_Heart_Will_Go_On_%28single_cover%29.png/330px-Celine_Dion_-_My_Heart_Will_Go_On_%28single_cover%29.png"],["Q1247220",155,"chanson","Ne me quitte pas","C","Ne me quitte pas est une chanson de Jacques Brel sur la rupture amoureuse, écrite et composée avec son pianiste Gérard Jouannest et enregistrée par Brel en 1959.",118,"fr:Ne_me_quitte_pas","https://upload.wikimedia.org/wikipedia/en/thumb/9/94/Jacques_Brel-Ne_Me_Quitte_Pas_%281960%29.jpg/330px-Jacques_Brel-Ne_Me_Quitte_Pas_%281960%29.jpg"],["Q1191058",156,"chanson","Ne partez pas sans moi","C","Ne partez pas sans moi est une chanson écrite par Nella Martinetti et composée par Atilla Şereftuğ, et interprétée par Céline Dion pour représenter la Suisse au Concours Eurovision de la chanson 1988, qu'elle remporte. C'est la seconde fois que la Suisse gagne le concours après avoir remporté le premier, en 1956 avec Lys Assia chantant Refrain. À ce jour, c'est la dernière chanson francophone à remporter le concours.",118,"fr:Ne_partez_pas_sans_moi","https://upload.wikimedia.org/wikipedia/en/thumb/b/b8/Nppsm3.jpg/330px-Nppsm3.jpg"],["Q598412",157,"chanson","Nel blu dipinto di blu","C","Nel blu dipinto di blu, plus connue sous le titre Volare, est la chanson phare de Domenico Modugno, coécrite en 1958 avec Franco Migliacci. Une version française est chantée par Dalida et Maria Lopez la même année sous le titre Dans le bleu du ciel bleu.",116,"fr:Nel_blu_dipinto_di_blu_(chanson)","c:7/7f/Eurovision_Song_Contest_1958_-_Domenico_Modugno.png"],["Q57",158,"chanson","Never Gonna Give You Up","PC","Never Gonna Give You Up est une chanson du chanteur Rick Astley tiré de son premier album Whenever You Need Somebody.",null,"fr:Never_Gonna_Give_You_Up","https://upload.wikimedia.org/wikipedia/commons/thumb/f/f7/Rick_Astley_sig.svg/330px-Rick_Astley_sig.svg.png",{"cats":["chansons","memes"]}],["Q11988",159,"chanson","Non, je ne regrette rien","C","Non, je ne regrette rien est une chanson composée en 1956 par Charles Dumont, sur des paroles de Michel Vaucaire. Elle est enregistrée pour la première fois par Édith Piaf le 10 novembre 1960 et sort en décembre. Elle fait partie des chansons les plus connues de la chanteuse dans le monde et se classe no 1 des ventes en France, aux Pays-Bas, en Belgique et au Canada.","Non, je ne regrette rien est une chanson composée en 1956 par Charles Dumont, sur des paroles de Michel Vaucaire.","fr:Non,_je_ne_regrette_rien","c:3/37/Edith_Piaf_zingt_in_ons_land%2C_Bestanddeelnr_914-6439.jpg"],["Q125778683",160,"chanson","Not Like Us","PC","Not Like Us est une chanson écrite et enregistrée par le rappeur américain Kendrick Lamar. Elle est sortie le 4 mai 2024 via le label Interscope Records, au milieu d'une querelle très médiatisée entre Kendrick Lamar et le rappeur canadien Drake. Il s'agit du cinquième volet de la série de diss songs de Lamar dirigées contre Drake. Elle est diffusée moins de 20 heures après son précédent single, Meet the Grahams.","Not Like Us est une chanson écrite et enregistrée par le rappeur américain Kendrick Lamar.","fr:Not_Like_Us","https://upload.wikimedia.org/wikipedia/en/thumb/6/61/Kendrick_Lamar_-_Not_Like_Us.png/330px-Kendrick_Lamar_-_Not_Like_Us.png"],["Q66057506",161,"chanson","Nothing Else Matters","C","Nothing Else Matters est une chanson du groupe de heavy metal Metallica, figurant sur l'album Metallica sorti en 1991. Elle demeure une des plus connues du groupe.","Nothing Else Matters est une chanson du groupe de heavy metal Metallica, figurant sur l'album Metallica sorti en 1991.","fr:Nothing_Else_Matters","https://upload.wikimedia.org/wikipedia/en/thumb/f/f5/Metallica_-_Nothing_Else_Matters_cover.jpg/330px-Metallica_-_Nothing_Else_Matters_cover.jpg",{"cats":["chansons","groupes"]}],["Q659370",162,"chanson","Nuit de folie","C","Nuit de folie est une chanson interprétée par Début de soirée, duo formé de deux DJ du sud de la France, William Picard et Sacha Goëller, parue sur leur premier album Jardins d'enfants.",119,"fr:Nuit_de_folie_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/d/d4/Nuit_de_folie.jpg/330px-Nuit_de_folie.jpg"],["Q19973",163,"chanson","Numb","C","Numb est une chanson du groupe américain Linkin Park. Elle est la 13e et dernière piste de l'album Meteora, sorti en 2003.","Numb est une chanson du groupe américain Linkin Park.","fr:Numb_(chanson_de_Linkin_Park)","https://upload.wikimedia.org/wikipedia/en/thumb/b/b9/Linkin_Park_-_Numb_CD_cover.jpg/330px-Linkin_Park_-_Numb_CD_cover.jpg",{"cats":["chansons","groupes"]}],["Q62587323",164,"chanson","Old Town Road","C","Old Town Road est une chanson du rappeur américain Lil Nas X. Sortie initialement de manière indépendante le 3 décembre 2018, la chanson connaît un succès rapide via la plateforme TikTok et est par la suite distribuée par le label Columbia. Une nouvelle version, sortie le 5 avril 2019, est par la suite commercialisée en featuring avec le chanteur de country Billy Ray Cyrus.","Old Town Road est une chanson du rappeur américain Lil Nas X.","fr:Old_Town_Road","https://upload.wikimedia.org/wikipedia/en/thumb/1/1c/Old_Town_Road_cover.jpg/330px-Old_Town_Road_cover.jpg"],["Q2617236",165,"chanson","One More Time","C","One More Time est une chanson du groupe de musique électronique français Daft Punk, écrite et composée par ses membres Thomas Bangalter et Guy-Manuel de Homem-Christo, et interprétée par le chanteur américain Romanthony. Enregistrée en 1998, elle est publiée en single le 13 novembre 2000 sous le label Virgin Records. Il s'agit du premier single extrait de Discovery, le second album de Daft Punk, publié en 2001.",118,"fr:One_More_Time_(chanson_de_Daft_Punk)","https://upload.wikimedia.org/wikipedia/en/thumb/9/99/DaftPunk_OneMoreTime.jpg/330px-DaftPunk_OneMoreTime.jpg",{"cats":["chansons","electro"]}],["Q132746150",166,"chanson","Ordinary","PC","Ordinary est une chanson d'Alex Warren sortie en février 2025. Cette ballade est devenue l'un des plus grands tubes de l'année.","","en:Ordinary_(Alex_Warren_song)","https://upload.wikimedia.org/wikipedia/en/thumb/b/b0/Alex_Warren_-_Ordinary.png/330px-Alex_Warren_-_Ordinary.png"],["Q161402",167,"chanson","Over the Rainbow","R","Over the Rainbow est l'une des chansons les plus connues de la fin des années 1930. Incarnant les espoirs et les rêves d'une jeunesse aspirant à un monde idéal d'amour et de joie, la chanson fut écrite en une nuit par Harold Arlen pour Judy Garland qui l'interpréta dans le film Le Magicien d'Oz, et elle devint le thème musical qui devait bercer toute sa vie. En effet, on lui demanda de l'interpréter à presque toutes ses apparitions publiques.","Over the Rainbow est l'une des chansons les plus connues de la fin des années 1930.","fr:Over_the_Rainbow_(chanson)","c:5/56/Judy_Garland_Over_the_Rainbow_2.jpg"],["Q3359283",168,"chanson","Où sont les femmes ?","C","Où sont les femmes ? est une chanson de Patrick Juvet parue sur l'album Paris by Night en 1977.","Où sont les femmes ?","fr:Où_sont_les_femmes_?","https://upload.wikimedia.org/wikipedia/en/thumb/5/51/Patrick_Juvet_O%C3%B9_sont_les_femmes.jpg/330px-Patrick_Juvet_O%C3%B9_sont_les_femmes.jpg"],["Q19298155",169,"chanson","Padam, padam...","C","Padam, padam... est une chanson d'amour d'Édith Piaf, écrite par Henri Contet et composée par Norbert Glanzberg, enregistrée en single en 1951 avec l'orchestre de Robert Chauvigny, et intégrée à son album Récital À l'Olympia enregistré à l'Olympia de Paris de 1955. Un des grands succès internationaux de son répertoire et de la chanson française.","Padam, padam...","fr:Padam,_padam...","c:5/51/Edith_Piaf_Harcourt_1950_3.jpg"],["Q1046717",170,"chanson","Paint It, Black","R","Paint It, Black est une chanson du groupe de rock britannique The Rolling Stones, créditée Jagger/Richards bien que tous les membres du groupe aient contribué à sa composition, notamment Bill Wyman et Brian Jones. La chanson sort en single successivement des deux côtés de l'Atlantique à une semaine d'intervalle en mai 1966, et atteint dans les deux cas la première place.",115,"fr:Paint_It,_Black","c:3/31/The_Rolling_Stones_Paint_It_Black_45t_face_A.jpg"],["Q13422150",171,"chanson","Papaoutai","C","Papaoutai est une chanson du chanteur belge Stromae extraite du second album studio, intitulé Racine carrée. Le titre est sorti en tant que premier single de l'album le 13 mai 2013. Un remix en featuring avec la rappeuse Angel Haze a également été réalisé.","Papaoutai est une chanson du chanteur belge Stromae extraite du second album studio, intitulé Racine carrée.","fr:Papaoutai","https://upload.wikimedia.org/wikipedia/en/thumb/6/65/Stromae-Papaoutai.jpg/330px-Stromae-Papaoutai.jpg"],["Q1025916",172,"chanson","Paparazzi","C","Paparazzi est une chanson enregistrée par l’artiste américaine Lady Gaga, sortie comme étant le dernier single de son premier album, The Fame. Écrit par Rob Fusari et Gaga, le titre est le troisième single de l'album au Royaume-Uni, en Irlande ainsi qu’en Italie, le quatrième au Canada et aux États-Unis et le cinquième en Australie, en Nouvelle-Zélande et en France. Il est sorti le 6 juillet 2009 au Royaume-Uni et quatre jours plus tard en Australie.",117,"fr:Paparazzi_(chanson)","c:1/18/Paparazzi_Logo.png"],["Q2638348",173,"chanson","Parole parole","C","Parole parole est une chanson italienne en duo composée par Gianni Ferrio et écrite par Leo Chiosso et Giancarlo Del Re. La chanson a été initialement interprétée par Mina et Alberto Lupo, et ce fut un succès en 1972.","Parole parole est une chanson italienne en duo composée par Gianni Ferrio et écrite par Leo Chiosso et Giancarlo Del Re.","fr:Parole_parole","c:1/1d/Alberto_Lupo%2C_Mina_1972.jpg"],["Q48746335",174,"chanson","Paroles... Paroles...","C","Paroles… Paroles… est une chanson interprétée par Dalida et Alain Delon. Elle est la version française de la chanson italienne Parole parole.","Paroles… Paroles… est une chanson interprétée par Dalida et Alain Delon.","fr:Paroles..._Paroles...","https://upload.wikimedia.org/wikipedia/en/thumb/3/32/Paroles%2C_paroles.jpg/330px-Paroles%2C_paroles.jpg"],["Q116227",175,"chanson","Partenaire particulier","C","Partenaire particulier est un groupe français de musique new wave. Il connut un certain succès au milieu des années 1980, notamment avec sa chanson éponyme qui, comme deux autres de ses tubes, Je n'oublierai jamais et Elle est partie, se classa dans le Top 50 des meilleures ventes de singles en France. Par la suite, il prend le nom de D.K. Dance en se tournant vers la musique house au début des années 1990.","Partenaire particulier est un groupe français de musique new wave.","fr:Partenaire_particulier",""],["Q672515",176,"chanson","Party Rock Anthem","PC","Party Rock Anthem est une chanson du groupe américain d'électro pop LMFAO en collaboration avec Lauren Bennett et GoonRock, extrait de leur second album studio Sorry for Party Rocking. La chanson est sortie en tant que premier single de l'album le 25 janvier 2011. Il interpole des paroles de la chanson Hustlin' qu'interprète Rick Ross.",113,"fr:Party_Rock_Anthem","https://upload.wikimedia.org/wikipedia/en/thumb/a/a2/Party_Rock_Anthem_%28feat._Lauren_Bennet_%26_GoonRock%29_-_Single.jpeg/330px-Party_Rock_Anthem_%28feat._Lauren_Bennet_%26_GoonRock%29_-_Single.jpeg"],["Q132167876",177,"chanson","Petit génie","C","Petit génie, sorti le 3 août 2023, est une chanson de Jungeli en collaboration avec Abou Debeing, Imen Es, Alonzo et Lossa. Elle devient rapidement un succès viral, se hissant plusieurs semaines non consécutives à la première place des classements en France et cumulant des millions de streams et de vues sur les plateformes numériques.",116,"fr:Petit_génie",""],["Q153029",178,"chanson","Poker Face","C","Poker Face est une chanson interprétée et écrite par l’artiste américaine Lady Gaga, issue de son premier album, The Fame. Elle est produite par RedOne et sort en tant que deuxième single de son album à la fin de l'année 2008 dans certains pays et au début 2009 pour le reste du monde. Le titre a un tempo assez rapide de dance-pop, comme son précédent single, Just Dance, avec une touche un peu plus sombre.",116,"fr:Poker_Face_(chanson_de_Lady_Gaga)","https://upload.wikimedia.org/wikipedia/en/thumb/3/3a/Poker_Face_by_Lady_Gaga_alternative_cover.png/330px-Poker_Face_by_Lady_Gaga_alternative_cover.png"],["Q64212442",179,"chanson","Pookie","C","Pookie est un single de la chanteuse Aya Nakamura sorti le 10 avril 2019.",null,"fr:Pookie_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/5/56/Aya_Nakamura_-_Pookie_%28Remix%29.png/330px-Aya_Nakamura_-_Pookie_%28Remix%29.png"],["Q115468",180,"chanson","Poupée de cire, poupée de son","C","Poupée de cire, poupée de son est une chanson française écrite et composée en 1965 par Serge Gainsbourg vraisemblablement d'après le 4e mouvement prestissimo de la Sonate pour piano no 1 en fa mineur op.2-1 de Beethoven.",103,"fr:Poupée_de_cire,_poupée_de_son","c:b/b6/1965_Eurovision_Song_Contest_-_France_Gall.jpg"],["Q2708219",181,"chanson","Pour que tu m'aimes encore","C","Pour que tu m'aimes encore est une chanson interprétée par la chanteuse canadienne Céline Dion. C'est le premier extrait de son album D'eux sorti en 1995. Elle est écrite et composée par Jean-Jacques Goldman.","Pour que tu m'aimes encore est une chanson interprétée par la chanteuse canadienne Céline Dion.","fr:Pour_que_tu_m'aimes_encore","https://upload.wikimedia.org/wikipedia/en/thumb/e/e8/Pour_que_tu_m%27aimes_encore_single.jpg/330px-Pour_que_tu_m%27aimes_encore_single.jpg"],["Q2000445",182,"chanson","Purple Rain","R","Purple Rain est une ballade de Prince et The Revolution. Ce troisième single porte le même titre que l'album et que le film, tous les supports sont sortis en 1984. La chanson est un mélange de Rock 'n' roll, de pop et de musique gospel et est considérée comme l'une de ses chansons phares, avec les titres When Doves Cry et 1999. Le single s'est classé à la seconde place aux États-Unis.","Purple Rain est une ballade de Prince et The Revolution.","fr:Purple_Rain_(chanson)","c:9/9c/Purple_Rain.png"],["Q3412892",183,"chanson","Quand la musique est bonne","C","Quand la musique est bonne est une chanson française écrite et interprétée par Jean-Jacques Goldman. Sortie en 1982, elle est le premier single issu de son deuxième album studio. Elle fait partie des plus grands titres du chanteur, notamment grâce à un refrain très entraînant.","Quand la musique est bonne est une chanson française écrite et interprétée par Jean-Jacques Goldman.","fr:Quand_la_musique_est_bonne",""],["Q3413921",184,"chanson","Que je t'aime","C","Que je t'aime est une chanson de Johnny Hallyday écrite par le parolier Gilles Thibaut et le compositeur Jean Renard. Sortie en 1969, elle s'inscrit parmi les plus grands succès du chanteur, demeure l'une des chansons favorites du public et compte parmi celles qu'Hallyday a le plus souvent inscrite à son tour de chant.","Que je t'aime est une chanson de Johnny Hallyday écrite par le parolier Gilles Thibaut et le compositeur Jean Renard.","fr:Que_je_t'aime_(chanson)",""],["Q605031",185,"chanson","Radio Ga Ga","C","Radio Ga Ga est une chanson du groupe de rock britannique Queen, sortie en single en 1984. Il s'agit du premier extrait de l'album The Works. Écrite par Roger Taylor, la chanson est un tube dans le monde entier; elle n'a cependant atteint que la 2e place dans les classements anglais, derrière Relax du groupe Frankie Goes to Hollywood. Elle a reçu un disque d'argent par la BPI. Le succès est plus modeste en France.","Radio Ga Ga est une chanson du groupe de rock britannique Queen, sortie en single en 1984.","fr:Radio_Ga_Ga","c:f/f7/Queen_%E2%80%93_Radio_Ga_Ga_%28vinyl_7%22_single%2C_Barbados%2C_1984%29.jpg"],["Q7281218",186,"chanson","Radioactive","C","Radioactive est une chanson du groupe de rock américain Imagine Dragons figurant sur leur EP inaugural Continued Silence et plus tard sur leur premier album studio Night Visions en tant que piste d'ouverture. Elle est envoyée pour la première fois sur les radios américaines le 2 avril 2012, et de nouveau le 29 octobre 2012.",112,"fr:Radioactive_(chanson_d'Imagine_Dragons)","https://upload.wikimedia.org/wikipedia/en/thumb/9/91/Imagine_Dragons_-_%22Radioactive%22_%28Single%29.jpg/330px-Imagine_Dragons_-_%22Radioactive%22_%28Single%29.jpg",{"cats":["chansons","groupes"]}],["Q944039",187,"chanson","Rapper's Delight","C","Rapper's Delight est une chanson du groupe américain The Sugarhill Gang, composée sur la trame du titre Good Times de Chic.",117,"fr:Rapper's_Delight","c:7/7b/Rapper%27s_Delight_%28Long_version%29_by_Sugarhill_Gang_US_12-inch_vinyl_red_label.png"],["Q3503685",188,"chanson","Rasputin","PC","Rasputin est une chanson du groupe disco Boney M., succès de l'année 1978. La chanson évoque Grigori Raspoutine, un mystique russe.","Rasputin est une chanson du groupe disco Boney M., succès de l'année 1978.","fr:Rasputin_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/3/30/Boney_M._-_Rasputin_%281978_single%29.jpg/330px-Boney_M._-_Rasputin_%281978_single%29.jpg"],["Q170165",189,"chanson","Rolling in the Deep","C","Rolling in the Deep est une chanson de la chanteuse britannique Adele, extraite de son deuxième album 21. La chanson a été écrite par Adele et Paul Epworth.","Rolling in the Deep est une chanson de la chanteuse britannique Adele, extraite de son deuxième album 21.","fr:Rolling_in_the_Deep","c:b/bd/Rolling_in_the_deep.gif"],["Q7387030",190,"chanson","S'il suffisait d'aimer","C","S'il suffisait d'aimer est une chanson de Céline Dion, écrite, composée et produite par Jean-Jacques Goldman.",null,"fr:S'il_suffisait_d'aimer_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/b/bb/S%27il_suffisait_d%27aimer_%28song%29.jpg/330px-S%27il_suffisait_d%27aimer_%28song%29.jpg"],["Q17146824",191,"chanson","Santiano","C","Santiano est une chanson d'Hugues Aufray sortie en 1961. Elle est l'adaptation française, par le parolier Jacques Plante, du chant de marins Santianna d'origine irlandaise.","Santiano est une chanson d'Hugues Aufray sortie en 1961.","fr:Santiano",""],["Q21857396",192,"chanson","Sapés comme jamais","C","Sapés comme jamais, sorti le 29 août 2015, est une chanson tirée de l'album de Maître Gims Mon cœur avait raison.",null,"fr:Sapés_comme_jamais","c:3/3a/Maitre_Gims.jpg"],["Q19756862",193,"chanson","See You Again","PC","See You Again est une chanson de Wiz Khalifa, en duo avec le chanteur Charlie Puth, sortie le 6 mars 2015. Cette chanson est un hommage à l'acteur Paul Walker, emblématique personnage des sept premiers opus de la saga Fast and Furious, et décédé en novembre 2013 dans un accident de voiture.","See You Again est une chanson de Wiz Khalifa, en duo avec le chanteur Charlie Puth, sortie le 6 mars 2015.","fr:See_You_Again_(chanson_de_Wiz_Khalifa)","https://upload.wikimedia.org/wikipedia/en/thumb/0/08/Wiz_Khalifa_Feat._Charlie_Puth_-_See_You_Again_%28Official_Single_Cover%29.png/330px-Wiz_Khalifa_Feat._Charlie_Puth_-_See_You_Again_%28Official_Single_Cover%29.png"],["Q1420378",194,"chanson","Seven Nation Army","PC","Seven Nation Army est un single du groupe de rock américain The White Stripes, sorti en 2003 et extrait de leur quatrième album, Elephant. Écrite et produite par Jack White, la chanson contient notamment un riff de guitare devenu célèbre, en faisant un titre fréquemment joué dans les stades ou fredonné par les supporters lors d'évènements sportifs.",111,"fr:Seven_Nation_Army","https://upload.wikimedia.org/wikipedia/en/thumb/6/62/7nationarmy.jpg/330px-7nationarmy.jpg"],["Q17544624",195,"chanson","Shake It Off","C","Shake It Off est le premier single du cinquième album de l'auteure-compositrice-interprète américaine Taylor Swift, 1989. Écrite par Taylor Swift, Max Martin et Shellback, cette chanson démarque la jeune femme de son style musical habituel qui est la country. Taylor a dévoilé la chanson lors d'une interview avec ses fans pour Yahoo! le 18 août 2014; le clip est sorti le même jour. Quelques heures plus tard, Shake It Off fut disponible sur toutes les plateformes de téléchargement.",115,"fr:Shake_It_Off_(chanson_de_Taylor_Swift)","c:f/fd/Eras_Tour_-_Minneapolis%2C_MN_-_1989_act_8.jpg"],["Q28132505",196,"chanson","Shape of You","C","Shape of You est une chanson de l’auteur-compositeur-interprète britannique Ed Sheeran. Elle sort le 6 janvier 2017 au format numérique, simultanément sur toutes les plateformes de téléchargement et en double exploitation avec le morceau Castle on the Hill sous les labels Asylum et Atlantic, en tant que premier single issu de son troisième album studio, ÷.","Shape of You est une chanson de l’auteur-compositeur-interprète britannique Ed Sheeran.","fr:Shape_of_You","https://upload.wikimedia.org/wikipedia/en/thumb/b/b4/Shape_Of_You_%28Official_Single_Cover%29_by_Ed_Sheeran.png/330px-Shape_Of_You_%28Official_Single_Cover%29_by_Ed_Sheeran.png"],["Q147409",197,"chanson","Single Ladies","C","Single Ladies est le deuxième single issu de l'album I Am... Sasha Fierce de l’artiste américaine Beyoncé. Il a été classé no 1 des 100 plus grands singles de l’année 2008 par le magazine Rolling Stone et no 2 sur la liste des meilleures chansons de 2008 par MTV. Il s’agit d’un tube à la fois musical et visuel qui est devenu instantanément un classique et qui se reconnaît désormais d’un simple petit geste de la main.","Single Ladies est le deuxième single issu de l'album I Am...","fr:Single_Ladies_(Put_a_Ring_on_It)","https://upload.wikimedia.org/wikipedia/en/thumb/4/44/Single_Ladies_%28Put_a_Ring_on_It%29_cover.png/330px-Single_Ladies_%28Put_a_Ring_on_It%29_cover.png"],["Q485907",198,"chanson","Smells Like Teen Spirit","R","Smells Like Teen Spirit est la première chanson de l'album Nevermind, du groupe américain Nirvana, sorti en 1991. Composée un peu avant l'enregistrement de l'album, elle doit son nom à une référence faite par une amie de Kurt Cobain, le chanteur du groupe, à une marque de déodorant nommée Teen Spirit alors que Cobain pensait y voir une allusion anarchiste. Le titre utilise une dynamique inspirée des Pixies qui joue sur l'alternance entre couplets calmes et refrain puissant avec un riff principal à quatre accords.","Smells Like Teen Spirit est la première chanson de l'album Nevermind, du groupe américain Nirvana, sorti en 1991.","fr:Smells_Like_Teen_Spirit","c:1/19/Nirvana-Smells-Like-Teen-Spirit.png",{"cats":["chansons","groupes"]}],["Q326287",199,"chanson","Smooth Criminal","PC","Smooth Criminal est une chanson de Michael Jackson, sortie en 1987 tiré de l'album Bad, puis, le 5 octobre 1988 comme le 7e single.",117,"fr:Smooth_Criminal","https://upload.wikimedia.org/wikipedia/en/thumb/3/33/Smooth_Criminal.jpg/330px-Smooth_Criminal.jpg"],["Q747869",200,"chanson","Sombre Dimanche","C","Sombre Dimanche est un morceau de jazz composé en 1933 par le musicien hongrois Rezső Seress, sur des paroles de László Jávor.",119,"fr:Sombre_Dimanche_(chanson)","c:6/61/Okeh_gloomy_sunday_6451.png",{"cats":["chansons","legendes"]}],["Q744564",201,"chanson","Somebody to Love","C","Somebody to Love est une chanson du groupe britannique Queen écrite par Freddie Mercury, sortie en single en 1976. Elle figure sur l'album A Day at the Races, sorti peu après.","Somebody to Love est une chanson du groupe britannique Queen écrite par Freddie Mercury, sortie en single en 1976.","fr:Somebody_to_Love_(chanson_de_Queen)","https://upload.wikimedia.org/wikipedia/en/thumb/d/dc/Stlove.jpg/330px-Stlove.jpg"],["Q60768202",202,"chanson","Someone You Loved","C","Someone You Loved est un single de l'auteur-compositeur-interprète écossais Lewis Capaldi. Il a été publié pour la première fois le 8 novembre 2018 par Vertigo Records et Universal Music, en tant que troisième single de son EP Breach; il a ensuite été inclus dans son premier album Divinely Uninspired to a Hellish Extent sorti en mai 2019. La chanson a été écrite par Lewis Capaldi, Samuel Romans, et les producteurs Thomas Barnes, Peter Kelleher et Benjamin Kohn.","Someone You Loved est un single de l'auteur-compositeur-interprète écossais Lewis Capaldi.","fr:Someone_You_Loved","https://upload.wikimedia.org/wikipedia/en/thumb/a/a6/Lewis_Capaldi_-_Someone_You_Loved.png/330px-Lewis_Capaldi_-_Someone_You_Loved.png"],["Q835804",203,"chanson","Sonne","C","Sonne est le titre d'une des chansons du groupe Rammstein. Elle apparait dans l'album Mutter. Elle a été interprétée lors de Völkerball. Le mot « Sonne » signifie « soleil » en allemand.","Sonne est le titre d'une des chansons du groupe Rammstein.","fr:Sonne_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/4/41/Sonnesingle.jpg/330px-Sonnesingle.jpg",{"cats":["chansons","groupes"]}],["Q3459071",204,"chanson","SOS d'un Terrien en détresse","C","SOS d'un Terrien en détresse est une chanson composée par Michel Berger et écrite par Luc Plamondon en 1978 pour l'opéra rock Starmania.",112,"fr:SOS_d'un_Terrien_en_détresse",""],["Q4922332",205,"chanson","Sous le vent","C","Sous le vent est une chanson du chanteur québécois Garou en duo avec Céline Dion, figurant sur son premier album studio, Seul, sorti en 2000, et extraite en single en 2001.",112,"fr:Sous_le_vent_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/d/d9/Celine-Dion-Sous-Le-Vent.jpg/330px-Celine-Dion-Sous-Le-Vent.jpg"],["Q192023",206,"chanson","Stairway to Heaven","E","Stairway to Heaven est une des chansons les plus célèbres du groupe de rock britannique Led Zeppelin. Composée par Jimmy Page et écrite par Robert Plant, elle paraît en 1971 sur l'album Led Zeppelin IV. Elle est présente dans bon nombre de classements musicaux: en 2000, VH1 l'élit troisième de sa liste des 100 plus grandes chansons de rock, et en 2003, elle arrive 31e du classement des 500 plus grandes chansons de tous les temps établi par le magazine Rolling Stone.","Stairway to Heaven est une des chansons les plus célèbres du groupe de rock britannique Led Zeppelin.","fr:Stairway_to_Heaven","c:5/53/Stairway_to_Heaven_by_Led_Zeppelin_US_promotional_single.jpg",{"cats":["chansons","groupes"]}],["Q370983",207,"chanson","Still D.R.E.","C","Still D.R.E. est le premier single du second album de Dr. Dre, 2001. Snoop Dogg apparaît dans l'introduction, au refrain et à la fin du morceau. Le riff principal s’inspire peut-être de Maybe Tomorrow du guitariste américain de jazz Grant Green. Still D.R.E est également la première musique que Dr. Dre ne compose pas intégralement mais avec un autre compositeur, en l'occurrence Scott Storch.","Still D.R.E.","fr:Still_D.R.E.","https://upload.wikimedia.org/wikipedia/en/thumb/4/42/Drdre2.JPG/330px-Drdre2.JPG"],["Q835013",208,"chanson","Sweet Child o' Mine","PC","Sweet Child O' Mine est une chanson de Guns N' Roses, troisième single de leur premier album, Appetite for Destruction. C'est l'un des plus grands succès commerciaux du groupe. Cette chanson est la seule du groupe à avoir atteint la première place du Billboard Hot 100.","Sweet Child O' Mine est une chanson de Guns N' Roses, troisième single de leur premier album, Appetite for Destruction.","fr:Sweet_Child_o'_Mine","https://upload.wikimedia.org/wikipedia/en/thumb/1/15/Guns_N%27_Roses_-_Sweet_Child_o%27_Mine.png/330px-Guns_N%27_Roses_-_Sweet_Child_o%27_Mine.png",{"cats":["chansons","groupes"]}],["Q1587664",209,"chanson","Sweet Dreams","R","Sweet Dreams est une chanson écrite, composée et interprétée par le duo britannique Eurythmics composé d’Annie Lennox et de Dave Stewart. Quatrième extrait de son second album, Sweet Dreams, sorti en 1983, elle est son premier succès et la chanson la plus connue du groupe. Arrivée jusqu'à la 1re position des charts américains et à la 2e position des charts anglais, la chanson a été classée 365e des « 500 plus grandes chansons de tous les temps » par le magazine Rolling Stone.",117,"fr:Sweet_Dreams_(Are_Made_of_This)","https://upload.wikimedia.org/wikipedia/en/thumb/0/00/Eurythmics_SDAMOT.jpg/330px-Eurythmics_SDAMOT.jpg"],["Q145677",210,"chanson","Take on Me","PC","Take on Me est une chanson du groupe norvégien a-ha, écrite et composée par Morten Harket, Magne Furuholmen et Pål Waaktaar-Savoy. Une première version de la chanson est enregistrée en 1984 et sortie en octobre de la même année; cette version passe relativement inaperçue auprès du grand public. La version à succès de Take on Me est enregistrée pour leur premier album studio Hunting High and Low. Cette version sort le 5 avril 1985 comme premier single de l'album.",114,"fr:Take_on_Me","https://upload.wikimedia.org/wikipedia/en/thumb/d/d5/A-ha_take_on_me-1stcover.jpg/330px-A-ha_take_on_me-1stcover.jpg"],["Q188770",211,"chanson","Telephone","C","Telephone est une chanson sortie en 2010, enregistrée et écrite par la chanteuse américaine Lady Gaga, issue de son second album The Fame Monster avec la participation de Beyoncé Knowles. Gaga écrit initialement la chanson pour Britney Spears, toutefois, cette dernière refuse finalement d’ajouter le morceau sur son album Circus. Gaga récupère alors la chanson pour son album, invitant Beyoncé en tant que collaboratrice vocale à la suite de sa propre invitation sur le titre Video Phone de Beyoncé.",115,"fr:Telephone_(chanson)","c:d/d8/Telephone_Logo.png"],["Q136335202",212,"chanson","The Fate of Ophelia","R","The Fate of Ophelia est une chanson de l'autrice-compositrice-interprète Taylor Swift, issue de son douzième album, The Life of a Showgirl. Il s'agit de la chanson d'ouverture et du premier single de l'album, sorti le 3 octobre 2025.",119,"fr:The_Fate_of_Ophelia","c:9/9c/Friedrich_Wilhelm_Theodor_Heyser_-_Ophelia.jpg"],["Q1165771",213,"chanson","The Final Countdown","R","The Final Countdown est une chanson du groupe de hard rock suédois Europe écrite par Joey Tempest. C'est le premier single issu du troisième album studio du groupe, The Final Countdown, sorti le 14 février 1986. C'est la chanson la plus connue du groupe. Elle a atteint la 1re place dans vingt-cinq pays, incluant la France. Aux États-Unis, le single a atteint la 8e place au Billboard Hot 100","The Final Countdown est une chanson du groupe de hard rock suédois Europe écrite par Joey Tempest.","fr:The_Final_Countdown_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/2/22/The_Final_Countdown_single.png/330px-The_Final_Countdown_single.png"],["Q478928",214,"chanson","The House of the Rising Sun","E","The House of the Rising Sun est une chanson traditionnelle de folk américaine. Elle est aussi connue sous le nom de Rising Sun Blues. De nombreuses versions de la chanson existent, car elle a été reprise maintes fois.","The House of the Rising Sun est une chanson traditionnelle de folk américaine.","fr:The_House_of_the_Rising_Sun",""],["Q517591",215,"chanson","The Show Must Go On","C","The Show Must Go On est une chanson du groupe de rock britannique Queen sortie en 1991, sous le label EMI Parlophone. Elle est issue de l'album Innuendo connu pour être l'un des plus aboutis de la carrière du groupe. Il s'agit aussi et surtout de la dernière chanson diffusée du vivant de Freddie Mercury, chanteur du groupe, alors déjà très affaibli par le VIH et le SIDA qui aura raison de lui le 24 novembre 1991 des suites d'une broncho-pneumonie.","The Show Must Go On est une chanson du groupe de rock britannique Queen sortie en 1991, sous le label EMI Parlophone.","fr:The_Show_Must_Go_On_(chanson_de_Queen)","c:f/f3/Grandville_Concert_%C3%A0_la_vapeur_1.jpg"],["Q159348",216,"chanson","They Don't Care About Us","PC","They Don't Care About Us est une chanson de Michael Jackson extraite du double album HIStory sorti en 1995. Ce morceau est le 4e single de l'album.","They Don't Care About Us est une chanson de Michael Jackson extraite du double album HIStory sorti en 1995.","fr:They_Don't_Care_About_Us","https://upload.wikimedia.org/wikipedia/en/thumb/d/d5/Mjtdcau.jpg/330px-Mjtdcau.jpg"],["Q380825",217,"chanson","Thriller","L","Thriller (prononcé:) est une chanson interprétée par Michael Jackson, avec la participation de Vincent Price, écrite et composée par Rod Temperton. Parue l'année précédente sur l'album Thriller, elle est le dernier single à en être extrait et sort le 2 novembre 1983.",119,"fr:Thriller_(chanson)","c:1/18/Thriller_logotipo.png"],["Q535566",218,"chanson","Titanium","C","Titanium est une chanson de David Guetta réalisée en collaboration avec la chanteuse australienne Sia. Il s'agit du 4e single extrait du 5e album studio du DJ, Nothing but the Beat. La chanson est écrite par Sia Furler, David Guetta, Giorgio Tuinfort et Afrojack, produit par Guetta, Tuinfort et Afrojack. Titanium sort le 8 août 2011 sur les plateformes de téléchargement. C'est la première chanson, des trois singles promotionnels de l'album avant d'être choisie en décembre 2011 comme single officiel.","Titanium est une chanson de David Guetta réalisée en collaboration avec la chanteuse australienne Sia.","fr:Titanium_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/1/1d/Titaniumsong.jpg/330px-Titaniumsong.jpg",{"cats":["chansons","electro"]}],["Q3530411",219,"chanson","Toi + Moi","C","Toi + Moi est le premier single du premier album du chanteur français Grégoire. Cette chanson est sortie le 30 juin 2008 et a été écrite et composée par le chanteur lui-même.","Toi + Moi est le premier single du premier album du chanteur français Grégoire.","fr:Toi_+_Moi_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/a/a6/Toi_%2B_moi_%28song%29.jpg/330px-Toi_%2B_moi_%28song%29.jpg"],["Q16035398",220,"chanson","Tourner dans le vide","C","Tourner dans le vide est le deuxième single de la chanteuse Indila, extrait de l'album Mini World. Le titre est écrit par Indila et composé et produit par Skalpovich. Le clip a été tourné au château de Ferrières.","Tourner dans le vide est le deuxième single de la chanteuse Indila, extrait de l'album Mini World.","fr:Tourner_dans_le_vide","https://upload.wikimedia.org/wikipedia/en/thumb/8/83/Tourner_dans_le_vide.jpeg/330px-Tourner_dans_le_vide.jpeg"],["Q14916720",221,"chanson","Tous les mêmes","C","Tous les mêmes est le troisième single du chanteur belge Stromae extrait de l'album Racine carrée sorti en août 2013.",null,"fr:Tous_les_mêmes","https://upload.wikimedia.org/wikipedia/en/thumb/b/bb/Tous-les-memes-by-stromae.jpg/330px-Tous-les-memes-by-stromae.jpg"],["Q61331036",222,"chanson","Tout oublier","C","Tout oublier est une chanson de la chanteuse belge Angèle, en featuring avec son frère aîné Roméo Elvis, sortie le 5 octobre 2018. C'est le cinquième extrait de son premier album Brol.",116,"fr:Tout_oublier","https://upload.wikimedia.org/wikipedia/en/thumb/5/5f/Angele-Tout_Oublier_single_cover.jpg/330px-Angele-Tout_Oublier_single_cover.jpg"],["Q379751",223,"chanson","Toxic","PC","Toxic est une chanson de l'artiste chanteuse américaine pop Britney Spears, coécrite et produite par Bloodshy & Avant et extraite du quatrième album de la chanteuse, In the Zone. La chanson est sortie le 13 janvier 2004, sous Jive Records en tant que deuxième single de l'album. Alors que les titres Boom Boom et Outrageous étaient pressentis l'un ou l'autre pour devenir le deuxième single de In the Zone, Britney Spears choisit finalement Toxic.",117,"fr:Toxic_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/2/21/Britney_Spears_Toxic.png/330px-Britney_Spears_Toxic.png"],["Q3541720",224,"chanson","Tu m'oublieras","C","Tu m'oublieras est une chanson d'amour disco-electropop, adaptée du titre You Will Forget d'Irma Jackson dont la musique a été composée par Marc Hillman puis reprise en France avec des paroles françaises d'Yves Dessca. Initialement enregistrée par Régine en 1980 sous le titre Tu oublieras..., elle est reprise par Jeane Manson en 1990 puis avec grand succès par Larusso en 1998, devenant n°1 des ventes en France avec plus de 1,2 million d'exemplaires vendus.",112,"fr:Tu_m'oublieras","https://upload.wikimedia.org/wikipedia/en/thumb/2/2f/Tu_m%27oublieras.jpg/330px-Tu_m%27oublieras.jpg"],["Q597783",225,"chanson","U Can't Touch This","C","U Can't Touch This est une chanson du rappeur américain MC Hammer sortie le 13 janvier 1990. Il s'agit d'une reprise du single Super Freak de Rick James.","U Can't Touch This est une chanson du rappeur américain MC Hammer sortie le 13 janvier 1990.","fr:U_Can't_Touch_This","https://upload.wikimedia.org/wikipedia/en/thumb/d/d0/Hammer_Touch.jpg/330px-Hammer_Touch.jpg"],["Q1770488",226,"chanson","Ue o muite arukō","C","Ue o muite arukō, est une chanson du chanteur japonais Kyū Sakamoto, sortie pour la première fois au Japon en 1961. Diffusée à l'international en 1963, elle connaît un immense succès et se classe notamment no 1 du Billboard Hot 100 aux États-Unis. Avec 13 millions d'exemplaires écoulés, il s'agit d'un des singles les plus vendus de tous les temps.","Ue o muite arukō, est une chanson du chanteur japonais Kyū Sakamoto, sortie pour la première fois au Japon en 1961.","fr:Ue_o_muite_arukō","c:1/14/Kyu_sakamoto.png"],["Q155447",227,"chanson","Umbrella","PC","Umbrella est une chanson de l'artiste barbadienne de RnB Rihanna, accompagnée d'un couplet de rap par Jay-Z. La chanson est coécrite par The-Dream, Christopher Stewart, Kuk Harell et Jay-Z puis composée et réalisée par Stewart. Elle sort le 2 avril 2007, comme premier single de son troisième album studio, Good Girl Gone Bad.","Umbrella est une chanson de l'artiste barbadienne de RnB Rihanna, accompagnée d'un couplet de rap par Jay-Z.","fr:Umbrella","https://upload.wikimedia.org/wikipedia/en/thumb/0/01/Rihanna_-_Umbrella.png/330px-Rihanna_-_Umbrella.png"],["Q3548354",228,"chanson","Un autre monde","C","Un autre monde est une chanson composée par le groupe Téléphone, sortie en 1984 dans l'album Un autre monde et chantée par Jean-Louis Aubert.",118,"fr:Un_autre_monde_(chanson)","",{"cats":["chansons","groupes"]}],["Q836667",229,"chanson","Under Pressure","PC","Under Pressure est une chanson écrite et interprétée par Queen et David Bowie. Sortie en single en octobre 1981, cette chanson est la première collaboration du groupe anglais avec un autre artiste, et figure sur leur album Hot Space sorti en 1982. Elle rencontre un grand succès à sa sortie: no 1 des ventes au Royaume-Uni, elle se classe dans le top 10 dans de nombreux pays européens.","Under Pressure est une chanson écrite et interprétée par Queen et David Bowie.","fr:Under_Pressure_(chanson)","c:b/b3/Queen_%26_David_Bowie_-_Under_Pressure.jpeg",{"cats":["chansons","groupes"]}],["Q18559542",230,"chanson","Uptown Funk","PC","Uptown Funk est une chanson du producteur britannique Mark Ronson et de l'artiste américain Bruno Mars parue le 10 novembre 2014 en format numérique. Elle se classe numéro un des ventes en France, au Royaume-Uni et aux États-Unis où elle passe quatorze semaines en tête du Billboard Hot 100. La chanson remporte deux Grammy Awards en 2016: enregistrement de l'année, et meilleure performance pop en duo ou en groupe.",114,"fr:Uptown_Funk","https://upload.wikimedia.org/wikipedia/en/thumb/a/a7/Mark_Ronson_-_Uptown_Funk_%28feat._Bruno_Mars%29_%28Official_Single_Cover%29.png/330px-Mark_Ronson_-_Uptown_Funk_%28feat._Bruno_Mars%29_%28Official_Single_Cover%29.png"],["Q626490",231,"chanson","Viva la Vida","PC","Viva la Vida est le second single du quatrième album studio du groupe de rock alternatif britannique Coldplay intitulé Viva la Vida or Death and All His Friends, qui est sorti le 7 mai 2008. Il s'agit du plus grand succès de Coldplay, numéro un aux États-Unis et au Royaume-Uni. Elle a reçu le Grammy Award de la meilleure prestation pop d'un duo ou groupe avec chant.",118,"fr:Viva_la_Vida_(chanson)","c:b/b2/Coldplay_-_Viva_la_Vida_or_Death_and_All_His_Friends.png"],["Q105137334",232,"chanson","Voilà","C","Voilà est une chanson interprétée, écrite et composée par Barbara Pravi, accompagnée par Igit et Lili Poe à l'écriture et la composition.",118,"fr:Voilà_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/f/f0/Barbara_Pravi_-_Voil%C3%A0.png/330px-Barbara_Pravi_-_Voil%C3%A0.png"],["Q132559200",233,"chanson","Voyage, Voyage","C","Voyage, Voyage est une chanson de la chanteuse Desireless et sortie en 1986 en tant que premier single de son premier album François.",117,"fr:Voyage,_Voyage","https://upload.wikimedia.org/wikipedia/en/thumb/3/38/Voyage_Voyage_Desireless_cover.jpg/330px-Voyage_Voyage_Desireless_cover.jpg"],["Q155894",234,"chanson","Waka Waka","PC","Waka Waka, en anglais, et Waka Waka en espagnol, reprise de la chanson Zangalewa interprétée par le groupe camerounais Golden sound par Shakira et le groupe sud-africain Freshlyground. Il s'agit de la musique officielle de la Coupe du monde de football de 2010 qui s'est déroulée en Afrique du Sud.",118,"fr:Waka_Waka_(This_Time_for_Africa)","https://upload.wikimedia.org/wikipedia/en/thumb/7/70/Shakirasinglewc.jpg/330px-Shakirasinglewc.jpg"],["Q13557314",235,"chanson","Wake Me Up","C","Wake Me Up est une chanson du producteur et DJ suédois Avicii en featuring avec le chanteur Aloe Blacc, extraite de son premier album studio, True. Le titre est sorti en tant que premier single de l'album le 17 juin 2013.",119,"fr:Wake_Me_Up_(chanson_d'Avicii)","https://upload.wikimedia.org/wikipedia/en/thumb/d/da/Avicii_Wake_Me_Up_Official_Single_Cover.png/330px-Avicii_Wake_Me_Up_Official_Single_Cover.png",{"cats":["chansons","electro"]}],["Q752873",236,"chanson","Waltzing Matilda","PC","Waltzing Matilda est l'une des chansons folkloriques australiennes les plus connues. Elle raconte l'histoire d'un journalier itinérant qui capture un mouton près de son campement de fortune puis le met dans son sac de nourriture. Quand le propriétaire arrive accompagné de policiers, le journalier se jette dans une mare proche. Depuis lors, son fantôme hante le lieu.","Waltzing Matilda est l'une des chansons folkloriques australiennes les plus connues.","fr:Waltzing_Matilda","c:f/f4/Original_Waltzing_Matilda_manuscript.jpg"],["Q32503",237,"chanson","Waterloo","C","Waterloo est une chanson d'ABBA sortie en 1974. Il s'agit du premier single tiré de leur second album, également intitulé Waterloo.","Waterloo est une chanson d'ABBA sortie en 1974.","fr:Waterloo_(chanson)","c:0/0d/Waterloo_by_ABBA_US_single_side-A.png"],["Q238564",238,"chanson","We Are the Champions","C","We Are the Champions est une chanson du groupe britannique Queen, sortie en single en 1977, avec We Will Rock You comme face B, titre avec lequel il s'enchaîne sur l'album News of the World. Écrite par Freddie Mercury, elle est le premier extrait de l'album News of the World. Ce morceau est devenu très populaire dans le monde sportif — surtout au football et au cricket — et salue notamment nombre de remise de titres sportifs.",119,"fr:We_Are_the_Champions","https://upload.wikimedia.org/wikipedia/en/thumb/5/5a/Wearethechampions.jpg/330px-Wearethechampions.jpg"],["Q308895",239,"chanson","We Are the World","L","We Are the World est une chanson caritative enregistrée par le supergroupe américain USA for Africa en 1985. Sortie sur l'album We Are the World, elle est écrite par Michael Jackson et Lionel Richie, alors que les réalisateurs artistiques en sont Quincy Jones et Michael Omartian. Le single a pour objectif de collecter des fonds pour lutter contre la famine en Éthiopie. L'événement, historique, réunit quelques-uns des artistes les plus célèbres du monde musical américain de l'époque.","We Are the World est une chanson caritative enregistrée par le supergroupe américain USA for Africa en 1985.","fr:We_Are_the_World","c:9/92/Michael_Jackson_autographing_%27We_Are_The_World%27_posters_1985.jpg"],["Q326487",240,"chanson","We Will Rock You","C","We Will Rock You est une chanson du groupe britannique Queen, sortie en single en 1977, avec We Are the Champions comme face A, titre avec lequel il s'enchaîne sur l'album. Écrite par Brian May, elle est extraite de l'album News of the World sorti la même année.",119,"fr:We_Will_Rock_You","https://upload.wikimedia.org/wikipedia/fr/thumb/0/05/News_of_the_World_%28album%29.jpg/330px-News_of_the_World_%28album%29.jpg",{"cats":["chansons","groupes"]}],["Q944632",241,"chanson","What a Wonderful World","PC","What a Wonderful World est un standard de jazz américain composé et écrit par Bob Thiele et George David Weiss pour Louis Armstrong, qui l'enregistre en 1967 en single jazz symphonique chez ABC Records. Cet hymne pour la paix et l'amour est un de ses plus importants et ultimes succès emblématiques international, vendu à plus d’un million d’exemplaires dans le monde.",115,"fr:What_a_Wonderful_World","c:c/c5/Louis_Armstrong_%281955%29.jpg"],["Q157355",242,"chanson","Wind of Change","PC","Wind of Change est une chanson du groupe de hard rock allemand Scorpions, composée en 1990 par le chanteur du groupe Klaus Meine et issue de l'album Crazy World. Elle est sortie en single l'année suivante.",116,"fr:Wind_of_Change_(chanson)","c:f/fd/Scorpions_-_07.jpg",{"cats":["chansons","groupes"]}],["Q1479183",243,"chanson","Without Me","C","Without Me est une chanson du rappeur américain Eminem. C'est le premier single extrait de son quatrième album intitulé The Eminem Show sorti en 2002. Without Me a été numéro 1 dans de nombreux pays.","Without Me est une chanson du rappeur américain Eminem.","fr:Without_Me_(chanson_d'Eminem)","https://upload.wikimedia.org/wikipedia/en/thumb/a/ad/Eminem_-_Without_Me_CD_cover.jpg/330px-Eminem_-_Without_Me_CD_cover.jpg"],["Q1045517",244,"chanson","Wonderwall","PC","Wonderwall est une chanson du groupe Oasis sortie en 1995 sur l'album Morning Glory?. C'est incontestablement la chanson la plus célèbre du groupe. Véritable phénomène musical, ce titre a contribué en grande partie au succès de l'album, et ce dès sa sortie. En 2010, la radio XFM a réalisé un gigantesque sondage pour déterminer les 1000 meilleures chansons anglaises de rock de tous les temps. Wonderwall arrivait en septième position.","Wonderwall est une chanson du groupe Oasis sortie en 1995 sur l'album Morning Glory?.","fr:Wonderwall_(chanson)","c:d/df/Oasis-band-concert-Montreal-Canada-Aug2002.jpg"],["Q529026",245,"chanson","Yellow","C","Yellow est une chanson du groupe britannique Coldplay, second single extrait de l'album Parachutes, paru en 2000. Soutenue par un grand nombre de passages à la radio, la chanson connut un grand succès et reste aujourd'hui l'une de leurs plus connues. Elle figurait dans la file d'attente de l'ancienne attraction de Disneyland Paris, Rock 'n' Roller Coaster.","Yellow est une chanson du groupe britannique Coldplay, second single extrait de l'album Parachutes, paru en 2000.","fr:Yellow_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/9/9b/Yellow_cover_art.JPG/330px-Yellow_cover_art.JPG"],["Q202698",246,"chanson","Yesterday","PC","Yesterday est une chanson des Beatles, composée et interprétée par Paul McCartney mais créditée à Lennon/McCartney. Elle est parue sur l’album Help! le 6 août 1965 au Royaume-Uni. Aux États-Unis, elle paraît en single le 13 septembre 1965, avec Act Naturally en face B. Par la suite, elle est incluse sur l’album américain Yesterday and Today le 15 juin 1966.","Yesterday est une chanson des Beatles, composée et interprétée par Paul McCartney mais créditée à Lennon/McCartney.","fr:Yesterday","https://upload.wikimedia.org/wikipedia/en/thumb/e/e5/Beatles-singles-yesterday.jpg/330px-Beatles-singles-yesterday.jpg"],["Q300973",247,"chanson","You Are Not Alone","C","You Are Not Alone est une chanson de Michael Jackson parue sur l'album HIStory le 20 juin 1995, puis sortie en tant que single le 15 août de la même année.",119,"fr:You_Are_Not_Alone_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/1/1e/You_Are_Not_Alone.jpg/330px-You_Are_Not_Alone.jpg"],["Q169298",248,"chanson","Zombie","L","Zombie est une chanson contestataire du groupe irlandais Cranberries, apparue sur l'album No Need to Argue en 1994. Elle évoque le conflit nord-irlandais, appelé aussi Les Troubles, et contient des références à l'insurrection de Pâques 1916. Zombie rend également hommage aux victimes de l'attentat de l'IRA, le 20 mars 1993. Elle s'oppose aux différentes violences qu'a subit l'Irlande.","Zombie est une chanson contestataire du groupe irlandais Cranberries, apparue sur l'album No Need to Argue en 1994.","fr:Zombie_(chanson_des_Cranberries)","https://upload.wikimedia.org/wikipedia/en/thumb/1/16/The_Cranberries_-_Zombie.jpg/330px-The_Cranberries_-_Zombie.jpg"],["Q2385403",249,"chanson","Ça plane pour moi","C","Ça plane pour moi est une chanson de Plastic Bertrand parue en 1977. La musique est composée par Lou Deprijck et les paroles écrites par Yvan Lacomblez, dit Pipou. Bien qu'étant attribué à Plastic Bertrand sur la pochette, le morceau est en réalité chanté par Deprijck lui-même, qui est également le producteur du disque.","Ça plane pour moi est une chanson de Plastic Bertrand parue en 1977.","fr:Ça_plane_pour_moi","https://upload.wikimedia.org/wikipedia/en/thumb/1/1b/Plastic_Bertrand_-_%C3%87a_plane_pour_moi.jpg/330px-Plastic_Bertrand_-_%C3%87a_plane_pour_moi.jpg"],["Q8078543",250,"chanson","Évidemment","C","Évidemment est une chanson écrite et composée par Michel Berger et enregistrée par France Gall en 1987 pour son album Babacar, dont elle est le troisième single, sorti le 7 mars 1988.",117,"fr:Évidemment_(chanson)","https://upload.wikimedia.org/wikipedia/en/thumb/1/1f/Evidemment.jpg/330px-Evidemment.jpg"],["Q155016",251,"chanson","…Baby One More Time","R","...Baby One More Time est le premier single de la chanteuse américaine pop Britney Spears, sorti le 23 octobre 1998 aux États-Unis et en 1999 dans le reste du monde. La chanson figure sur son premier album...Baby One More Time. Dépassant le milliard de vues sur Youtube, ce single est perçu comme sa signature et a été un énorme succès commercial en se vendant à plus de 10 millions d'exemplaires, ce qui en fait l’un des singles les plus vendus de tous les temps et qui lança la carrière de Britney Spears.",119,"fr:…Baby_One_More_Time_(chanson)","c:a/ae/Baby_One_More_Time_S_logo.png"],["Q8360",252,"album","(What's the Story) Morning Glory?","E","Morning Glory? est le deuxième album du groupe de rock anglais Oasis, sorti le 2 octobre 1995 chez Creation Records. Il contient parmi les plus grands tubes d'Oasis comme Some Might Say, Champagne Supernova, Don't Look Back in Anger, et bien sûr Wonderwall qui connaît un très grand succès. Le son du groupe se fait moins brut que celui de Definitely Maybe avec des arrangements plus variés.","Morning Glory?","fr:(What's_the_Story)_Morning_Glory?","https://upload.wikimedia.org/wikipedia/en/thumb/b/b1/Oasis_-_%28What%27s_The_Story%29_Morning_Glory_album_cover.jpg/330px-Oasis_-_%28What%27s_The_Story%29_Morning_Glory_album_cover.jpg"],["Q17544553",253,"album","1989","R","1989 est le cinquième album de l'auteure-compositrice-interprète américaine Taylor Swift, sorti le 27 octobre 2014 aux États-Unis, sous le label Big Machine Records. Taylor a travaillé sur cet album entre 2013 et 2014, et a beaucoup collaboré avec les producteurs Max Martin et Shellback. Le titre de l'album représente l'année de naissance de Taylor.",118,"fr:1989_(album)","c:5/5d/1989_album_logo.png"],["Q155169",254,"album","21","PC","21 est le deuxième album studio de la chanteuse britannique Adele. Il est sorti le 24 janvier 2011 en Europe et le 22 février 2011 aux États-Unis. Cinq singles en ont été extraits: Rolling in the Deep, Someone Like You, Set Fire to the Rain, Rumour Has It et Turning Tables.","21 est le deuxième album studio de la chanteuse britannique Adele.","fr:21_(album_d'Adele)","c:9/96/Adele_someone_like_you.jpg"],["Q207502",255,"album","21st Century Breakdown","C","21st Century Breakdown est le huitième album studio du groupe de punk rock américain Green Day. Il est sorti le 15 mai 2009 sur le label Reprise. Il a reçu, en février 2010, le Grammy du Meilleur album rock lors de la cérémonie des Grammy Awards.","21st Century Breakdown est le huitième album studio du groupe de punk rock américain Green Day.","fr:21st_Century_Breakdown","https://upload.wikimedia.org/wikipedia/en/thumb/c/c8/Green_Day_-_21st_Century_Breakdown_cover.jpg/330px-Green_Day_-_21st_Century_Breakdown_cover.jpg"],["Q220756",256,"album","A Day at the Races","PC","A Day at the Races est le 5e album du groupe de rock britannique Queen, sorti en 1976. Il contient Somebody to Love qui sera second des charts lors de sa sortie en single. Tout comme A Night at the Opera, le nom de cet album est inspiré de celui d'un film des Marx Brothers.","A Day at the Races est le 5e album du groupe de rock britannique Queen, sorti en 1976.","fr:A_Day_at_the_Races_(album)","c:f/fc/QueenADayattheRacesfont.png"],["Q182518",257,"album","A Hard Day's Night","E","A Hard Day's Night est le troisième album des Beatles, paru le 10 juillet 1964 en Grande-Bretagne, sur le label Parlophone, en tant que bande originale de leur premier film, qui porte le même titre. Seules les chansons de la face A du disque figurent dans le long-métrage, bien que certaines de la face B aient été également composées à cet usage. L'album sort le 26 juin aux États-Unis, édité par United Artists, qui ne contient que les chansons entendues dans le film et des pièces orchestrales tirées de la bande son.",111,"fr:A_Hard_Day's_Night_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/e/e6/HardDayUK.jpg/330px-HardDayUK.jpg"],["Q300447",258,"album","A Kind of Magic","PC","A Kind of Magic est le douzième album studio du groupe de rock britannique Queen, sorti en juin 1986. Revitalisé par sa prestation très remarquée lors du Live Aid, le groupe accepte peu après de contribuer à la bande originale du film Highlander. En cours d'enregistrement, le quatuor décide de sortir un album à part entière, ce qui donne à celui-ci un côté assez hybride puisque six des neuf titres qui le composent peuvent être entendus dans le film sous des formes plus ou moins différentes.","A Kind of Magic est le douzième album studio du groupe de rock britannique Queen, sorti en juin 1986.","fr:A_Kind_of_Magic_(album)","https://upload.wikimedia.org/wikipedia/fr/thumb/3/3d/A_Kind_of_Magic_%28album%29.jpg/330px-A_Kind_of_Magic_%28album%29.jpg"],["Q109214",259,"album","A Momentary Lapse of Reason","R","A Momentary Lapse of Reason est le treizième album studio du groupe britannique de rock Pink Floyd, paru en septembre 1987.",117,"fr:A_Momentary_Lapse_of_Reason","https://upload.wikimedia.org/wikipedia/en/thumb/4/4e/MLoRLP01.jpg/330px-MLoRLP01.jpg"],["Q193477",260,"album","A Night at the Opera","R","A Night at the Opera est le quatrième album studio du groupe de rock britannique Queen, sorti en novembre 1975. Devenus célèbres avec leur album précédent, les membres du groupe sont toutefois en proie à des problèmes financiers. Ils se libèrent alors de leur contrat avec les studios Trident et retournent aussitôt enregistrer un nouvel album avec l'aide de Roy Thomas Baker.","A Night at the Opera est le quatrième album studio du groupe de rock britannique Queen, sorti en novembre 1975.","fr:A_Night_at_the_Opera_(album_de_Queen)","https://upload.wikimedia.org/wikipedia/en/thumb/4/4d/Queen_A_Night_At_The_Opera.png/330px-Queen_A_Night_At_The_Opera.png",{"cats":["chansons","groupes"]}],["Q207661",261,"album","A Saucerful of Secrets","R","A Saucerful of Secrets est le deuxième album studio du groupe rock britannique Pink Floyd. Il est enregistré entre 1967 et 1968 dans les studios Abbey Road et sort le 29 juin 1968 sur le label Columbia, la production est assurée par Norman Smith.","A Saucerful of Secrets est le deuxième album studio du groupe rock britannique Pink Floyd.","fr:A_Saucerful_of_Secrets_(album)","c:a/a7/A_Saucerful_of_Secrets.jpg"],["Q13171",262,"album","A Thousand Suns","PC","A Thousand Suns est le quatrième album studio du groupe de rock américain Linkin Park, sorti le 8 septembre 2010. L'album est intégralement écrit par le groupe et coproduit par le chanteur Mike Shinoda et Rick Rubin, avec qui ils avaient déjà collaboré pour produire Minutes to Midnight. Le premier single tiré de l'album, The Catalyst, est diffusé sur les radios, et mis en vente en ligne le 2 août 2010.","A Thousand Suns est le quatrième album studio du groupe de rock américain Linkin Park, sorti le 8 septembre 2010.","fr:A_Thousand_Suns","https://upload.wikimedia.org/wikipedia/en/thumb/a/af/A_Thousand_Suns_Cover2.jpg/330px-A_Thousand_Suns_Cover2.jpg"],["Q173643",263,"album","Abbey Road","M","Abbey Road est le onzième album original publié par les Beatles, paru le 12 septembre 1969 en France, le 26 septembre 1969 au Royaume-Uni, et le 1er octobre aux États-Unis et au Canada. Bien que sa sortie précède celle de Let It Be, paru en mai 1970, c'est le dernier album enregistré par les « Fab Four ».",117,"fr:Abbey_Road_(album)","c:a/a4/The_Beatles_Abbey_Road_album_cover.jpg"],["Q85189613",264,"album","After Hours","PC","After Hours est le quatrième album studio du chanteur canadien The Weeknd, sorti en 2020.",null,"fr:After_Hours_(album_de_The_Weeknd)","https://upload.wikimedia.org/wikipedia/en/thumb/c/c1/The_Weeknd_-_After_Hours.png/330px-The_Weeknd_-_After_Hours.png"],["Q1952903",265,"album","Ainsi soit je...","C","Ainsi soit je... est le deuxième album de Mylène Farmer, sorti le 14 mars 1988.","Ainsi soit je...","fr:Ainsi_soit_je...","c:3/39/Logo_Ainsi_soit_je.jpg"],["Q498054",266,"album","All Eyez on Me","R","All Eyez on Me est le quatrième album studio du rappeur américain 2Pac, sorti le 13 février 1996. C'est son premier album sorti chez Death Row Records, et le dernier sorti de son vivant. Cet album est reconnu comme l'un des plus importants des années 1990 et l'un des plus influents de l'histoire du hip-hop. Il s'agit du tout premier double album de l'histoire du hip-hop pour un artiste solo.","All Eyez on Me est le quatrième album studio du rappeur américain 2Pac, sorti le 13 février 1996.","fr:All_Eyez_on_Me","https://upload.wikimedia.org/wikipedia/en/thumb/1/16/Alleyezonme.jpg/330px-Alleyezonme.jpg"],["Q151714",267,"album","American Idiot","R","American Idiot est le septième album studio du groupe américain de punk rock Green Day, sorti le 21 septembre 2004 sur le label Reprise Records. Le groupe construit cet album comme un opéra-rock qui retrace des épisodes de la vie de Jesus of Suburbia, antihéros imaginé par le chanteur et guitariste Billie Joe Armstrong. Frustré par sa vie, il décide de quitter sa banlieue pour aller chercher une vie meilleure en ville.",118,"fr:American_Idiot","c:d/de/American_Idiot.PNG",{"cats":["chansons","groupes"]}],["Q206216",268,"album","Animals","E","Animals est le dixième album studio du groupe britannique de rock progressif Pink Floyd, sorti le 21 janvier 1977 au Royaume-Uni.",116,"fr:Animals_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/7/74/Pink_Floyd-Animals-Frontal.jpg/330px-Pink_Floyd-Animals-Frontal.jpg"],["Q270690",269,"album","Appetite for Destruction","R","Appetite for Destruction est le premier album du groupe de hard rock américain Guns N' Roses.",null,"fr:Appetite_for_Destruction","https://upload.wikimedia.org/wikipedia/en/thumb/6/60/GunsnRosesAppetiteforDestructionalbumcover.jpg/330px-GunsnRosesAppetiteforDestructionalbumcover.jpg",{"cats":["chansons","groupes"]}],["Q162392",270,"album","Arrival","PC","Arrival est le quatrième album du groupe suédois ABBA, sorti le 11 octobre 1976 sur le label Polar Music.",null,"fr:Arrival_(album_d'ABBA)","https://upload.wikimedia.org/wikipedia/en/thumb/7/71/ABBA_-_Arrival.png/330px-ABBA_-_Arrival.png"],["Q2743297",271,"album","Artpop","PC","Artpop est le quatrième album studio de Lady Gaga, sorti le 11 novembre 2013. Il est édité par Interscope Records et accompagné par une application mobile téléchargeable gratuitement. Les premiers singles issus de cet album, Applause et Do What U Want, sont sortis respectivement en août et octobre 2013. Deux singles promotionnels sont apparus, Venus en octobre et Dope en novembre. Le troisième single intitulé G.U.Y. est sorti le 28 mars 2014.","Artpop est le quatrième album studio de Lady Gaga, sorti le 11 novembre 2013.","fr:Artpop","https://upload.wikimedia.org/wikipedia/fr/thumb/4/49/Lady_Gaga_-_ARTPOP_logo2.png/330px-Lady_Gaga_-_ARTPOP_logo2.png"],["Q55934491",272,"album","Astroworld","C","Astroworld, parfois stylisé ASTROWORLD, est le troisième album studio du rappeur américain Travis Scott, sorti le 3 août 2018, sur les labels Grand Hustle, Epic Records et Cactus Jack. Cet album est aussi le plus grand succès du rappeur. Le projet est certifié quatre fois platine",115,"fr:Astroworld_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/4/4b/Travis_Scott_-_Astroworld.png/330px-Travis_Scott_-_Astroworld.png"],["Q210122",273,"album","Atom Heart Mother","R","Atom Heart Mother est le cinquième album studio du groupe de rock progressif et psychédélique britannique Pink Floyd. Paru le 2 octobre 1970 sur le label Harvest, il est certifié disque d'or en France.","Atom Heart Mother est le cinquième album studio du groupe de rock progressif et psychédélique britannique Pink Floyd.","fr:Atom_Heart_Mother","https://upload.wikimedia.org/wikipedia/en/thumb/2/2e/AtomHeartMotherCover.jpeg/330px-AtomHeartMotherCover.jpeg"],["Q193950",274,"album","B'Day","PC","B'Day est le deuxième album studio de la chanteuse américaine de R'n'B Beyoncé, sorti le 4 septembre 2006 sur le label Columbia Records en collaboration avec Music World Music et Sony Urban Music. La sortie coïncide avec le 25e anniversaire de Beyoncé. À l'origine, l'album doit sortir en 2004, faisant suite à son premier album solo Dangerously in Love sorti en 2003.",118,"fr:B'Day","https://upload.wikimedia.org/wikipedia/commons/thumb/f/f3/Beyonce_-_BDay.svg/330px-Beyonce_-_BDay.svg.png"],["Q155715",275,"album","Back in Black","R","Back in Black est le 7e album du groupe de hard rock AC/DC, sorti le 25 juillet 1980. Il s'agit du premier album du groupe enregistré avec le chanteur Brian Johnson, remplaçant Bon Scott, le précédent chanteur, décédé cinq mois plus tôt et à qui l'album rend hommage.","Back in Black est le 7e album du groupe de hard rock AC/DC, sorti le 25 juillet 1980.","fr:Back_in_Black","c:9/92/ACDC_Back_in_Black.png",{"cats":["chansons","groupes"]}],["Q156670",276,"album","Back to Black","E","Back to Black est le deuxième album studio de la chanteuse et compositrice soul britannique Amy Winehouse sorti en octobre 2006 au Royaume-Uni et en mars 2007 en France. L'album s'inspire principalement de la relation tumultueuse de la chanteuse et de son ex-petit-ami et futur mari Blake Fielder-Civil, qui l'a temporairement laissée pour retourner vers son ex-petite amie.",114,"fr:Back_to_Black","c:a/aa/Amy_Winehouse_-_Back_To_Black_%28Deluxe_Edition%29.jpg"],["Q44142",277,"album","Bad (album)","L","Bad est le septième album solo de Michael Jackson et son troisième chez Epic Records. Coproduit par Michael Jackson, il est le troisième et dernier album produit par Quincy Jones. Sorti le 31 août 1987, ce disque fut probablement le plus attendu des années 1980 car il devait succéder à Thriller, l'album le plus vendu au monde.","Bad est le septième album solo de Michael Jackson et son troisième chez Epic Records.","fr:Bad_(album)","c:3/37/Bad_Album_Logo.png"],["Q776064",278,"album","Bat Out of Hell","R","Bat Out of Hell est le deuxième album de Meat Loaf, sorti le 21 octobre 1977. Il est produit par Todd Rundgren.","Bat Out of Hell est le deuxième album de Meat Loaf, sorti le 21 octobre 1977.","fr:Bat_Out_of_Hell","https://upload.wikimedia.org/wikipedia/en/thumb/0/00/Bat_out_of_Hell.jpg/330px-Bat_out_of_Hell.jpg"],["Q207336",279,"album","Beatles for Sale","R","Beatles for Sale est le quatrième album des Beatles, paru le 4 décembre 1964 au Royaume-Uni. Il est conçu alors que la Beatlemania bat son plein, dans la foulée de la sortie de l'album A Hard Day's Night. Selon la volonté du manager Brian Epstein et du producteur George Martin, le groupe doit, à cette époque, respecter un rythme de deux albums par an, le second devant paraître à temps pour les fêtes de fin d'année.","Beatles for Sale est le quatrième album des Beatles, paru le 4 décembre 1964 au Royaume-Uni.","fr:Beatles_for_Sale","https://upload.wikimedia.org/wikipedia/en/thumb/4/40/Beatlesforsale.jpg/330px-Beatlesforsale.jpg"],["Q328482",280,"album","Black Sabbath","R","Black Sabbath est le 1er album studio du groupe rock éponyme qui deviendra, avec l'album Paranoid et sa chanson emblématique War Pigs, le symbole du courant heavy metal traditionnel. Ce premier album a été enregistré à Londres et est paru le 13 février 1970 au Royaume-Uni et le 1er juin 1970 aux États-Unis.",111,"fr:Black_Sabbath_(album)","c:e/e8/LP_%22Black_Sabbath%22_by_Black_Sabbath_%28Vertigo_label%29.png"],["Q192755",281,"album","Blackout","R","Blackout est le cinquième album studio de la chanteuse américaine Britney Spears, sorti le 26 octobre 2007 en Europe ainsi que le 30 octobre dans le monde, quatre ans après In the Zone. Britney commence l'écriture de chansons pour l'album en novembre 2003, et commence à expérimenter un son plus acoustique. Après son mariage avec le danseur Kevin Federline en 2004 et la naissance de son premier fils l'année suivante, elle commence l’enregistrement de Blackout en 2006 avec les producteurs J.R.",116,"fr:Blackout_(album_de_Britney_Spears)","https://upload.wikimedia.org/wikipedia/en/thumb/7/76/Britney_Spears_-_Blackout.png/330px-Britney_Spears_-_Blackout.png"],["Q218513",282,"album","Bleach","R","Bleach est le premier album studio du groupe américain de grunge Nirvana, sorti le 15 juin 1989 aux États-Unis sur le label Sub Pop en cassette et en vinyle 12\", puis au format CD au Royaume-Uni par Tupelo Records. Après le succès de l'album Nevermind en 1991, Sub Pop et Geffen Records ressortent conjointement une édition le 15 décembre 1992 avec deux morceaux en plus. En 2009, l'album est la meilleure vente de l'histoire du label Sub Pop avec plus de 1,7 million d'exemplaires vendus aux États-Unis.",117,"fr:Bleach_(album)","https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/Nirvana-Bleach.svg/330px-Nirvana-Bleach.svg.png"],["Q26450992",283,"album","Blonde","PC","Blonde est le deuxième album studio de l'auteur-compositeur-interprète américain de R&B Frank Ocean, sorti le 20 août 2016 par le label Boys Don't Cry et le dernier en date.",117,"fr:Blonde_(album_de_Frank_Ocean)","https://upload.wikimedia.org/wikipedia/en/thumb/a/a0/Blonde_-_Frank_Ocean.jpeg/330px-Blonde_-_Frank_Ocean.jpeg"],["Q164646",284,"album","Born This Way","PC","Born This Way est le troisième album studio de la chanteuse américaine Lady Gaga, sorti le 23 mai 2011 et produit par Interscope Records.",117,"fr:Born_This_Way","https://upload.wikimedia.org/wikipedia/en/thumb/c/c3/Born_This_Way_album_cover.png/330px-Born_This_Way_album_cover.png"],["Q752366",285,"album","Born to Run","R","Born to Run est le troisième album de Bruce Springsteen, qu'il a produit avec Jon Landau et Mike Appel, sorti en 1975. Il fut classé en troisième place des meilleures ventes des disques aux États-Unis.","Born to Run est le troisième album de Bruce Springsteen, qu'il a produit avec Jon Landau et Mike Appel, sorti en 1975.","fr:Born_to_Run","https://upload.wikimedia.org/wikipedia/en/thumb/7/7a/Born_to_Run_%28Front_Cover%29.jpg/330px-Born_to_Run_%28Front_Cover%29.jpg"],["Q124691269",286,"album","Brat","R","Brat est le sixième album studio de la chanteuse britannique Charli XCX, sorti le 7 juin 2024.",null,"fr:Brat","c:6/60/Charli_XCX_-_Brat_%28album_cover%29.png"],["Q57313098",287,"album","Brol","C","Brol est le premier album studio de la chanteuse belge Angèle, sorti le 5 octobre 2018.",null,"fr:Brol","https://upload.wikimedia.org/wikipedia/en/thumb/1/1f/Ang%C3%A8le_%E2%80%93_Brol.png/330px-Ang%C3%A8le_%E2%80%93_Brol.png"],["Q219425",288,"album","Californication","PC","Californication (prononcé en anglais:) est le septième album studio enregistré par le groupe californien de funk rock Red Hot Chili Peppers, paru le 8 juin 1999 chez Warner Bros. De nouveau produit par Rick Rubin, il marque le retour de John Frusciante à la guitare, après plusieurs années de dépendance aux drogues, et le départ de Dave Navarro. Il coïncide aussi avec un changement dans leur musique: un son plus funk rock, des chansons plus structurées et des riffs plus mélodiques.",117,"fr:Californication_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/d/df/RedHotChiliPeppersCalifornication.jpg/330px-RedHotChiliPeppersCalifornication.jpg"],["Q2717350",289,"album","Cheese","C","Cheese est le premier album de Stromae sorti le 14 juin 2010.",null,"fr:Cheese_(album)","c:6/6d/Cheese_logo.png"],["Q86919359",290,"album","Chromatica","C","Chromatica est le sixième album studio de la chanteuse américaine Lady Gaga. Cet album fait suite à A Star Is Born, dernier projet musical de Lady Gaga et à Joanne, dernier album studio de la chanteuse. À la suite de la pandémie de Covid-19, la sortie de l'album a été repoussée du 10 avril au 29 mai 2020. Il est produit par Interscope Records et Streamline Records. Le premier single de cet album, Stupid Love, a été dévoilé le 28 février.","Chromatica est le sixième album studio de la chanteuse américaine Lady Gaga.","fr:Chromatica","https://upload.wikimedia.org/wikipedia/en/thumb/d/d6/Lady_Gaga_-_Chromatica_%28Official_Album_Cover%29.png/330px-Lady_Gaga_-_Chromatica_%28Official_Album_Cover%29.png"],["Q19345",291,"album","Circus","PC","Circus est le sixième album studio de la chanteuse américaine Britney Spears, paru le 28 novembre 2008 en Europe et le 2 décembre aux États-Unis, jour du vingt-septième anniversaire de la chanteuse. Britney commence à travailler sur cet album au début de l’année 2008 avec une palette de producteurs, comprenant certains de ses producteurs, à l'image de Bloodshy & Avant et Danja. L'album se compose essentiellement de musique pop et dance-pop.",118,"fr:Circus_(album_de_Britney_Spears)","https://upload.wikimedia.org/wikipedia/en/thumb/e/e1/Circus-_Album.png/330px-Circus-_Album.png"],["Q109642385",292,"album","Civilisation","C","Civilisation est le quatrième album studio du rappeur français Orelsan sorti le 19 novembre 2021. L'album est produit par les labels 7th Magnitude et 3e Bureau pour la maison de disque Wagram Music et édité par Warner Chappell Music France.","Civilisation est le quatrième album studio du rappeur français Orelsan sorti le 19 novembre 2021.","fr:Civilisation_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/d/dc/Orelsan_-_Civilisation.png/330px-Orelsan_-_Civilisation.png"],["Q1944486",293,"album","Come On Over","C","Come On Over est le troisième album de Shania Twain. Dévoilant sa vraie personnalité, elle s'implique davantage dans l'écriture des chansons. Avec 40 millions d'exemplaires vendus à travers le monde, c'est l'un des albums les plus vendus de l'histoire.","Come On Over est le troisième album de Shania Twain.","fr:Come_On_Over_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/0/0b/ShaniaTwainComeOnOver.png/330px-ShaniaTwainComeOnOver.png"],["Q56322344",294,"album","Commando","C","Commando est le 2e album studio du rappeur français Niska sorti le 22 septembre 2017.",null,"fr:Commando_(album)",""],["Q151880",295,"album","Confessions on a Dance Floor","PC","Confessions on a Dance Floor est le dixième album studio de Madonna. Enregistré entre 2004 et 2005, il sort les 14 et 15 novembre 2005. L'œuvre se caractérise par une sonorité disco/pop/dance/funk/electro. Aujourd'hui, l'album s'est écoulé à plus de 12 millions d'exemplaires. Madonna reçoit un Grammy Award pour le Best Electronic/Dance Album de 2006.","Confessions on a Dance Floor est le dixième album studio de Madonna.","fr:Confessions_on_a_Dance_Floor","https://upload.wikimedia.org/wikipedia/en/thumb/d/df/Madonna_-_Confessions_on_a_Dance_Floor.png/330px-Madonna_-_Confessions_on_a_Dance_Floor.png"],["Q124504661",296,"album","Cowboy Carter","PC","Cowboy Carter est le huitième album studio de la chanteuse américaine Beyoncé, sorti le 29 mars 2024 sous Parkwood Entertainment et Columbia Records. L'album est le deuxième volet du projet de trilogie de Beyoncé, après Renaissance.",114,"fr:Cowboy_Carter","c:b/b3/Album_cover_for_Cowboy_Carter_by_Beyonc%C3%A9.png"],["Q30598066",297,"album","Ctrl","C","Ctrl est le premier album studio de l'auteure-compositrice-interprète américaine SZA sorti le 9 juin 2017.",null,"fr:Ctrl_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/b/bf/SZA_-_Ctrl_cover.png/330px-SZA_-_Ctrl_cover.png"],["Q28032829",298,"album","Cyborg","C","Cyborg est le deuxième album studio du rappeur français Nekfeu sorti le 2 décembre 2016 sur les labels Seine Zoo, Polydor et Universal.",113,"fr:Cyborg_(album_de_Nekfeu)","https://upload.wikimedia.org/wikipedia/en/thumb/1/1e/Nekfeu_-_Cyborg_cover.jpg/330px-Nekfeu_-_Cyborg_cover.jpg"],["Q987317",299,"album","D'eux","C","D'eux, est le quinzième album de Céline Dion sorti le 28 mars 1995. Écrit et réalisé par Jean-Jacques Goldman, il est l'album francophone le plus vendu de l'histoire de la musique et est certifié « disque de diamant » en France en 1995.","D'eux, est le quinzième album de Céline Dion sorti le 28 mars 1995.","fr:D'eux","https://upload.wikimedia.org/wikipedia/en/thumb/c/c3/D%27eux.jpg/330px-D%27eux.jpg"],["Q44104",300,"album","Dangerous","E","Dangerous est le huitième album studio de Michael Jackson et le quatrième chez Epic Records, sorti le 26 novembre 1991. Il marque le début de la collaboration du chanteur avec Teddy Riley qui en est le coproducteur.","Dangerous est le huitième album studio de Michael Jackson et le quatrième chez Epic Records, sorti le 26 novembre 1991.","fr:Dangerous_(album_de_Michael_Jackson)","c:3/32/Dangerous_Album_Logo2.png"],["Q127503",301,"album","Dangerously in Love","C","Dangerously in Love est le premier album solo de la chanteuse américaine de R'n'B Beyoncé, sorti le 20 juin 2003 chez Columbia Records. L'enregistrement du disque a eu lieu de 2002 à mars 2003 dans plusieurs studios, durant la pause de son ancien groupe Destiny's Child. Principalement orienté R'n'B et soul, il est surtout composé de chansons aux rythmes rapides et de ballades, reprenant des éléments caractéristiques du hip-hop et de la musique arabe.",117,"fr:Dangerously_in_Love","https://upload.wikimedia.org/wikipedia/en/thumb/8/84/Dangerously_In_Love_Album%282003%29.png/330px-Dangerously_In_Love_Album%282003%29.png"],["Q28494258",302,"album","Dans la légende","C","Dans la légende est le deuxième album studio du duo de rap français PNL sorti le 16 septembre 2016 sous le label QLF Records.",116,"fr:Dans_la_légende","https://upload.wikimedia.org/wikipedia/en/thumb/a/a0/PNL_-_Dans_la_l%C3%A9gende.png/330px-PNL_-_Dans_la_l%C3%A9gende.png"],["Q151657",303,"album","Death Magnetic","PC","Death Magnetic est le neuvième album studio du groupe de thrash metal Metallica. Il est sorti le 12 septembre 2008 sur le label Vertigo Records en Europe et Warner Bros Records en Amérique du Nord.","Death Magnetic est le neuvième album studio du groupe de thrash metal Metallica.","fr:Death_Magnetic","https://upload.wikimedia.org/wikipedia/en/thumb/5/53/Metallica_-_Death_Magnetic_cover.jpg/330px-Metallica_-_Death_Magnetic_cover.jpg"],["Q131564497",304,"album","DeBÍ TiRAR MáS FOToS","PC","DeBÍ TiRAR MáS FOToS, est le sixième album studio solo du rappeur et chanteur portoricain Bad Bunny. Il est sorti le 5 janvier 2025 chez Rimas Entertainment et fait suite à son précédent album Nadie Sabe Lo Que Va a Pasar Mañana.","DeBÍ TiRAR MáS FOToS, est le sixième album studio solo du rappeur et chanteur portoricain Bad Bunny.","fr:DeBÍ_TiRAR_MáS_FOToS","c:d/d1/Logotipo_de_DeB%C3%8D_TiRAR_M%C3%A1S_FOToS.jpg"],["Q86661715",305,"album","Destin","C","Destin est le deuxième album studio du rappeur Ninho, sorti le 22 mars 2019, soit un an après la sortie de la mixtape M.I.L.S 2.0.",117,"fr:Destin_(album)",""],["Q1901313",306,"album","Discovery","PC","Discovery est le deuxième album studio du groupe français Daft Punk, publié le 12 mars 2001 par le label Virgin Records. Cet album marque un changement de style, passant de la house de Chicago de leur premier album, Homework paru en 1997, à un style plus fortement inspiré du disco, du post-disco, du garage house et du R&B.","Discovery est le deuxième album studio du groupe français Daft Punk, publié le 12 mars 2001 par le label Virgin Records.","fr:Discovery_(album_de_Daft_Punk)","c:8/8a/Discovery_Daft_Punk.jpg"],["Q211292",307,"album","Dookie","R","Dookie est le troisième album studio du groupe californien de punk rock Green Day, sorti le 1er février 1994. Premier album du groupe produit par un label majeur, Reprise Records, il est enregistré en trois semaines aux studios Fantasy avec le producteur Rob Cavallo à la fin de l'été 1993.","Dookie est le troisième album studio du groupe californien de punk rock Green Day, sorti le 1er février 1994.","fr:Dookie","c:7/74/GreenDay_Dookie.png",{"cats":["chansons","groupes"]}],["Q56650719",308,"album","El mal querer","C","El mal querer est le deuxième album studio de la chanteuse espagnole Rosalía, sorti le 2 novembre 2018.",null,"fr:El_mal_querer","https://upload.wikimedia.org/wikipedia/en/thumb/e/e9/Rosal%C3%ADa_El_mal_querer.png/330px-Rosal%C3%ADa_El_mal_querer.png"],["Q904457",309,"album","Falling into You","C","Falling into You est le seizième album de Céline Dion et son quatrième anglophone, sorti le 8 mars 1996. Il est l'un des albums les plus vendus de l'histoire, avec des ventes estimées à 32 millions d'exemplaires à travers le monde, dont plus de 12 millions aux États-Unis, ce qui lui a valu comme certification un disque de diamant.","Falling into You est le seizième album de Céline Dion et son quatrième anglophone, sorti le 8 mars 1996.","fr:Falling_into_You","https://upload.wikimedia.org/wikipedia/en/thumb/c/c2/Falling_into_You.png/330px-Falling_into_You.png"],["Q842214",310,"album","Fearless","R","Fearless est le deuxième album studio de la chanteuse de country pop américaine Taylor Swift, sorti le 11 novembre 2008 à l'âge de 18 ans, sous le label indépendant Big Machine Records. Toutes les chansons ont été écrites par Taylor Swift ou coécrite avec Liz Rose. L'album a reçu le Grammy Award de l'album de l'année en 2010. Taylor Swift est donc devenue la plus jeune artiste de l'histoire de la musique à remporter un Grammy Awards pour l'album de l'année.",119,"fr:Fearless_(album_de_Taylor_Swift)","c:c/c1/Taylor_Swift_%285203982915%29.jpg"],["Q167554",311,"album","Femme Fatale","C","Femme Fatale est le septième album studio de la chanteuse américaine Britney Spears, sorti le 28 mars 2011 en France et le 29 dans le reste du monde sous le label Jive Records. Enregistré entre 2009 et 2011, l'album comporte des travaux réalisés avec des collaborateurs de longue date, Max Martin et Dr. Luke, qui sont les producteurs délégués de l'album. Ceux-ci confirment alors qu'ils travaillent avec Britney sur de nouvelles chansons pour la sortie d'un album après la tournée mondiale de la chanteuse en 2009.",119,"fr:Femme_Fatale_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/b/b9/Britney_Spears_-_Femme_Fatale.png/330px-Britney_Spears_-_Femme_Fatale.png"],["Q20668963",312,"album","Feu","C","Feu est le premier album studio du rappeur français Nekfeu sorti le 8 juin 2015 sur les labels Seine Zoo, Polydor et Universal.",116,"fr:Feu_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/f/f2/Nekfeu_-_Feu_cover.jpg/330px-Nekfeu_-_Feu_cover.jpg"],["Q156710",313,"album","Fever","C","Fever est le huitième album studio de la chanteuse australienne Kylie Minogue, sorti le 1er octobre 2001 en Europe et en Australie sous le label Parlophone. L'album est sorti par la suite aux États-Unis le 26 février 2002. Kylie a collaboré avec des producteurs et des compositeurs comme Cathy Dennis, Rob Davis, Richard Stannard, Julian Gallagher, TommyD, Tom Nichols, Pascal Gabriel afin de réaliser un album dance-pop avec des influences disco et Europop.",117,"fr:Fever_(album_de_Kylie_Minogue)","c:d/d1/Kylie_Minogue_%22Tension_Tour%22_at_Allstate_Arena_IMG_2002.jpg"],["Q97620733",314,"album","Folklore","R","folklore est le huitième album studio de l'auteure-compositrice-interprète américaine Taylor Swift. Écrit pendant le confinement lié à la pandémie de Covid-19, cet album sort le 24 juillet 2020 chez Republic Records, onze mois après son album précédent, Lover. Il est généralement considéré comme un tournant dans la discographie et l'image de la chanteuse.","folklore est le huitième album studio de l'auteure-compositrice-interprète américaine Taylor Swift.","fr:Folklore_(album_de_Taylor_Swift)","https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/TS_folklore_Wordmark.svg/330px-TS_folklore_Wordmark.svg.png"],["Q76962209",315,"album","Future Nostalgia","PC","Future Nostalgia est le deuxième album studio de la chanteuse britannico-albanaise Dua Lipa. Il est sorti le 27 mars 2020 sous le label Warner Records.","Future Nostalgia est le deuxième album studio de la chanteuse britannico-albanaise Dua Lipa.","fr:Future_Nostalgia_(album_de_Dua_Lipa)","https://upload.wikimedia.org/wikipedia/en/thumb/f/f5/Dua_Lipa_-_Future_Nostalgia_%28Official_Album_Cover%29.png/330px-Dua_Lipa_-_Future_Nostalgia_%28Official_Album_Cover%29.png"],["Q131279728",316,"album","GNX","PC","GNX est le sixième album studio du rappeur américain Kendrick Lamar sorti en 2024 sur les labels PGLang et Interscope Records. L'album est sorti, sans aucune promotion et par « surprise » le 22 novembre 2024. GNX, intitulé ainsi d'après une version de la Buick Regal, est le premier album de Lamar après son départ de Top Dawg Entertainment et Aftermath Entertainment.",117,"fr:GNX","https://upload.wikimedia.org/wikipedia/en/thumb/9/93/Kendrick_Lamar_-_GNX.png/330px-Kendrick_Lamar_-_GNX.png"],["Q19060",317,"album","Got to Be There","PC","Got to Be There est le premier album solo de Michael Jackson, paru le 24 janvier 1972, sous le label Motown.",null,"fr:Got_to_Be_There_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/b/b2/Mj1971-got-to-be-there.jpg/330px-Mj1971-got-to-be-there.jpg"],["Q1129439",318,"album","Graduation","R","Graduation est le troisième album studio de Kanye West, sorti le 7 septembre 2007 en France et le 11 septembre aux États-Unis. Cet opus est le troisième du rappeur du label Roc-A-Fella. Il a remporté le Grammy Award du meilleur album de rap en 2008.",114,"fr:Graduation_(album_de_Kanye_West)","https://upload.wikimedia.org/wikipedia/en/thumb/7/70/Graduation_%28album%29.jpg/330px-Graduation_%28album%29.jpg"],["Q2698545",319,"album","Grease","C","Grease: The Original Soundtrack from the Motion Picture est la bande originale du film Grease sorti en 1978.",null,"fr:Grease_(bande_originale)","https://upload.wikimedia.org/wikipedia/fr/thumb/2/2f/Grease_%28film%29_Logo.png/330px-Grease_%28film%29_Logo.png"],["Q106634897",320,"album","Happier Than Ever","C","Happier Than Ever est le deuxième album de la chanteuse et compositrice américaine Billie Eilish, co-composé et produit par son frère Finneas O'Connell, sorti le 30 juillet 2021 sur le label Darkroom/Interscope. Il parait deux ans après son premier album, When We All Fall Asleep, Where Do We Go?.",119,"fr:Happier_Than_Ever","https://upload.wikimedia.org/wikipedia/en/thumb/4/45/Billie_Eilish_-_Happier_Than_Ever.png/330px-Billie_Eilish_-_Happier_Than_Ever.png"],["Q483778",321,"album","Hard Candy","C","Hard Candy est le onzième album studio de la chanteuse américaine Madonna mis en vente internationalement le 28 avril 2008 sous l'étiquette de la Warner. Cet opus est le dernier produit par la maison de disques Warner.",117,"fr:Hard_Candy_(album_de_Madonna)","c:6/68/Hard_Candy_logo_def.png"],["Q201816",322,"album","Help!","E","Help! est le cinquième album des Beatles, paru le 6 août 1965 au Royaume-Uni, et une semaine plus tard aux États-Unis. Il est préparé dans le cadre du film éponyme, le deuxième mettant en vedette le groupe. Ils l'enregistrent au cours de plusieurs sessions réparties entre les concerts et les tournages, entre février et juin 1965.","Help!","fr:Help!_(album)","c:f/f7/The_Beatles_-_Help_-_a_set_of_silhouette_as_a_roof_decoration_-_Penny_Lane%2C_Liverpool%2C_England_%282015-11-11_13-00-49_by_Loco_Steve%29.jpg"],["Q1036873",323,"album","Histoire de Melody Nelson","C","Histoire de Melody Nelson est un album de Serge Gainsbourg paru en 1971. C'est son premier album-concept. Il a été écrit en collaboration avec le compositeur et arrangeur Jean-Claude Vannier.","Histoire de Melody Nelson est un album de Serge Gainsbourg paru en 1971.","fr:Histoire_de_Melody_Nelson","c:6/68/Gainsbourg-Birkin-Italie-1976.png"],["Q44347",324,"album","HIStory: Past, Present and Future, Book I","R","HIStory: Past, Present and Future – Book I est le neuvième album studio de Michael Jackson, sorti en 1995 sous les labels Epic Records et MJJ Productions. Son titre s'appuie sur le jeu de mots « His story » et « History ».",114,"fr:History_(album_de_Michael_Jackson)","c:a/a1/HIStory_Album_Logo.png"],["Q125392346",325,"album","Hit Me Hard and Soft","PC","Hit Me Hard and Soft est le troisième album studio de la chanteuse et auteure-compositrice américaine Billie Eilish. L'artiste annonce l'album le 8 avril 2024 sur son compte Instagram après avoir fait diverses allusions au projet. À la suite de l'annonce de l'album, elle dévoile les dates de sa tournée mondiale, qui traverse seize pays.","Hit Me Hard and Soft est le troisième album studio de la chanteuse et auteure-compositrice américaine Billie Eilish.","fr:Hit_Me_Hard_and_Soft","c:2/21/Billie_Eilish_peforms_%22The_Diner%22_in_Inglewood_%28Dec_2024%29.png"],["Q275828",326,"album","Hot Space","PC","Hot Space est le dixième album studio du groupe de rock britannique Queen sorti le 21 mai 1982 chez EMI au Royaume-Uni et par Elektra Records aux États-Unis.",118,"fr:Hot_Space","c:d/d4/QueenHotSpacefont.png"],["Q752172",327,"album","Hotel California (album)","R","Hotel California est le cinquième album studio du groupe de rock américain Eagles, sorti en 1976.",null,"fr:Hotel_California_(album_des_Eagles)","c:f/f6/Hotel_California_Logo_3.jpg"],["Q19862",328,"album","Hybrid Theory","E","Hybrid Theory est le premier album du groupe américain Linkin Park, sorti le 24 octobre 2000 aux États-Unis sous le label Warner Bros. Records. L'album a rencontré un très grand succès commercial puisqu'il a été vendu entre 24 et 27 millions d'exemplaires dans le monde, dont 10 millions aux États-Unis, ce qui lui vaut un disque de diamant. Il a atteint la deuxième place du Billboard 200 et des positions élevées dans les autres classements de vente d'albums dans le monde.",115,"fr:Hybrid_Theory","https://upload.wikimedia.org/wikipedia/en/thumb/2/2a/Linkin_Park_Hybrid_Theory_Album_Cover.jpg/330px-Linkin_Park_Hybrid_Theory_Album_Cover.jpg",{"cats":["chansons","groupes"]}],["Q147006",329,"album","I Am... Sasha Fierce","PC","I Am… Sasha Fierce est le troisième album studio de l'artiste américaine de R'n'B Beyoncé. Sorti le 12 novembre 2008, chez Columbia Records, il est considéré comme un double album. Le premier disque I Am… comporte des ballades R'n'B et des chansons pop à tempo lent ou moyen, tandis que le second disque Sasha Fierce, intitulé d'après l'alter ego de Beyoncé, contient plus de chansons dansantes à tempo élevé qui se croisent avec de l'europop et de l'electropop.","I Am… Sasha Fierce est le troisième album studio de l'artiste américaine de R'n'B Beyoncé.","fr:I_Am..._Sasha_Fierce","c:b/b6/Beyonc%C3%A9_-_Sasha_Fierce_true_logo.png"],["Q847541",330,"album","Illmatic","PC","Illmatic est le premier album studio du rappeur américain Nas, sorti le 19 avril 1994 sur le label Columbia.",null,"fr:Illmatic","c:b/b8/Nas_-_Illmatic_%28Side_A%29.jpg"],["Q222001",331,"album","In Utero","R","In Utero est le troisième et dernier album studio du groupe américain de grunge Nirvana, publié par DGC Records le 13 septembre 1993 au Royaume-Uni, puis le 21 septembre 1993 aux États-Unis.",117,"fr:In_Utero_(album)","https://upload.wikimedia.org/wikipedia/commons/thumb/4/49/Nirvana-InUtero-logo.svg/330px-Nirvana-InUtero-logo.svg.png",{"cats":["chansons","groupes"]}],["Q210048",332,"album","Innuendo","PC","Innuendo est le quatorzième album studio du groupe de rock britannique Queen, sorti le 4 février 1991. Coproduit par le groupe et David Richards, il s'agit du premier album de Queen à être distribué par Hollywood Records aux États-Unis, tandis qu'il est distribué par Parlophone au Royaume-Uni. Innuendo est également le dernier album sorti du vivant de Freddie Mercury, qui meurt neuf mois après la sortie du disque, et le plus récent à être composé de matériel musical inédit.","Innuendo est le quatorzième album studio du groupe de rock britannique Queen, sorti le 4 février 1991.","fr:Innuendo_(album)","c:9/97/Grandville_Les_Myst%C3%A8res_de_l%27infini_3.jpg"],["Q44376",333,"album","Invincible","L","Invincible est le dixième et dernier album studio du chanteur Michael Jackson, son sixième album solo chez Epic Records, sorti le 30 octobre 2001.",111,"fr:Invincible_(album_de_Michael_Jackson)","c:0/0a/Invincible_Album_Logo_2.png"],["Q30738957",334,"album","Ipséité","C","Ipséité est le deuxième album studio du rappeur belge Damso sorti le 28 avril 2017 sous les labels 92i, Capitol et Universal.",114,"fr:Ipséité",""],["Q270083",335,"album","Jazz","PC","Jazz est le septième album du groupe de rock britannique Queen, sorti en 1978.",null,"fr:Jazz_(album)","https://upload.wikimedia.org/wikipedia/fr/thumb/1/12/Jazz_%28album%29.jpg/330px-Jazz_%28album%29.jpg"],["Q26898358",336,"album","Joanne","C","Joanne est le cinquième album studio de la chanteuse américaine Lady Gaga, sorti le 21 octobre 2016. Le premier single de cet opus est Perfect Illusion, paru le 9 septembre 2016, le deuxième single est Million Reasons, sorti le 8 novembre 2016. Un single promotionnel a vu le jour: A-YO sorti le 17 octobre 2016. Le troisième single, Joanne, sort le 22 décembre 2017 en Italie, puis le 26 janvier 2018 dans le monde entier.","Joanne est le cinquième album studio de la chanteuse américaine Lady Gaga, sorti le 21 octobre 2016.","fr:Joanne_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/f/fd/Lady_Gaga_-_Joanne_%28Official_Album_Cover%29.png/330px-Lady_Gaga_-_Joanne_%28Official_Album_Cover%29.png"],["Q182826",337,"album","Kill 'Em All","R","Kill 'Em All est le premier album officiel du groupe américain de thrash metal Metallica, sorti le 25 juillet 1983.",null,"fr:Kill_'Em_All","https://upload.wikimedia.org/wikipedia/en/thumb/5/5c/Metallica_-_Kill_%27Em_All_cover.jpg/330px-Metallica_-_Kill_%27Em_All_cover.jpg"],["Q3295515",338,"album","L'Album blanc","L","The Beatles, habituellement surnommé Album blanc, ou quelquefois Double blanc, à cause de sa pochette extérieure entièrement blanche, est un double album des Beatles sorti le 22 novembre 1968 contenant trente chansons originales. C'est le neuvième album du groupe mais le premier sous leur propre label, Apple Records. Les premières éditions sont numérotées individuellement.",112,"fr:The_Beatles_(album)","https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/The_White_Album.svg/330px-The_White_Album.svg.png"],["Q920654",339,"album","L'École du micro d'argent","C","L'École du Micro d'Argent est le troisième album studio du groupe de rap français IAM, sorti le 18 mars 1997 par les labels EMI, Delabel et Virgin.",116,"fr:L'École_du_micro_d'argent","https://upload.wikimedia.org/wikipedia/en/thumb/2/2c/IAM_ecole_du_micro_dargent.png/330px-IAM_ecole_du_micro_dargent.png"],["Q212846",340,"album","L.A. Woman","PC","L.A. Woman est le sixième album studio des Doors et le dernier sorti du vivant de Jim Morrison. L'album, beaucoup plus orienté blues rock que les autres productions du groupe, est enregistré entre novembre 1970 et janvier 1971, et ne sort qu'en avril 1971, peu avant la mort de Morrison.","L.A.","fr:L.A._Woman","https://upload.wikimedia.org/wikipedia/en/thumb/4/41/The_Doors_-_L.A._Woman.jpg/330px-The_Doors_-_L.A._Woman.jpg"],["Q1810133",341,"album","Le Roi Soleil","PC","Le Roi Soleil est une comédie musicale produite par Dove Attia et Albert Cohen, mise en scène et chorégraphiée par Kamel Ouali. Les paroles sont écrites par Lionel Florence et Patrice Guirao, et les musiques sont composées par un collège de compositeurs, dont Benoit Poher, Essaï Altounian et Cyril Paulus. Cette comédie musicale raconte la vie et les amours de Louis XIV, dit « le Roi Soleil ». La première du spectacle a eu lieu le 22 septembre 2005 au Palais des sports de Paris.",114,"fr:Le_Roi_Soleil","c:c/ca/Roi_Soleil_jnl_2.jpg"],["Q131392",342,"album","Led Zeppelin","R","Led Zeppelin est le premier album du groupe de rock britannique Led Zeppelin. Rapidement enregistré dans des conditions live, et seulement trois mois après la fondation du groupe par Jimmy Page, il sort le 13 janvier 1969 aux États-Unis et le 31 mars 1969 au Royaume-Uni et en Europe. Publié par le label Atlantic Records, il est produit par Jimmy Page. Cet album lance la carrière du groupe qui en publie un deuxième la même année, avant de devenir un des plus gros vendeurs des années 1970.","Led Zeppelin est le premier album du groupe de rock britannique Led Zeppelin.","fr:Led_Zeppelin_(album)","c:8/84/Hindenburg_burning.jpg"],["Q209539",343,"album","Led Zeppelin II","R","Led Zeppelin II est le deuxième album du groupe de rock britannique Led Zeppelin, sorti le 22 octobre 1969 sur le label Atlantic Records. Ce disque est parfois surnommé « Brown Bomber » en référence à la couleur dominante de sa pochette.",119,"fr:Led_Zeppelin_II","https://upload.wikimedia.org/wikipedia/en/thumb/2/20/Led_Zeppelin_-_Led_Zeppelin_II.jpg/330px-Led_Zeppelin_-_Led_Zeppelin_II.jpg"],["Q207438",344,"album","Led Zeppelin III","R","Led Zeppelin III est le troisième album du groupe de rock britannique Led Zeppelin, sorti le 5 octobre 1970 sur le label Atlantic Records. Il est enregistré en mai et juin 1970 principalement à la Headley Grange dans le comté d'Hampshire à l'aide du studio mobile des Rolling Stones et à Londres dans les Studios Olympic et Studios Island. Il est produit par le guitariste du groupe Jimmy Page assisté par les ingénieurs du son Andy Johns et Terry Manning.",114,"fr:Led_Zeppelin_III","https://upload.wikimedia.org/wikipedia/en/thumb/5/5f/Led_Zeppelin_-_Led_Zeppelin_III.png/330px-Led_Zeppelin_-_Led_Zeppelin_III.png"],["Q201940",345,"album","Led Zeppelin IV","E","Led Zeppelin IV est le titre généralement utilisé mais non officiel pour nommer le quatrième album du groupe de rock britannique Led Zeppelin sorti le 8 novembre 1971 et dont la pochette originale ne comprenait pas la moindre inscription, y compris sur la tranche.",116,"fr:Led_Zeppelin_IV","c:f/fa/Zeppelin_IV.jpg",{"cats":["chansons","groupes"]}],["Q23905116",346,"album","Lemonade","PC","Lemonade est le sixième album studio de la chanteuse américaine Beyoncé, sorti en 2016.",null,"fr:Lemonade_(album)","c:f/f2/Beyonce_-_The_Formation_World_Tour%2C_at_Wembley_Stadium_in_London%2C_England.jpg"],["Q65129278",347,"album","Les Étoiles vagabondes","C","Les Étoiles vagabondes est le troisième album studio du rappeur français Nekfeu sorti le 6 juin 2019 sur les labels Seine Zoo, Polydor et Universal. Une version nommée Les Étoiles vagabondes: Expansion sort le 21 juin 2019.",115,"fr:Les_Étoiles_vagabondes",""],["Q199585",348,"album","Let It Be (album)","L","Let It Be est le douzième et dernier album original publié par les Beatles, paru le 8 mai 1970 en Grande-Bretagne en coffret et dix jours plus tard aux États-Unis en album seul. Au moment de sa sortie, le groupe est déjà officiellement séparé. L'essentiel des chansons présentes sur ce disque a été enregistré plus d'un an avant, en janvier 1969, bien avant la réalisation de l'album Abbey Road, publié en septembre 1969.",116,"fr:Let_It_Be_(album_des_Beatles)","c:7/7a/The_Beatles_-_Let_It_Be.png"],["Q705543",349,"album","Let's Talk About Love","C","Let's Talk About Love est le dix-huitième album de Céline Dion, sorti d'abord le 14 novembre 1997 en Australie et les jours suivants dans le reste du monde. Cinquième album anglophone de la chanteuse québécoise, il est l'un des albums les plus vendus au monde (le deuxième le plus vendu de la chanteuse, juste après Falling into You vendu à 32 millions d'exemplaires.",117,"fr:Let's_Talk_About_Love_(album_de_Céline_Dion)","https://upload.wikimedia.org/wikipedia/en/thumb/4/48/Lets_talk_about_love.jpg/330px-Lets_talk_about_love.jpg"],["Q55598321",350,"album","Lithopédion","C","Lithopédion est le troisième album studio du rappeur belge Damso sorti le 15 juin 2018 sous les labels 92i, Capitol et Universal.",118,"fr:Lithopédion_(album)","",{"cats":["chansons","rap_fr"]}],["Q13172",351,"album","Living Things","C","Living Things est le cinquième album studio du groupe de rock américain Linkin Park. Il a été publié sous les labels Warner Bros. Records et Machine Shop Recordings, et est sorti le 20 juin 2012 au Japon et tout au long de la semaine suivante dans les autres parties du monde. La production a été assurée par le chanteur Mike Shinoda et le producteur Rick Rubin, qui avait également coproduit les deux précédents albums studio du groupe, Minutes to Midnight et A Thousand Suns.","Living Things est le cinquième album studio du groupe de rock américain Linkin Park.","fr:Living_Things_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/c/c9/Linkin_Park_-_Living_Things.jpg/330px-Linkin_Park_-_Living_Things.jpg"],["Q276546",352,"album","Load","R","Load est le 6e album studio du groupe de heavy metal américain, Metallica. Il est sorti le 4 juin 1996 sur le label Vertigo Records pour l'Europe et Elektra Records pour l'Amérique du Nord et a été produit par Bob Rock, James Hetfield et Lars Ulrich.","Load est le 6e album studio du groupe de heavy metal américain, Metallica.","fr:Load_(album)","https://upload.wikimedia.org/wikipedia/fr/thumb/a/ad/Load_%28album%29.jpg/330px-Load_%28album%29.jpg"],["Q208340",353,"album","Loud","C","Loud est le cinquième album studio de la chanteuse barbadienne Rihanna, sorti le 12 novembre 2010 par Def Jam Recordings. Les sessions d'enregistrement et de production de l'album ont eu lieu au cours de février à août 2010, partiellement au cours de la tournée de Rihanna, Last Girl on Earth Tour. Rihanna a travaillé avec plusieurs producteurs de disques, tel que StarGate, The Runners, Polow da Don, Tricky Stewart, et Alex da Kid, entre autres. Loud intègre fortement de la musique de genre dance-pop et R&B.",109,"fr:Loud_(album_de_Rihanna)","https://upload.wikimedia.org/wikipedia/en/thumb/d/d1/Rihanna_-_Loud.png/330px-Rihanna_-_Loud.png"],["Q155593",354,"album","Made in Heaven","PC","Made In Heaven est un album studio du groupe de rock britannique Queen, sorti en 1995. Il a été produit par Queen avec les parties vocales enregistrées par Freddie Mercury avant sa mort. Certaines chansons étaient déjà connues du public avant la sortie de l'album dans des versions différentes, comme I Was Born to Love You et Made in Heaven sur l'album solo de Freddie Mercury Mr.","Made In Heaven est un album studio du groupe de rock britannique Queen, sorti en 1995.","fr:Made_in_Heaven_(album_de_Queen)","c:0/00/Freddie_Bronzestatue_rueckansicht.jpg"],["Q177943",355,"album","Madonna","PC","Madonna/The First album est le titre du premier album de l'artiste américaine Madonna sorti le 27 juillet 1983 sous le label Sire Records. Il est ré-édité en 1985 sur le marché européen et renommé Madonna – The First Album. En 1982, alors qu'elle se lance dans une carrière de chanteuse à New York, Madonna rencontre Seymour Stein, le président de Sire, qui lui fait signer un contrat après l'écoute de son single Everybody. Le succès de ce single encourage Sire à signer un contrat pour l'enregistrement d'un album.",118,"fr:Madonna_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/f/f6/Madonna%2C_debut_album_cover.png/330px-Madonna%2C_debut_album_cover.png"],["Q60676411",356,"album","Magical Mystery Tour","R","Magical Mystery Tour est le 9e album studio des Beatles, sorti le 27 novembre 1967 aux États-Unis parallèlement au film homonyme, tandis que la version britannique, mise en vente le 8 décembre suivant, est leur 13e et dernier E.P., cette fois sur deux disques. Cette bande originale contient six des sept titres liés au film, composés et enregistrés durant l'été et l'automne 1967. Cette sortie cadre dans la foulée du succès de Sgt. Pepper's Lonely Hearts Club Band et de la mort de Brian Epstein.",119,"fr:Magical_Mystery_Tour_(album)","c:5/59/The_Beatles%2C_Magical_Mystery_Tour_%28Logo%29.png"],["Q187507",357,"album","Master of Puppets","E","Master of Puppets, sorti le 3 mars 1986, est le troisième album studio du groupe de thrash metal Metallica. C'est le dernier album du groupe avec le bassiste Cliff Burton, ce dernier décède en effet dans un accident de bus en Suède lors de la tournée de promotion de l'album.","Master of Puppets, sorti le 3 mars 1986, est le troisième album studio du groupe de thrash metal Metallica.","fr:Master_of_Puppets","https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/Master-of-puppets-metallica-logo.svg/330px-Master-of-puppets-metallica-logo.svg.png",{"cats":["chansons","groupes"]}],["Q131919251",358,"album","Mayhem","PC","MAYHEM est le septième album studio de la chanteuse et compositrice américaine Lady Gaga, sorti le 7 mars 2025.",null,"fr:Mayhem_(album_de_Lady_Gaga)","c:e/ed/Mayhem_Logo_718x358.png"],["Q205458",359,"album","Meddle","R","Meddle est le sixième album studio du groupe de rock anglais Pink Floyd, sorti le 30 octobre 1971 chez Capitol Records. L'album est enregistré au cours d'une tournée, de janvier à août 1971, dans plusieurs studios de Londres.","Meddle est le sixième album studio du groupe de rock anglais Pink Floyd, sorti le 30 octobre 1971 chez Capitol Records.","fr:Meddle","c:d/db/Meddle_Side_B%2C_Echoes.png"],["Q213516",360,"album","Metallica (album)","E","Metallica est le cinquième album studio du groupe de heavy metal éponyme sorti le 13 août 1991.",null,"fr:Metallica_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/2/2c/Metallica_-_Metallica_cover.jpg/330px-Metallica_-_Metallica_cover.jpg",{"cats":["chansons","groupes"]}],["Q19858",361,"album","Meteora","R","Meteora est le deuxième album studio du groupe américain de rock et de nu metal Linkin Park. Il est sorti le 25 mars 2003 sur le label Warner Bros. Records and Machine Shop Recordings, et fait suite à Reanimation, un album de collaboration contenant des remixes de chansons incluses dans leur premier album studio, Hybrid Theory. L'album a été produit par le groupe et Don Gilmore. Le titre Meteora est tiré des monastères orthodoxes grecs partageant le même nom.","Meteora est le deuxième album studio du groupe américain de rock et de nu metal Linkin Park.","fr:Meteora","https://upload.wikimedia.org/wikipedia/en/thumb/0/0c/Linkin_Park_Meteora_Album_Cover.jpg/330px-Linkin_Park_Meteora_Album_Cover.jpg",{"cats":["chansons","groupes"]}],["Q113640799",362,"album","Midnights","R","Midnights est le dixième album studio de l'auteure-compositrice-interprète américaine Taylor Swift, sorti le 21 octobre 2022 via Republic Records. Il est annoncé lors des MTV Video Music Awards 2022, marquant la première nouvelle œuvre de la chanteuse depuis ses albums folk indépendants de 2020, folklore et evermore. Midnights est un album concept explorant les méditations nocturnes et a été écrit et produit en collaboration avec son partenaire de longue date Jack Antonoff.",119,"fr:Midnights","https://upload.wikimedia.org/wikipedia/en/thumb/9/9f/Midnights_-_Taylor_Swift.png/330px-Midnights_-_Taylor_Swift.png"],["Q19855",363,"album","Minutes to Midnight","PC","Minutes to Midnight est le troisième album studio du groupe américain Linkin Park, sorti le 14 mai 2007 et le 15 mai 2007 en Amérique. Le nom de l'album fait référence à l'horloge de la fin du monde, une horloge représentant le nombre de minutes avant minuit, où minuit correspond à la destruction de la Terre par une guerre atomique. Initialement prévu pour l'été 2006, l'album est finalement commercialisé le 14 mai 2007. Il est produit par Rick Rubin, et coproduit par Mike Shinoda.",116,"fr:Minutes_to_Midnight","c:0/0d/Linkin_Park_minutes-to-midnight.png",{"cats":["chansons","groupes"]}],["Q48761101",364,"album","Mon pays c'est l'amour","C","Mon pays c'est l'amour est le 51e et dernier album studio de Johnny Hallyday. L'enregistrement de ce disque, débuté au printemps 2017 aux États-Unis, s'est poursuivi à l'automne en France, quelques semaines avant la mort du chanteur survenue le 5 décembre, et est resté inachevé. Réalisé par Yodelice et mixé par Bob Clearmountain, l'album est publié de manière posthume le 19 octobre 2018.","Mon pays c'est l'amour est le 51e et dernier album studio de Johnny Hallyday.","fr:Mon_pays_c'est_l'amour","c:4/40/Mon_pays_c%27est_l%27amour_%28Johnny_Hallyday_logo%29.png"],["Q214139",365,"album","Morrison Hotel","C","Morrison Hotel est le cinquième album du groupe de rock américain The Doors sorti le 9 février 1970 et produit par Paul A. Rothchild. Le titre de l'album, Morrison Hotel, provient d'un hôtel portant le nom du chanteur, par un pur hasard.",119,"fr:Morrison_Hotel","c:9/98/Doors_-_Morrison_Hotel.jpg"],["Q109409686",366,"album","Motomami","C","Motomami est le troisième album studio de la chanteuse espagnole Rosalía, sorti le 18 mars 2022.",null,"fr:Motomami","c:a/ad/Motomami_logo.png"],["Q1321558",367,"album","Mozart, l'opéra rock","C","Mozart, l'opéra rock est un spectacle musical français mis en scène par Olivier Dahan et produit par Dove Attia et Albert Cohen. Il retrace de façon romancée la vie de Wolfgang Amadeus Mozart, de son adolescence tumultueuse jusqu'à sa mort en 1791, à l'âge de trente-cinq ans.",114,"fr:Mozart,_l'opéra_rock","c:9/9b/213983_fr_dsc07688.jpg"],["Q110063250",368,"album","Multitude","C","Multitude est le troisième album studio du chanteur belge Stromae sorti le 4 mars 2022.",null,"fr:Multitude","c:8/8a/Stromae%2C_Rock_en_Seine_Festival_2022%2C_Paris_%2852391716210%29.jpg"],["Q208676",369,"album","Music of the Sun","C","Music of the Sun est le premier album de la chanteuse de R&B et pop Rihanna sorti sous le label Def Jam le 29 août 2005. Avant de signer un contrat, Rihanna est découverte par le producteur Evan Rogers qui aide Rihanna à faire des démos et à les envoyer aux labels. Après avoir signé un contrat pour le label Def Jam, Rihanna continue de travailler avec Rogers et son partenaire Carl Sturken pour son premier album. Music of the Sun est enregistré entre 2004 et 2005.","Music of the Sun est le premier album de la chanteuse de R&B et pop Rihanna sorti sous le label Def Jam le 29 août 2005.","fr:Music_of_the_Sun","https://upload.wikimedia.org/wikipedia/en/thumb/6/6e/Rihanna_-_Music_of_the_Sun.png/330px-Rihanna_-_Music_of_the_Sun.png"],["Q154601",370,"album","Mutter","C","Mutter est le troisième album studio du groupe de Neue Deutsche Härte, Rammstein. Il est sorti le 2 avril 2001 sur le label Motor Music Records et est produit par le producteur suédois Jacob Hellner.","Mutter est le troisième album studio du groupe de Neue Deutsche Härte, Rammstein.","fr:Mutter_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/5/5e/Mutter.jpg/330px-Mutter.jpg",{"cats":["chansons","groupes"]}],["Q547624",371,"album","My Beautiful Dark Twisted Fantasy","E","My Beautiful Dark Twisted Fantasy est le cinquième album studio de Kanye West, sorti le 22 novembre 2010 aux États-Unis.",null,"fr:My_Beautiful_Dark_Twisted_Fantasy","c:7/70/Kanye_West_Coachella_2011_6.jpg"],["Q58175139",372,"album","Nakamura","C","Nakamura est le deuxième album studio de la chanteuse malienne Aya Nakamura, sorti le 2 novembre 2018. L'album est publié par Rec. 118 et Parlophone, des labels de Warner Music France.","Nakamura est le deuxième album studio de la chanteuse malienne Aya Nakamura, sorti le 2 novembre 2018.","fr:Nakamura_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/9/92/Aya_Nakamura_-_Nakamura.jpg/330px-Aya_Nakamura_-_Nakamura.jpg"],["Q21971337",373,"album","Nero Nemesis","C","Nero Nemesis est le huitième album studio du rappeur français Booba sorti le 4 décembre 2015 sur le label Tallac Records, et distribué par Universal.",112,"fr:Nero_Nemesis","https://upload.wikimedia.org/wikipedia/en/thumb/2/2d/Booba-nero_nemesis.jpg/330px-Booba-nero_nemesis.jpg"],["Q17444",374,"album","Nevermind","L","Nevermind est le deuxième album studio du groupe américain de grunge Nirvana, sorti le 24 septembre 1991 par le label DGC Records. Kurt Cobain écrit et compose seul quasiment toutes les chansons de l'album et le groupe commence à enregistrer en avril 1990 avec le producteur Butch Vig mais la session est interrompue prématurément. Le batteur Chad Channing quitte ensuite le groupe et est remplacé par Dave Grohl.",117,"fr:Nevermind","c:1/11/Nirvana-Nevermind.png",{"cats":["chansons","groupes"]}],["Q309021",375,"album","News of the World","R","News of the World est le 6e album du groupe de rock britannique Queen, sorti en 1977. Cet album a été l'un des grands succès de Queen, grâce aux deux tubes We Will Rock You et We Are the Champions. Il a été décrit comme « le dernier album de la période classique » du groupe.","News of the World est le 6e album du groupe de rock britannique Queen, sorti en 1977.","fr:News_of_the_World_(album)","https://upload.wikimedia.org/wikipedia/fr/thumb/0/05/News_of_the_World_%28album%29.jpg/330px-News_of_the_World_%28album%29.jpg"],["Q2498352",376,"album","Night Visions","C","Night Visions est le premier album studio du groupe de rock alternatif américain Imagine Dragons, sorti le 4 septembre 2012.",118,"fr:Night_Visions_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/3/3f/Night_Visions_Album_Cover.jpeg/330px-Night_Visions_Album_Cover.jpeg"],["Q769086",377,"album","Notre-Dame de Paris","PC","Notre-Dame de Paris est une comédie musicale française, dont la première fut jouée le 16 septembre 1998 à Paris au Palais des congrès. Cette comédie musicale s'inspire du roman éponyme de Victor Hugo. Le parolier en est Luc Plamondon et le compositeur Richard Cocciante, avec une mise en scène de Gilles Maheu.",114,"fr:Notre-Dame_de_Paris_(comédie_musicale)","c:0/05/Le_salut_de_Notre_Dame_de_Paris.png"],["Q44289",378,"album","Off the Wall","E","Off the Wall est le cinquième album de Michael Jackson, paru le 10 août 1979. C'est le premier album du chanteur chez Epic Records. Sorti trois semaines avant le 21e anniversaire de Michael Jackson, Off the Wall marque sa première collaboration avec le producteur Quincy Jones. Les thèmes incluent notamment l'amour, la fête, l'évasion, la liberté ou encore la solitude.","Off the Wall est le cinquième album de Michael Jackson, paru le 10 août 1979.","fr:Off_the_Wall_(album)","c:c/cb/Off_The_Wall_Album_Logo2.png"],["Q202996",379,"album","OK Computer","E","OK Computer est le troisième album du groupe de rock alternatif britannique Radiohead. Sorti le 16 juin 1997 au Royaume-Uni et le 1er juillet aux États-Unis, il a été enregistré dans un manoir à Bath, ainsi que dans l'Oxfordshire.","OK Computer est le troisième album du groupe de rock alternatif britannique Radiohead.","fr:OK_Computer","https://upload.wikimedia.org/wikipedia/en/thumb/b/ba/Radioheadokcomputer.png/330px-Radioheadokcomputer.png"],["Q131977",380,"album","Parachutes","PC","Parachutes est le premier album du groupe de rock alternatif anglais Coldplay. Il est sorti en septembre 2000 en France, et le 7 juin 2000 au Royaume-Uni.","Parachutes est le premier album du groupe de rock alternatif anglais Coldplay.","fr:Parachutes_(album)","c:d/dd/Discograf%C3%ADa_Coldplay.jpg"],["Q271787",381,"album","Paranoid","R","Paranoid est le deuxième album studio du groupe rock britannique Black Sabbath sorti le 18 septembre 1970 au Royaume-Uni et le 1er janvier 1971 aux États-Unis. L'album a été produit par Rodger Bain aux studios Regent Sound & Island à Londres et fut enregistré en deux jours seulement.",108,"fr:Paranoid_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/6/64/Black_Sabbath_-_Paranoid.jpg/330px-Black_Sabbath_-_Paranoid.jpg",{"cats":["chansons","groupes"]}],["Q212863",382,"album","Pet Sounds","E","Pet Sounds est le onzième album studio du groupe de rock nord-américain The Beach Boys, sorti le 16 mai 1966 sur le label Capitol Records. L'album est souvent considéré comme l'un des plus influents de l'histoire de la musique pop, et comme l'un des tout meilleurs, avec des chansons comme Wouldn't It Be Nice ou God Only Knows. Pet Sounds est essentiellement un projet solo de Brian Wilson, créé après que Wilson a arrêté les tournées avec le groupe pour se concentrer sur l'écriture et l'enregistrement.",115,"fr:Pet_Sounds","c:1/1c/Pet_Sounds.jpg"],["Q210809",383,"album","Physical Graffiti","R","Physical Graffiti est un double album du groupe de rock britannique Led Zeppelin. Il est sorti le 24 février 1975 et a été produit par Jimmy Page. C'est leur sixième disque studio et le premier album produit sur le label Swan Song Records créé par Led Zeppelin.","Physical Graffiti est un double album du groupe de rock britannique Led Zeppelin.","fr:Physical_Graffiti","https://upload.wikimedia.org/wikipedia/en/thumb/e/e3/Led_Zeppelin_-_Physical_Graffiti.jpg/330px-Led_Zeppelin_-_Physical_Graffiti.jpg"],["Q181826",384,"album","Please Please Me","E","Please Please Me est le premier album des Beatles, paru le 22 mars 1963 au Royaume-Uni. Sa publication accompagne les débuts de la Beatlemania, après la sortie des deux premiers singles du groupe, Love Me Do en octobre 1962, suivi quatre mois plus tard de leur premier succès au sommet des hit-parades, la chanson Please Please Me.","Please Please Me est le premier album des Beatles, paru le 22 mars 1963 au Royaume-Uni.","fr:Please_Please_Me_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/2/2e/Please_Please_Me.png/330px-Please_Please_Me.png"],["Q253004",385,"album","Purple Rain (album)","R","Purple Rain est le sixième album studio du chanteur et musicien américain Prince. Écrit et interprété avec le groupe The Revolution, il est publié le 25 juin 1984 par Warner Bros. Ses ventes, certifiées à treize millions d'exemplaires aux États-Unis, sont estimées jusqu'à vingt-deux millions dans le monde. Par la synthèse qu'il réalise du rock, du rhythm and blues et de la musique électronique, comme par sa réputation critique et sa popularité, le disque est une pièce maîtresse de la culture musicale contemporaine.","Purple Rain est le sixième album studio du chanteur et musicien américain Prince.","fr:Purple_Rain_(album)","c:9/9c/Purple_Rain.png"],["Q99511935",386,"album","QALF","C","QALF est le quatrième album studio du rappeur belge Damso, sorti le 18 septembre 2020, réédité le 29 avril 2021 sous le nom QALF Infinity et le 28 octobre 2023 en QALF LIVE, sous le label Trente-quatre Centimes, label indépendant du rappeur.",119,"fr:QALF",""],["Q193490",387,"album","Queen","PC","Queen est le premier album du groupe de rock britannique éponyme Queen, sorti en 1973. Il prend le nom de Queen I lors de sa réédition en 2024.","Queen est le premier album du groupe de rock britannique éponyme Queen, sorti en 1973.","fr:Queen_(album)","https://upload.wikimedia.org/wikipedia/fr/thumb/d/d3/Queen_%28album%29.jpg/330px-Queen_%28album%29.jpg"],["Q223181",388,"album","Queen II","PC","Queen II est le second album du groupe de rock britannique Queen, sorti en 1974 sous l’étiquette EMI. Enregistré en 1973 aux Studios Trident à Londres, il a été co-produit par Roy Thomas Baker, Robin Cable et mixé par Mike Stone. Dès sa sortie, il est resté au palmarès britannique pendant 29 semaines, dont 11 semaines consécutives où il atteint la cinquième position au classement des meilleures ventes au Royaume-Uni avant de faire une réapparition en 2011.","Queen II est le second album du groupe de rock britannique Queen, sorti en 1974 sous l’étiquette EMI.","fr:Queen_II","https://upload.wikimedia.org/wikipedia/fr/thumb/a/ad/Queen_II.jpg/330px-Queen_II.jpg"],["Q14566706",389,"album","Racine carrée","R","Racine carrée est le deuxième album studio de l'auteur-compositeur-interprète belge Stromae sorti le 16 août 2013.",null,"fr:Racine_carrée_(album)","c:c/cc/Le_chanteur_Stromae.jpg",{"cats":["chansons","rap_fr"]}],["Q8119033",390,"album","Random Access Memories","R","Random Access Memories est le quatrième et dernier album studio du groupe français Daft Punk, sorti officiellement le 17 mai 2013. Il est publié par Daft Life Limited, une filiale de Columbia Records.",117,"fr:Random_Access_Memories","c:e/eb/Random_Access_Memories_title.gif"],["Q529999",391,"album","Ready to Die","PC","Ready to Die est le premier album studio de The Notorious B.I.G., sorti le 13 septembre 1994.",null,"fr:Ready_to_Die","https://upload.wikimedia.org/wikipedia/en/thumb/9/97/Ready_To_Die.jpg/330px-Ready_To_Die.jpg"],["Q858750",392,"album","Red","R","Red est le 4e album studio par l'artiste américaine country Taylor Swift. Il est sorti le 22 octobre 2012 sous Big Machine Records. À sa sortie, Red a été la plupart du temps acclamé par la critique musicale, qui a salué sa polyvalence en tant que musicienne, apprécié ses expériences avec de nouveaux genres musicaux et loué ses talents de compositrice.","Red est le 4e album studio par l'artiste américaine country Taylor Swift.","fr:Red_(album_de_Taylor_Swift)","c:6/62/Red_Taylor_Swift.png"],["Q715465",393,"album","ReLoad","PC","ReLoad est le 7e album du groupe de heavy metal américain Metallica. Il est sorti le 18 novembre 1997 sur le label Elektra Records et a été produit par Bob Rock, James Hetfield et Lars Ulrich. Il peut être considéré comme la seconde partie de Load, sorti un an plus tôt.","ReLoad est le 7e album du groupe de heavy metal américain Metallica.","fr:ReLoad","https://upload.wikimedia.org/wikipedia/en/thumb/9/9b/Metallica_-_Reload_cover.jpg/330px-Metallica_-_Reload_cover.jpg"],["Q112595827",394,"album","Renaissance","PC","Renaissance est le septième album studio de la chanteuse américaine Beyoncé, sorti le 29 juillet 2022 sous Parkwood Entertainment et Columbia Records. Il s'agit de son premier album studio depuis Lemonade, paru en 2016. Beyoncé a créé et enregistré Renaissance pendant la pandémie de Covid-19 dans le but d'inspirer à la fois la joie et la confiance aux auditeurs isolés pendant cette période.",115,"fr:Renaissance_(album_de_Beyoncé)","c:a/a5/Album_cover_for_Renaissance_by_Beyonc%C3%A9.jpg"],["Q37814092",395,"album","Reputation","R","Reputation est le sixième album de l'auteure-compositrice-interprète américaine Taylor Swift, sorti le 10 novembre 2017 sous le label Big Machine Records.",119,"fr:Reputation","https://upload.wikimedia.org/wikipedia/en/thumb/f/f2/Taylor_Swift_-_Reputation.png/330px-Taylor_Swift_-_Reputation.png"],["Q185121",396,"album","Revolver","L","Revolver est le septième album studio des Beatles, paru le 5 août 1966 au Royaume-Uni et trois jours plus tard aux États-Unis, avec une liste de chansons légèrement différente. Enregistré sur une période de trois mois, il est souvent considéré comme un album majeur de leur carrière et l'un des plus influents de tous les temps par les critiques, figurant entre autres à la onzième place dans la liste de 2020 des 500 plus grands albums de tous les temps du magazine Rolling Stone et à la troisième place, dans la liste…",114,"fr:Revolver_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/e/ec/Revolver_%28album_cover%29.jpg/330px-Revolver_%28album_cover%29.jpg"],["Q190989",397,"album","Ride the Lightning","E","Ride the Lightning est le deuxième album du groupe de thrash metal américain Metallica. Il est sorti le 27 juillet 1984 chez Megaforce Records et Music for Nations. Il est sorti chez Elektra Records le 19 novembre 1984 après que le groupe ait signé chez ces derniers en septembre 1984. Ride the Lightning a été vendu au fil des années à plus de six millions d'exemplaires rien qu'aux États-Unis et a été crédité sept fois disque de platine.","Ride the Lightning est le deuxième album du groupe de thrash metal américain Metallica.","fr:Ride_the_Lightning","https://upload.wikimedia.org/wikipedia/en/thumb/f/f4/Ridetl.png/330px-Ridetl.png"],["Q3437685",398,"album","Rock'n'Roll Attitude","C","Rock'n'Roll Attitude est le 34e album studio de Johnny Hallyday, sorti le 26 juin 1985.",null,"fr:Rock'n'Roll_Attitude","c:0/04/Rock%27n%27Roll_Attitude_%28Johnny_Hallyday_logo%29.png"],["Q190640",399,"album","Rubber Soul","M","Rubber Soul est le sixième album des Beatles, paru le 3 décembre 1965 au Royaume-Uni, et trois jours plus tard aux États-Unis. Produit par George Martin sous le label Parlophone, l'album est publié moins de trois mois après la sortie de Help!. Enregistré en seulement quatre semaines entre le 12 octobre et le 11 novembre 1965 aux studios EMI de Londres, l'album est pourtant le fruit d'un important travail d'écriture et de composition du duo Lennon/McCartney.",114,"fr:Rubber_Soul","https://upload.wikimedia.org/wikipedia/fr/thumb/5/5b/Rubber_Soul.png/330px-Rubber_Soul.png"],["Q695405",400,"album","Rumours","L","Rumours est le onzième album studio du groupe de rock Fleetwood Mac. Il est sorti le 4 février 1977 sur le label Warner Bros. Records et a été produit par le groupe, Ken Caillat et Richard Dashut. Il se classe à la septième place des albums les plus vendus au monde avec environ quarante millions d'unités écoulées en 2020.","Rumours est le onzième album studio du groupe de rock Fleetwood Mac.","fr:Rumours","https://upload.wikimedia.org/wikipedia/en/thumb/f/fb/FMacRumours.PNG/330px-FMacRumours.PNG"],["Q928132",401,"album","Saturday Night Fever","PC","Saturday Night Fever est la bande originale du film La Fièvre du samedi soir, composée en grande partie par les Bee Gees et sortie en novembre 1977.",115,"fr:Saturday_Night_Fever_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/0/0c/TheBeeGeesSaturdayNightFeveralbumcover.jpg/330px-TheBeeGeesSaturdayNightFeveralbumcover.jpg"],["Q55146346",402,"album","Scorpion","C","Scorpion est le cinquième album studio du rappeur canadien Drake, sorti en 2018 sur les labels OVO Sound, Young Money, Cash Money et Republic Records. Il s'agit d'un double album.",118,"fr:Scorpion_(album_de_Drake)","https://upload.wikimedia.org/wikipedia/en/thumb/9/90/Scorpion_by_Drake.jpg/330px-Scorpion_by_Drake.jpg"],["Q213578",403,"album","Sehnsucht","C","Sehnsucht est le deuxième album studio du groupe de Neue Deutsche Härte Rammstein. Il est sorti le 25 août 1997 sur le label Motor Music pour l'Europe, Slash Records pour l'Amérique du Nord, et a été produit par Jacob Hellner et le groupe.","Sehnsucht est le deuxième album studio du groupe de Neue Deutsche Härte Rammstein.","fr:Sehnsucht_(album_de_Rammstein)","https://upload.wikimedia.org/wikipedia/en/thumb/b/b0/Rammstein_-_Sehnsucht.jpg/330px-Rammstein_-_Sehnsucht.jpg"],["Q169226",404,"album","Sgt. Pepper's Lonely Hearts Club Band","M","Sgt. Pepper's Lonely Hearts Club Band est le huitième album studio des Beatles, publié le 1er juin 1967 au Royaume-Uni et en France et le jour suivant aux États-Unis et au Canada.","Sgt.","fr:Sgt._Pepper's_Lonely_Hearts_Club_Band_(album)","c:5/57/Sgt._Pepper%27s_Lonely_Hearts_Club_Band_album_art.jpg"],["Q219747",405,"album","Sheer Heart Attack","PC","Sheer Heart Attack est le 3e album studio du groupe de rock britannique Queen, sorti en 1974.",null,"fr:Sheer_Heart_Attack","https://upload.wikimedia.org/wikipedia/en/thumb/f/f4/Queen_Sheer_Heart_Attack.png/330px-Queen_Sheer_Heart_Attack.png"],["Q126327826",406,"album","Short n' Sweet","PC","Short n' Sweet est le sixième album studio de la chanteuse américaine Sabrina Carpenter. Il est sorti le 23 août 2024 chez Island Records, marquant le deuxième album de Carpenter avec le label après Emails I Can't Send. Album pop aux influences country, rock et R&B, Short n' Sweet a été produit par Jack Antonoff, John Ryan et Ian Kirkpatrick entre autres.","Short n' Sweet est le sixième album studio de la chanteuse américaine Sabrina Carpenter.","fr:Short_n'_Sweet","c:9/9d/Short_n_Sweet_logo.png"],["Q115271946",407,"album","SOS","PC","SOS est le deuxième album studio de la chanteuse américaine SZA, sorti le 9 décembre 2022.",null,"fr:SOS_(album_de_SZA)","https://upload.wikimedia.org/wikipedia/en/thumb/2/2c/SZA_-_S.O.S.png/330px-SZA_-_S.O.S.png"],["Q106316694",408,"album","Sour","R","Sour est le premier album de l'auteure-compositrice-interprète américaine Olivia Rodrigo, sorti le 21 mai 2021 chez Geffen Records.",115,"fr:Sour_(album)","c:8/82/Sour_album_logo.png"],["Q385122",409,"album","Speak Now","R","Speak Now est le troisième album studio par l'artiste américaine Taylor Swift. Il est sorti le 25 octobre 2010 sous le label indépendant Big Machine Records. L’enregistrement de l'album a lieu de 2008 à 2010 dans plusieurs studios d'enregistrement différents et est entièrement écrit de la main de Taylor Swift et produit par Nathan Chapman et elle-même. Speak Now représente des thèmes lyriques concernant l'amour, l’amitié, les chagrins d’amour et le temps qui passe.","Speak Now est le troisième album studio par l'artiste américaine Taylor Swift.","fr:Speak_Now_(album)","https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Taylor_Swift_-_Speak_Now.svg/330px-Taylor_Swift_-_Speak_Now.svg.png"],["Q152605",410,"album","Stadium Arcadium","PC","Stadium Arcadium est le neuvième album studio du groupe de rock américain Red Hot Chili Peppers. Il sort le 5 mai 2006, distribué par le label Warner Bros. Il s'agit du cinquième album consécutif produit par Rick Rubin, qui accompagne le groupe depuis 1991. Il contient cinq singles: Dani California, Tell Me Baby, Snow, Desecration Smile et Hump de Bump, ainsi que le tout premier clip officiel réalisé par des fans pour la chanson Charlie.","Stadium Arcadium est le neuvième album studio du groupe de rock américain Red Hot Chili Peppers.","fr:Stadium_Arcadium","https://upload.wikimedia.org/wikipedia/en/thumb/e/e6/Stadiumarcadium.jpg/330px-Stadiumarcadium.jpg"],["Q26980835",411,"album","Starboy","C","Starboy est le troisième album studio du chanteur canadien The Weeknd, sorti le 25 novembre 2016, publié sous les labels XO et Republic Records. Il comporte des collaborations avec les artistes Daft Punk, Lana Del Rey, Kendrick Lamar et Future. L'album est produit par Doc McKinney mais également par Diplo, Cashmere Cat, Metro Boomin, Frank Dukes, Labrinth, etc.",113,"fr:Starboy","https://upload.wikimedia.org/wikipedia/en/thumb/3/39/The_Weeknd_-_Starboy.png/330px-The_Weeknd_-_Starboy.png"],["Q924458",412,"album","Starmania","PC","Starmania est un opéra-rock franco-québécois composé par Michel Berger sur un livret de Luc Plamondon. Le spectacle est présenté pour la première fois le 10 avril 1979 au palais des congrès de Paris.","Starmania est un opéra-rock franco-québécois composé par Michel Berger sur un livret de Luc Plamondon.","fr:Starmania","c:4/41/Alex_Montembault_-_Starmania_01.jpg"],["Q212665",413,"album","Strange Days","C","Strange Days est le deuxième album du groupe américain The Doors, sorti le 25 septembre 1967 chez Elektra Records. Cet album fut un succès commercial, grimpant à la 3ème place des charts américains et raflant un Disque de Platine. Il contient deux singles ayant atteint le Top 30: People Are Strange et Love Me Two Times.","Strange Days est le deuxième album du groupe américain The Doors, sorti le 25 septembre 1967 chez Elektra Records.","fr:Strange_Days_(album)","c:d/db/Strange_Days_-_Billboard_ad_1967.jpg"],["Q3502571",414,"album","Subliminal","C","Subliminal est le premier album solo du rappeur congolais Maître Gims, sorti le 20 mai 2013 sur le label Wati B.",null,"fr:Subliminal_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/1/1a/Subliminal-album-by-maitre-gims.jpg/330px-Subliminal-album-by-maitre-gims.jpg"],["Q845783",415,"album","Taylor Swift","E","Taylor Swift est le premier album studio de la chanteuse de country pop américaine éponyme, Taylor Swift. Après la signature d'un contrat de disque en 2005, l'album est sorti le 24 octobre 2006 chez le label indépendant Big Machine Records alors que Taylor Swift n'avait que 16 ans.","Taylor Swift est le premier album studio de la chanteuse de country pop américaine éponyme, Taylor Swift.","fr:Taylor_Swift_(album)","c:6/6e/TaylorSwiftAlbum2006.png"],["Q186188",416,"album","Teenage Dream","PC","Teenage Dream est le troisième album studio de la chanteuse américaine Katy Perry. Il est sorti le 24 août 2010 en Amérique du Nord et le 30 août dans le reste du monde.","Teenage Dream est le troisième album studio de la chanteuse américaine Katy Perry.","fr:Teenage_Dream","c:d/dc/Teenage_dream_logo.png"],["Q664539",417,"album","The Bodyguard: Original Soundtrack Album","PC","The Bodyguard: Original Soundtrack Album est la bande originale du film Bodyguard, sortie en 1992. Elle a remporté en 1994 le Grammy Award de l'album de l'année.","The Bodyguard: Original Soundtrack Album est la bande originale du film Bodyguard, sortie en 1992.","fr:The_Bodyguard:_Original_Soundtrack_Album","https://upload.wikimedia.org/wikipedia/en/thumb/0/03/Whitney_Houston_-_The_Bodyguard.png/330px-Whitney_Houston_-_The_Bodyguard.png"],["Q749154",418,"album","The Chronic","PC","The Chronic est le premier album studio du rappeur-producteur américain Dr. Dre, sorti en 1992.","The Chronic est le premier album studio du rappeur-producteur américain Dr.","fr:The_Chronic","https://upload.wikimedia.org/wikipedia/en/thumb/1/19/Dr.DreTheChronic.jpg/330px-Dr.DreTheChronic.jpg"],["Q150901",419,"album","The Dark Side of the Moon","M","The Dark Side of the Moon est le huitième album studio du groupe britannique de rock progressif Pink Floyd, sorti le 1er mars 1973 aux États-Unis et le 23 mars 1973 au Royaume-Uni chez Harvest Records. Le groupe présente une première version de l'album, principalement développée lors de prestations en public, plusieurs mois avant le début de l'enregistrement.",116,"fr:The_Dark_Side_of_the_Moon","c:6/63/Dispersion_prism.jpg",{"cats":["chansons","groupes"]}],["Q208521",420,"album","The Division Bell","R","The Division Bell est le quatorzième album du groupe de rock progressif anglais, Pink Floyd. Il est sorti le 28 mars 1994 sur le label EMI, Columbia et a été produit par David Gilmour et Bob Ezrin.","The Division Bell est le quatorzième album du groupe de rock progressif anglais, Pink Floyd.","fr:The_Division_Bell","c:7/70/Expo_Pink_Floyd_-_Division_Bell.jpg"],["Q201949",421,"album","The Doors","PC","The Doors est le premier disque du groupe éponyme, sorti en janvier 1967.",null,"fr:The_Doors_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/9/98/TheDoorsTheDoorsalbumcover.jpg/330px-TheDoorsTheDoorsalbumcover.jpg"],["Q131182",422,"album","The Fame","PC","The Fame est le premier album studio de l’artiste américaine Lady Gaga. Sorti le 19 août 2008 sous le label Interscope, il est bâti par plusieurs producteurs incluant RedOne, Martin Kierszenbaum ainsi que Rob Fusari. Les chansons de l’album sont principalement inspirées par l’amour global que Gaga porte à la renommée en plus de traiter de sa vision personnelle des subtilités de la richesse et du mode de vie des célébrités.","The Fame est le premier album studio de l’artiste américaine Lady Gaga.","fr:The_Fame","c:c/cb/Gaga_Fame_Logo.png"],["Q164621",423,"album","The Fame Monster","PC","The Fame Monster est le deuxième album, commercialisé comme un EP de la chanteuse américaine Lady Gaga. Il sort le 18 novembre 2009 et contient huit chansons qui devaient à l'origine être ajoutées dans une réédition du premier album de Gaga, The Fame. Toutefois, après des pourparlers avec Interscope, le label de Gaga, l'album est vendu séparément et devient donc une œuvre autonome.","The Fame Monster est le deuxième album, commercialisé comme un EP de la chanteuse américaine Lady Gaga.","fr:The_Fame_Monster","https://upload.wikimedia.org/wikipedia/en/thumb/4/45/The_Fame_Monster.png/330px-The_Fame_Monster.png"],["Q208227",424,"album","The Final Cut","PC","The Final Cut est le douzième album studio du groupe rock progressif britannique Pink Floyd, sorti le 21 mars 1983 au Royaume-Uni.",117,"fr:The_Final_Cut_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/e/e4/FloydFC-Cover01.jpg/330px-FloydFC-Cover01.jpg"],["Q211405",425,"album","The Game","PC","The Game est le huitième album du groupe de rock britannique Queen, sorti en 1980.",null,"fr:The_Game_(album_de_Queen)","https://upload.wikimedia.org/wikipedia/fr/thumb/1/13/The_Game_%28album_de_Queen%29.jpg/330px-The_Game_%28album_de_Queen%29.jpg"],["Q152873",426,"album","The Joshua Tree","R","The Joshua Tree est le cinquième album studio du groupe de rock irlandais U2, sorti le 9 mars 1987 sous le label Island Records. Il est produit par le Canadien Daniel Lanois et l'Anglais Brian Eno. Le disque est réalisé dans différents studios dublinois ou lieux irlandais entre janvier 1986 et janvier 1987: aux STS Studios, à Danesmoate House, à Melbeach et aux Windmill Lane Studios. Il se compose de 11 chansons et sa durée d'écoute dépasse légèrement les 50 minutes.",119,"fr:The_Joshua_Tree","https://upload.wikimedia.org/wikipedia/en/thumb/6/6b/The_Joshua_Tree.png/330px-The_Joshua_Tree.png"],["Q153607",427,"album","The Marshall Mathers LP","R","The Marshall Mathers LP est le troisième album du rappeur Eminem enregistré en studio, si l'on compte Infinite. Cet album est sorti en 2000 sur le label Aftermath Entertainment de Dr. Dre. Il a remporté le Grammy Award du meilleur album de rap en 2001. Il s'est vendu à 27 millions d'exemplaires dans le monde. Grâce à cet album, Eminem décroche le record de ventes aux États-Unis sur une semaine pour un artiste solo avec 1,76 million de ventes.","The Marshall Mathers LP est le troisième album du rappeur Eminem enregistré en studio, si l'on compte Infinite.","fr:The_Marshall_Mathers_LP","https://upload.wikimedia.org/wikipedia/en/thumb/a/ae/The_Marshall_Mathers_LP.jpg/330px-The_Marshall_Mathers_LP.jpg"],["Q390295",428,"album","The Miracle","PC","The Miracle est le 13e album studio du groupe de rock britannique Queen, sorti en mai 1989. Enregistré après une longue période pendant laquelle le groupe avait mis ses activités en pause, Queen y affirme sa volonté de mettre en avant son unité en cosignant désormais officiellement toutes les chansons.","The Miracle est le 13e album studio du groupe de rock britannique Queen, sorti en mai 1989.","fr:The_Miracle_(album)","https://upload.wikimedia.org/wikipedia/fr/thumb/6/64/The_Miracle_%28album_de_Queen%29.jpg/330px-The_Miracle_%28album_de_Queen%29.jpg"],["Q945926",429,"album","The Miseducation of Lauryn Hill","PC","The Miseducation of Lauryn Hill est le premier et le seul album studio de Lauryn Hill sorti le 25 août 1998 sur le label Ruffhouse. L'album fut nommé dix fois aux Grammy Awards en 1999 et gagna cinq prix, dont celui du meilleur album de l'année. En date de 2008, l'album s'est vendu à plus de 18 millions de copies à travers le monde.",114,"fr:The_Miseducation_of_Lauryn_Hill","https://upload.wikimedia.org/wikipedia/en/thumb/9/99/The_Miseducation_of_Lauryn_Hill.png/330px-The_Miseducation_of_Lauryn_Hill.png"],["Q223858",430,"album","The Number of the Beast","R","The Number of the Beast est le troisième album studio du groupe britannique de heavy metal Iron Maiden, et est sorti le 22 mars 1982. L'album est le premier du groupe avec le nouveau chanteur Bruce Dickinson qui remplaça le défaillant Paul Di'Anno, et le dernier avec le batteur Clive Burr, qui sera remplacé par le batteur Nicko McBrain.",119,"fr:The_Number_of_the_Beast","https://upload.wikimedia.org/wikipedia/fr/thumb/5/56/The_Number_of_the_Beast.png/330px-The_Number_of_the_Beast.png",{"cats":["chansons","groupes"]}],["Q202714",431,"album","The Piper at the Gates of Dawn","R","The Piper at the Gates of Dawn est le premier album studio du groupe de rock progressif britannique Pink Floyd. Il est sorti le 5 août 1967 sur le label Columbia Records et a été produit par Norman Smith. Le titre de l'album est une référence au chapitre 7 du livre Le Vent dans les saules de Kenneth Grahame. Le disque est largement dominé par l'influence de Syd Barrett, dont les compositions évoquent l'espace ou les contes de fées.","The Piper at the Gates of Dawn est le premier album studio du groupe de rock progressif britannique Pink Floyd.","fr:The_Piper_at_the_Gates_of_Dawn","https://upload.wikimedia.org/wikipedia/en/thumb/3/3c/PinkFloyd-album-piperatthegatesofdawn_300.jpg/330px-PinkFloyd-album-piperatthegatesofdawn_300.jpg"],["Q217203",432,"album","The Soft Parade","C","The Soft Parade est le quatrième album du groupe californien The Doors, sorti le 18 juillet 1969.",null,"fr:The_Soft_Parade","https://upload.wikimedia.org/wikipedia/en/thumb/c/ce/The_Doors_-_The_Soft_Parade.jpg/330px-The_Doors_-_The_Soft_Parade.jpg"],["Q124426354",433,"album","The Tortured Poets Department","E","The Tortured Poets Department est le onzième album studio de l'auteure-compositrice-interprète américaine Taylor Swift, sorti le 19 avril 2024 chez Republic Records. Taylor Swift annonce son lancement lors de la 66e cérémonie des Grammy Awards, le 4 février 2024. Deux heures après sa sortie, elle révèle qu'il s'agit en réalité d'un double album et dévoile The Tortured Poets Department: The Anthology, qui compte 15 chansons supplémentaires.",119,"fr:The_Tortured_Poets_Department","c:2/24/The_Tortured_Poets_Department_Logo_v2.png"],["Q151114",434,"album","The Wall","L","The Wall est le onzième album studio du groupe britannique de rock progressif Pink Floyd et son second double album après Ummagumma. Enregistré sur une période de huit mois, l’album est sorti le 30 novembre 1979 en Grande-Bretagne et le 8 décembre de la même année aux États-Unis. Il figure dans la liste des 500 plus grands albums de tous les temps selon le magazine Rolling Stone et est le dernier grand succès du groupe.",115,"fr:The_Wall","https://upload.wikimedia.org/wikipedia/commons/thumb/b/b1/The_Wall_Cover.svg/330px-The_Wall_Cover.svg.png",{"cats":["chansons","groupes"]}],["Q224641",435,"album","The Works","PC","The Works est le onzième album studio du groupe de rock Queen, sorti le 27 février 1984. Coproduit par Queen et Reinhold Mack, il est enregistré sur une période de cinq mois, entre les Record Plant Studios de Los Angeles et les studios Musicland de Munich, dans une ambiance tendue. Il marque un certain retour de la formation à ses racines rock après ses expériences mitigées dans les genres funk et disco du début des années 1980.","The Works est le onzième album studio du groupe de rock Queen, sorti le 27 février 1984.","fr:The_Works_(album_de_Queen)","https://upload.wikimedia.org/wikipedia/en/thumb/3/39/Queen_The_Works.png/330px-Queen_The_Works.png"],["Q44320",436,"album","Thriller (album)","M","Thriller est le sixième album studio du chanteur et auteur-compositeur américain Michael Jackson et son deuxième chez Epic Records. Coproduit par Quincy Jones, qui avait déjà collaboré avec Jackson sur l’album Off the Wall en 1979, il sort le 30 novembre 1982.",117,"fr:Thriller_(album)","c:2/2b/Thriller_Album_Logo.png"],["Q19602856",437,"album","To Pimp a Butterfly","R","To Pimp a Butterfly est le troisième album studio du rappeur américain Kendrick Lamar. Il est sorti le 15 mars 2015, par Top Dawg Entertainment, Aftermath Entertainment et Interscope Records.","To Pimp a Butterfly est le troisième album studio du rappeur américain Kendrick Lamar.","fr:To_Pimp_a_Butterfly","https://upload.wikimedia.org/wikipedia/en/thumb/f/f6/Kendrick_Lamar_-_To_Pimp_a_Butterfly.png/330px-Kendrick_Lamar_-_To_Pimp_a_Butterfly.png"],["Q218971",438,"album","Toxicity","PC","Toxicity est le 2e album studio du groupe de heavy metal armeno-américain System of a Down, sorti le 4 septembre 2001 sur les labels American Recordings et Columbia Records. Retrouvant la puissance et le dynamisme de leur premier album homonyme de 1998, il contient toutefois plus de mélodies, d'harmonies et de chants que l'album précédents.",117,"fr:Toxicity_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/6/64/SystemofaDownToxicityalbumcover.jpg/330px-SystemofaDownToxicityalbumcover.jpg",{"cats":["chansons","groupes"]}],["Q39074516",439,"album","Trône","C","Trône, parfois orthographié Trōne, est le neuvième album studio du rappeur français Booba sorti le 1er décembre 2017 en format numérique et le 15 décembre 2017 en format physique, sur le label Tallac et distribué par 92i, Capitol, et Universal.",119,"fr:Trône_(album)",""],["Q109046199",440,"album","Ultra","C","Ultra est le dixième album studio du rappeur français Booba, sorti le 5 mars 2021.",null,"fr:Ultra_(album_de_Booba)",""],["Q206271",441,"album","Ummagumma","R","Ummagumma est le quatrième album du groupe rock progressif britannique Pink Floyd. Sorti le 25 octobre 1969 sur le label Harvest Records, il s'agit d'un double album, composé d'un disque issu de deux concerts du groupe et d'un disque studio.","Ummagumma est le quatrième album du groupe rock progressif britannique Pink Floyd.","fr:Ummagumma","https://upload.wikimedia.org/wikipedia/en/thumb/1/16/PinkFloyd-album-ummagummastudio-300.jpg/330px-PinkFloyd-album-ummagummastudio-300.jpg"],["Q158740",442,"album","Viva la Vida or Death and All His Friends","PC","Viva la vida or Death and All His Friends est le quatrième album studio du groupe de rock alternatif britannique Coldplay sorti le 12 juin 2008 au Royaume-Uni, le 13 juin en Suisse, le 16 juin en France et le 17 juin au Canada. Il s'agit de l'album le plus vendu dans le monde en 2008 avec 6,6 millions d'exemplaires vendus. En février 2009, Coldplay en avait vendu 7 millions.",112,"fr:Viva_la_Vida_or_Death_and_All_His_Friends","c:b/b2/Coldplay_-_Viva_la_Vida_or_Death_and_All_His_Friends.png"],["Q214134",443,"album","Waiting for the Sun","C","Waiting for the Sun est le troisième album du groupe The Doors, sorti le 3 juillet 1968. Enregistré aux studios TTG de Los Angeles entre février et mai 1968, il demeure le seul et unique numéro un du groupe et contient leur deuxième single numéro un Hello, I Love You. Le premier single issu de l'album fut The Unknown Soldier qui atteignit la 39ème place du Billboard Hot 100. Il est aussi le premier album du groupe à entrer dans les charts anglais où il grimpa à la 16ème place.","Waiting for the Sun est le troisième album du groupe The Doors, sorti le 3 juillet 1968.","fr:Waiting_for_the_Sun","https://upload.wikimedia.org/wikipedia/en/thumb/d/d3/The_Doors_-_Waiting_for_the_Sun.jpg/330px-The_Doors_-_Waiting_for_the_Sun.jpg"],["Q61157315",444,"album","When We All Fall Asleep, Where Do We Go?","PC","When We All Fall Asleep, Where Do We Go? est le premier album de longue durée de l'auteure-compositrice-interprète américaine Billie Eilish, co-composé et produit par son frère Finneas O'Connell et sorti le 29 mars 2019. L'album est enregistré dans le studio improvisé de la petite chambre de Finneas, dans la maison familiale située dans le quartier de Highland Park à Los Angeles.","When We All Fall Asleep, Where Do We Go?","fr:When_We_All_Fall_Asleep,_Where_Do_We_Go?","https://upload.wikimedia.org/wikipedia/en/thumb/3/38/When_We_All_Fall_Asleep%2C_Where_Do_We_Go%3F.png/330px-When_We_All_Fall_Asleep%2C_Where_Do_We_Go%3F.png"],["Q200872",445,"album","Wish You Were Here","L","Wish You Were Here est le neuvième album studio du groupe de rock britannique Pink Floyd. Il est sorti le 12 septembre 1975 chez Harvest Records et pour la première fois chez Columbia Records. Basé sur des titres que Pink Floyd a composés lors d'une tournée en 1974, Wish You Were Here est enregistré en 1975 aux studios Abbey Road à Londres.","Wish You Were Here est le neuvième album studio du groupe de rock britannique Pink Floyd.","fr:Wish_You_Were_Here_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/a/a4/Pink_Floyd%2C_Wish_You_Were_Here_%281975%29.png/330px-Pink_Floyd%2C_Wish_You_Were_Here_%281975%29.png"],["Q182389",446,"album","With the Beatles","R","With the Beatles est le deuxième album des Beatles, paru le 22 novembre 1963 en Grande-Bretagne. Il est enregistré dans la foulée de la sortie du single She Loves You, qui bat des records de vente alors que la Beatlemania est en plein essor. Au milieu des tournées en Europe, le groupe enregistre en sept journées de travail, étalées sur trois mois, quatorze chansons composées pour la moitié par le duo Lennon/McCartney pendant les tournées.","With the Beatles est le deuxième album des Beatles, paru le 22 novembre 1963 en Grande-Bretagne.","fr:With_the_Beatles","https://upload.wikimedia.org/wikipedia/en/thumb/5/52/With_the_Beatles.png/330px-With_the_Beatles.png"],["Q206097",447,"album","Yellow Submarine","R","Yellow Submarine est le dixième album studio des Beatles, paru le 13 janvier 1969 aux États-Unis et le 17 janvier en Grande-Bretagne. Il s'agit de la bande originale du film d'animation du même nom sorti en salles sept mois auparavant. Des treize morceaux de cet album, seulement six sont des Beatles, parmi lesquels quatre sont inédits. Les titres Yellow Submarine et All You Need Is Love ont en effet déjà été commercialisés auparavant.",116,"fr:Yellow_Submarine_(album)","https://upload.wikimedia.org/wikipedia/fr/thumb/c/c1/Yellow_Submarine_%28album%29.png/330px-Yellow_Submarine_%28album%29.png"],["Q28133332",448,"album","÷","C","÷ est le troisième album studio du chanteur Ed Sheeran sorti le 3 mars 2017 chez Asylum Records.",null,"fr:÷_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/4/45/Divide_cover.png/330px-Divide_cover.png"],["Q214973",449,"album","…And Justice for All","E","…And Justice for All est le quatrième album studio du groupe de thrash metal Metallica sorti le 25 août 1988 par Elektra Records.",112,"fr:…And_Justice_for_All_(album)","https://upload.wikimedia.org/wikipedia/en/thumb/b/bd/Metallica_-_...And_Justice_for_All_cover.jpg/330px-Metallica_-_...And_Justice_for_All_cover.jpg"],["Q190911",450,"album","…Baby One More Time (album)","PC","...Baby One More Time est le premier album de la chanteuse pop américaine Britney Spears. Sorti aux États-Unis le 12 janvier 1999, il est produit entre autres par Max Martin et Rami.","...Baby One More Time est le premier album de la chanteuse pop américaine Britney Spears.","fr:…Baby_One_More_Time_(album)","c:b/be/Babyonemoretimelogo.png"]]]);